package com.flipgoblin;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class FlipGoblinPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(FlipGoblinPlugin.class);
		RuneLite.main(args);
	}
}

package com.flipgoblin;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * A snapshot of what the player owns at one moment: a list of (itemId, quantity) entries
 * merged together from container contents.
 */
public final class AssetSnapshot
{
	public static final class Entry
	{
		public final int itemId;
		public final long qty;

		public Entry(int itemId, long qty)
		{
			this.itemId = itemId;
			this.qty = qty;
		}
	}

	/** Epoch ms the snapshot was taken. */
	public final long timestamp;
	public final List<Entry> entries;

	public AssetSnapshot(long timestamp, List<Entry> entries)
	{
		this.timestamp = timestamp;
		this.entries = entries;
	}

	/**
	 * Builds a snapshot from raw (id, quantity) container contents. Entries with an id or
	 * quantity of zero or less are skipped. When the same item appears more than once, its
	 * quantities are added together. Items keep the order they first appeared in.
	 */
	public static AssetSnapshot of(long timestamp, int[][]... containers)
	{
		return of(timestamp, 0, containers);
	}

	/**
	 * Same as {@link #of(long, int[][]...)}, but also counts coins that no container shows,
	 * such as coins held by the GE for an open buy offer. Takes a long because eight slots
	 * of escrow can add up to more than the max cash stack.
	 */
	public static AssetSnapshot of(long timestamp, long extraCoins, int[][]... containers)
	{
		Map<Integer, Long> merged = new LinkedHashMap<>();
		if (extraCoins > 0)
		{
			merged.put(ItemIds.COINS, extraCoins);
		}
		for (int[][] container : containers)
		{
			if (container == null)
			{
				continue;
			}
			for (int[] pair : container)
			{
				int id = pair[0];
				long qty = pair[1];
				if (id <= 0 || qty <= 0)
				{
					continue;
				}
				merged.merge(id, qty, Long::sum);
			}
		}
		List<Entry> entries = new ArrayList<>(merged.size());
		for (Map.Entry<Integer, Long> e : merged.entrySet())
		{
			entries.add(new Entry(e.getKey(), e.getValue()));
		}
		return new AssetSnapshot(timestamp, entries);
	}

	/** Converts the entries back to raw (id, quantity) pairs so a saved snapshot can be merged again. */
	public int[][] pairs()
	{
		int[][] out = new int[entries.size()][2];
		for (int i = 0; i < entries.size(); i++)
		{
			Entry e = entries.get(i);
			out[i][0] = e.itemId;
			out[i][1] = (int) Math.min(Integer.MAX_VALUE, e.qty);
		}
		return out;
	}

	public long totalStacks()
	{
		return entries.size();
	}

	/** The cash in the snapshot in gp: coins plus platinum tokens at 1,000 each. 0 if none are visible. */
	public long coins()
	{
		long gp = 0;
		for (Entry e : entries)
		{
			gp += ItemIds.cashValue(e.itemId) * e.qty;
		}
		return gp;
	}

	/**
	 * Estimates the snapshot's total value in gp. Coins and platinum tokens count at face
	 * value. Every other stack is valued at its live bid price minus GE tax. Stacks with no
	 * known bid price are left out of the total and counted instead. Returns {total gp,
	 * unpriced count}.
	 */
	public long[] estimateValue(Map<Integer, Long> bids)
	{
		long total = 0;
		long unpriced = 0;
		for (Entry e : entries)
		{
			long cash = ItemIds.cashValue(e.itemId);
			if (cash > 0)
			{
				total += cash * e.qty;
				continue;
			}
			Long bid = bids == null ? null : bids.get(e.itemId);
			if (bid == null)
			{
				unpriced++;
				continue;
			}
			total += SessionStats.netFromSale(bid, e.itemId) * e.qty;
		}
		return new long[]{total, unpriced};
	}
}

package com.flipgoblin;

import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import lombok.extern.slf4j.Slf4j;

/**
 * Schedules and sends assets-snapshot pushes. Never push eagerly, never drop: placing an
 * offer emits inventory-shrank and offer-escrow events milliseconds apart, and each
 * recomposes the snapshot. Pushing the first would publish a dipped total, and a plain
 * throttle would drop the corrected body, so the dip would sit on the dashboard until the
 * next game event. Instead every recompose lands in {@link #submit} and a single deferred
 * drain pushes whatever is newest once the burst settles. An offers change cancels a
 * far-out drain and reschedules it inside the fast window.
 */
@Slf4j
final class AssetsPusher
{
	/** Failed pushes retry on this cadence until the state converges. */
	static final long RETRY_MS = 10_000;

	/** The plugin-side sender. It owns the token and lock gates. */
	interface Sender
	{
		enum Result
		{
			OK, FAIL, DISABLED
		}

		Result send(String body);
	}

	private final ScheduledExecutorService executor;
	private final Sender sender;

	private volatile long lastPushMs;
	private volatile String lastBody;
	/** Newest composed snapshot not yet pushed. Latest wins; overwritten freely on every recompose. */
	private volatile String pendingBody;
	/** The scheduled drain, if any. Replaced when a faster window wants an earlier push. */
	private ScheduledFuture<?> drain;
	private final Object drainLock = new Object();

	AssetsPusher(ScheduledExecutorService executor, Sender sender)
	{
		this.executor = executor;
		this.sender = sender;
	}

	/** Takes the newest composed body and schedules a drain for it. */
	void submit(String body)
	{
		pendingBody = body;
		boolean offersChanged =
			!SyncClient.offersSection(body).equals(SyncClient.offersSection(lastBody));
		schedule(SyncClient.assetDrainDelayMs(offersChanged, lastPushMs, System.currentTimeMillis()));
	}

	/**
	 * Executor-side half: pushes the newest settled snapshot, change-detected. Bookkeeping
	 * is success-gated: recording the body as pushed before the HTTP call would let one
	 * failed push make the change detector drop that state forever. A failure leaves the
	 * state pending and retries.
	 */
	private void drainPending()
	{
		String body = pendingBody;
		if (body == null || body.equals(lastBody))
		{
			return;
		}
		long started = System.currentTimeMillis();
		Sender.Result result = sender.send(body);
		long took = System.currentTimeMillis() - started;
		if (result == Sender.Result.DISABLED)
		{
			return;
		}
		if (result == Sender.Result.OK)
		{
			lastPushMs = System.currentTimeMillis();
			lastBody = body;
			// Debug, not info: this fires up to once a minute for a whole linked session.
			log.debug("[{}] assets push ok in {}ms ({} chars)", FlipGoblinPlugin.BUILD, took, body.length());
			// The body may have moved on while the push was in flight. Drain the newer
			// state on the fast floor instead of waiting for the next game event.
			if (!body.equals(pendingBody))
			{
				schedule(1_000);
			}
			return;
		}
		log.info("[{}] assets push FAILED after {}ms, retrying in {}s", FlipGoblinPlugin.BUILD, took,
			RETRY_MS / 1000);
		schedule(RETRY_MS);
	}

	/** A best-effort synchronous drain, for shutdown. */
	void flushNow()
	{
		drainPending();
	}

	/** Schedules a drain {@code delay} ms out, unless an earlier one is already on its way. */
	private void schedule(long delay)
	{
		synchronized (drainLock)
		{
			if (drain != null && !drain.isDone()
				&& drain.getDelay(TimeUnit.MILLISECONDS) <= delay)
			{
				return;
			}
			if (drain != null)
			{
				drain.cancel(false);
			}
			drain = executor.schedule(this::drainPending, delay, TimeUnit.MILLISECONDS);
		}
	}
}

package com.flipgoblin;

import java.util.ArrayList;
import java.util.List;

/**
 * Corrects the stored bank snapshot when the GE pays for a buy offer out of the bank.
 * The client only sends the bank while it is open, so without this the snapshot keeps
 * coins the GE already took, and they count twice: in the bank and as the offer's escrow.
 */
final class BankDraw
{
	/** Ticks to wait after a buy is placed before reading the inventory, so its update has landed. */
	static final int SETTLE_TICKS = 2;

	private BankDraw()
	{
	}

	/**
	 * The part of a buy's cost that the inventory did not pay, so the bank paid it.
	 * Cash means coins plus platinum tokens in gp.
	 */
	static long shortfall(long cost, long invCashBefore, long invCashAfter)
	{
		long paidFromInventory = Math.max(0, invCashBefore - invCashAfter);
		return Math.max(0, cost - paidFromInventory);
	}

	/**
	 * Returns the snapshot with {@code gp} taken out of its cash: coins first, then platinum
	 * tokens, with the change from a token kept as coins. Takes no more than the snapshot holds.
	 */
	static AssetSnapshot withdraw(AssetSnapshot photo, long gp)
	{
		long coins = 0;
		long platinum = 0;
		List<AssetSnapshot.Entry> rest = new ArrayList<>();
		for (AssetSnapshot.Entry e : photo.entries)
		{
			if (e.itemId == ItemIds.COINS)
			{
				coins += e.qty;
			}
			else if (e.itemId == ItemIds.PLATINUM_TOKEN)
			{
				platinum += e.qty;
			}
			else
			{
				rest.add(e);
			}
		}
		long fromCoins = Math.min(coins, gp);
		coins -= fromCoins;
		long left = gp - fromCoins;
		if (left > 0 && platinum > 0)
		{
			long tokenGp = ItemIds.cashValue(ItemIds.PLATINUM_TOKEN);
			long tokens = Math.min(platinum, (left + tokenGp - 1) / tokenGp);
			platinum -= tokens;
			coins += Math.max(0, tokens * tokenGp - left);
		}
		List<AssetSnapshot.Entry> out = new ArrayList<>();
		if (coins > 0)
		{
			out.add(new AssetSnapshot.Entry(ItemIds.COINS, coins));
		}
		if (platinum > 0)
		{
			out.add(new AssetSnapshot.Entry(ItemIds.PLATINUM_TOKEN, platinum));
		}
		out.addAll(rest);
		return new AssetSnapshot(photo.timestamp, out);
	}
}

package com.flipgoblin;

import java.util.List;
import java.util.Map;

/**
 * Sums the other linked characters' stored data (recent fill history and last bank
 * snapshot) so the panel's "All characters" scope can show account-wide numbers beside
 * the live character's. Pure math; profile enumeration and JSON parsing stay in the plugin.
 *
 * Realized P/L is FIFO-matched per character and then summed. Record lists are never
 * merged into one match, because one character's buys must not price another's sells.
 * An offline character's inventory, equipment, and GE escrow are invisible here, so
 * callers label the aggregate "banks only".
 */
final class CharacterLedger
{
	/** One other character's parsed stores. Either part may be null or empty. */
	static final class Character
	{
		final String name;
		final List<TradeRecord> records;
		final AssetSnapshot bank;

		Character(String name, List<TradeRecord> records, AssetSnapshot bank)
		{
			this.name = name;
			this.records = records;
			this.bank = bank;
		}
	}

	/** The other characters' summed contribution. The live character renders separately. */
	static final class Totals
	{
		final int characters;
		/** Summed per-character realized P/L over fills inside the horizon. */
		final long realized7d;
		/** Summed bank snapshot values at the given bids. -1 means no bid map yet. */
		final long bankEst;
		/** Stacks the bid map could not price. These are left out of bankEst. */
		final long unpriced;
		/** Display names joined with " · ", for tooltips. */
		final String names;

		Totals(int characters, long realized7d, long bankEst, long unpriced, String names)
		{
			this.characters = characters;
			this.realized7d = realized7d;
			this.bankEst = bankEst;
			this.unpriced = unpriced;
			this.names = names;
		}
	}

	private CharacterLedger()
	{
	}

	/**
	 * Sums the other characters. The horizon filter is applied again at read time, because a
	 * stored history was trimmed when that character last saved (possibly days ago) and the
	 * panel's label promises 7 days from now. Pure.
	 */
	static Totals aggregate(List<Character> others, Map<Integer, Long> bids, long nowMs, long horizonMs)
	{
		long realized = 0;
		long bankEst = bids == null ? -1 : 0;
		long unpriced = 0;
		StringBuilder names = new StringBuilder();
		for (Character c : others)
		{
			if (names.length() > 0)
			{
				names.append(" · ");
			}
			names.append(c.name);
			if (c.records != null && !c.records.isEmpty())
			{
				List<TradeRecord> recent = new java.util.ArrayList<>(c.records.size());
				for (TradeRecord r : c.records)
				{
					if (r != null && r.timestamp >= nowMs - horizonMs)
					{
						recent.add(r);
					}
				}
				realized += SessionStats.match(recent).totalRealized;
			}
			if (c.bank != null && bids != null)
			{
				long[] v = c.bank.estimateValue(bids);
				bankEst += v[0];
				unpriced += v[1];
			}
		}
		return new Totals(others.size(), realized, bankEst, unpriced, names.toString());
	}
}

package com.flipgoblin;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Tracks what the GE collection box is holding for the player, per slot. The game API never
 * exposes this directly. It complements the working-offer escrow in {@link GePositions}.
 * Every uncertainty resolves downward (assume collected), so the ledger can never inflate
 * the total.
 *
 * It is fed from three sources, each covering the others' blind spots:
 * - Fill deltas from the offer stream, diffed here with the same identity rules as the
 *   differ. A buy fill adds bought stock. A sell fill adds proceeds net of tax. A
 *   cancellation adds the refund: unfilled escrow coins for a buy, unsold stock for a
 *   sell.
 * - The collection box widget via {@link #resyncAll}, authoritative while visible.
 * - Collect clicks via {@link #zeroAll}: any witnessed collect empties the ledger, and the
 *   next widget glance restores whatever actually remains.
 *
 * The first sighting of an offer (login replay or slot reuse) only records a baseline and
 * counts nothing. Offline fills enter only through {@link #applyFill}, which the caller
 * gates on an ACQUITTED custody verdict. An EMPTY slot means collected, and its entry dies.
 *
 * Pure and single-threaded (client thread), like the differ and GePositions.
 */
final class CollectLedger
{
	/** One slot's uncollected contents. Plain fields so Gson can round-trip it. */
	static final class Entry
	{
		int itemId;
		int items; // uncollected item qty (bought stock / returned unsold stock)
		long coins; // uncollected coins (net sell proceeds / cancelled-buy refund)

		boolean isEmpty()
		{
			return items <= 0 && coins <= 0;
		}
	}

	/** The previous offer state per slot, for diffing. Session-local and never saved: a fresh
	 *  session must treat the login replay as a first sighting, and offline fills arrive
	 *  through applyFill instead. */
	private static final class Prev
	{
		final int itemId;
		final TradeRecord.Side side;
		final int totalQuantity;
		final long price;
		final int quantitySold;
		final long spent;
		final GePositions.Phase phase;

		Prev(OfferSnapshot s)
		{
			this.itemId = s.itemId;
			this.side = OfferStates.sideOf(s.state);
			this.totalQuantity = s.totalQuantity;
			this.price = s.price;
			this.quantitySold = s.quantitySold;
			this.spent = s.spent;
			this.phase = OfferStates.phaseOf(s.state);
		}
	}

	private final Map<Integer, Entry> entries = new HashMap<>();
	private final Map<Integer, Prev> prevs = new HashMap<>();

	/** Folds in one offer event. Returns true when the ledger changed, so the caller can save. */
	boolean onOffer(int slot, OfferSnapshot next, long ignoredTs)
	{
		if (next.state == GrandExchangeOfferState.EMPTY)
		{
			prevs.remove(slot);
			return entries.remove(slot) != null;
		}
		Prev prev = prevs.get(slot);
		prevs.put(slot, new Prev(next));
		if (prev == null)
		{
			// First sighting this session (login replay or plugin enable): baseline, count
			// nothing. A restored entry for this slot stays, unless the replayed offer is not
			// the one the entry belongs to. Then we missed an EMPTY, so drop the entry.
			Entry e = entries.get(slot);
			if (e != null && e.itemId != next.itemId)
			{
				entries.remove(slot);
				return true;
			}
			return false;
		}
		boolean sameOffer = OfferStates.sameOffer(prev.itemId, prev.side,
			prev.totalQuantity, prev.price, prev.quantitySold, prev.spent, next);
		if (!sameOffer)
		{
			// The slot was reused without a witnessed EMPTY, so whatever the old entry held
			// was collected while we blinked. Assume collected. The new offer starts clean.
			return entries.remove(slot) != null;
		}
		boolean changed = false;
		int qtyDelta = next.quantitySold - prev.quantitySold;
		if (qtyDelta > 0)
		{
			Entry e = entryFor(slot, next.itemId);
			if (prev.side == TradeRecord.Side.BUY)
			{
				e.items += qtyDelta;
			}
			else
			{
				// Net of tax. The offer's spent counter is gross for sells.
				e.coins += SessionStats.netFromSale(next.price, next.itemId) * qtyDelta;
			}
			changed = true;
		}
		if (prev.phase == GePositions.Phase.WORKING && OfferStates.phaseOf(next.state) == GePositions.Phase.CANCELLED)
		{
			// The machine moves the remainder into the collection box on cancel.
			int remainder = next.totalQuantity - next.quantitySold;
			if (remainder > 0)
			{
				Entry e = entryFor(slot, next.itemId);
				if (prev.side == TradeRecord.Side.BUY)
				{
					e.coins += next.price * (long) remainder; // unfilled escrow refund
				}
				else
				{
					e.items += remainder; // unsold stock returns
				}
				changed = true;
			}
		}
		return changed;
	}

	/**
	 * Counts an offline fill discovered at login. The caller gates this on an ACQUITTED
	 * custody verdict: nothing can touch the collection box while logged out, so acquittal
	 * proves the fill is still held by the GE.
	 */
	void applyFill(TradeRecord r)
	{
		Entry e = entryFor(r.slot, r.itemId);
		if (r.side == TradeRecord.Side.BUY)
		{
			e.items += r.quantity;
		}
		else
		{
			e.coins += SessionStats.netFromSale(r.price, r.itemId) * (long) r.quantity;
		}
	}

	/**
	 * Replaces the whole ledger with exactly what the open collection box shows, one
	 * {itemId, itemQty, coins} triple per slot-shaped widget, keyed by detection order.
	 * This heals drift in both directions. Detection-order keys are fine because every
	 * later consumer either matches by item, zeroes everything, or is this same poll on
	 * the next tick. Returns true when the ledger changed.
	 */
	boolean resyncAll(List<long[]> boxes)
	{
		Map<Integer, Entry> next = new HashMap<>();
		int key = 0;
		for (long[] b : boxes)
		{
			if (b[1] <= 0 && b[2] <= 0)
			{
				continue;
			}
			Entry e = new Entry();
			e.itemId = (int) b[0];
			e.items = (int) b[1];
			e.coins = b[2];
			next.put(key++, e);
		}
		if (sameEntries(entries, next))
		{
			return false;
		}
		entries.clear();
		entries.putAll(next);
		return true;
	}

	/**
	 * Witnesses one viewed slot's pending boxes from the GE offer-detail view. Before the
	 * witnessed state lands, any entry holding the same item under a different key is
	 * dropped, so a duplicate can never survive a glance. The rare twin-offer case deflates
	 * and heals at the next collection-box open. Returns true when the ledger changed.
	 */
	boolean resyncViewed(int slot, int itemId, int itemQty, long coins)
	{
		boolean changed = false;
		if (itemId > 0)
		{
			java.util.Iterator<Map.Entry<Integer, Entry>> it = entries.entrySet().iterator();
			while (it.hasNext())
			{
				Map.Entry<Integer, Entry> me = it.next();
				if (me.getKey() != slot && me.getValue().itemId == itemId)
				{
					it.remove();
					changed = true;
				}
			}
		}
		Entry cur = entries.get(slot);
		if (itemQty <= 0 && coins <= 0)
		{
			return (entries.remove(slot) != null) || changed;
		}
		if (cur != null && cur.itemId == itemId && cur.items == itemQty && cur.coins == coins)
		{
			return changed;
		}
		Entry e = new Entry();
		e.itemId = itemId;
		e.items = itemQty;
		e.coins = coins;
		entries.put(slot, e);
		return true;
	}

	private static boolean sameEntries(Map<Integer, Entry> a, Map<Integer, Entry> b)
	{
		if (a.size() != b.size())
		{
			return false;
		}
		for (Map.Entry<Integer, Entry> me : a.entrySet())
		{
			Entry o = b.get(me.getKey());
			if (o == null || o.itemId != me.getValue().itemId || o.items != me.getValue().items
				|| o.coins != me.getValue().coins)
			{
				return false;
			}
		}
		return true;
	}

	/** Handles a witnessed collect the inventory delta cannot follow, such as Collect-to-bank.
	 *  Err low and zero everything. The next widget glance restores what actually remains.
	 *  Returns true when the ledger changed. */
	boolean zeroAll()
	{
		boolean changed = !entries.isEmpty();
		entries.clear();
		return changed;
	}

	/**
	 * Consumes a witnessed collect-to-inventory by decrementing entries by what actually
	 * arrived, in slot order. This can only move the ledger down and never below zero, so a
	 * partial collect (a full inventory, or the max cash stack) leaves exactly the remainder
	 * the box still holds. Arrivals that match no entry are ignored, since they are not ours
	 * to explain. Returns true when the ledger changed.
	 */
	boolean applyCollectDelta(Map<Integer, Integer> arrivedItems, long arrivedCoins)
	{
		boolean changed = false;
		List<Integer> slots = new ArrayList<>(entries.keySet());
		java.util.Collections.sort(slots); // the client collects in slot order
		for (int slot : slots)
		{
			Entry e = entries.get(slot);
			Integer arrived = arrivedItems.get(e.itemId);
			if (arrived != null && arrived > 0 && e.items > 0)
			{
				int take = Math.min(e.items, arrived);
				e.items -= take;
				arrivedItems.put(e.itemId, arrived - take);
				changed = true;
			}
			if (arrivedCoins > 0 && e.coins > 0)
			{
				long take = Math.min(e.coins, arrivedCoins);
				e.coins -= take;
				arrivedCoins -= take;
				changed = true;
			}
			if (e.isEmpty())
			{
				entries.remove(slot);
			}
		}
		return changed;
	}

	/**
	 * The positive (id → quantity gained) differences between two inventory dumps, which is
	 * what a collect delivered. Coins ride under the coin item id like everywhere else.
	 * Pure; null containers read as empty.
	 */
	static Map<Integer, Integer> arrivals(int[][] before, int[][] after)
	{
		Map<Integer, Integer> delta = new HashMap<>();
		if (after != null)
		{
			for (int[] p : after)
			{
				delta.merge(p[0], p[1], Integer::sum);
			}
		}
		if (before != null)
		{
			for (int[] p : before)
			{
				delta.merge(p[0], -p[1], Integer::sum);
			}
		}
		delta.values().removeIf(v -> v <= 0);
		return delta;
	}

	/** Wipes everything, baselines included. Used when a new login starts a fresh custody window. */
	void reset()
	{
		entries.clear();
		prevs.clear();
	}

	/** Uncollected coins across all slots: net-of-tax proceeds plus refunds. */
	long coins()
	{
		long sum = 0;
		for (Entry e : entries.values())
		{
			sum += e.coins;
		}
		return sum;
	}

	/** Uncollected item stacks as (itemId, quantity) pairs, for the asset total. */
	int[][] itemPairs()
	{
		List<int[]> pairs = new ArrayList<>();
		for (Entry e : entries.values())
		{
			if (e.items > 0)
			{
				pairs.add(new int[]{e.itemId, e.items});
			}
		}
		return pairs.toArray(new int[0][]);
	}

	/** The saveable uncollected state. Entries only; baselines are session-local by design. */
	Map<Integer, Entry> snapshotEntries()
	{
		return new HashMap<>(entries);
	}

	/**
	 * Restores saved entries. The caller gates this on an ACQUITTED custody verdict. This is
	 * a merge: a slot the live session already touched keeps its live entry, and the seed
	 * only fills untouched slots, so restoring can never overwrite something witnessed this
	 * session. A null or empty seed restores nothing.
	 */
	void seedEntries(Map<Integer, Entry> seed)
	{
		if (seed == null)
		{
			return;
		}
		for (Map.Entry<Integer, Entry> me : seed.entrySet())
		{
			if (me.getValue() != null && !me.getValue().isEmpty() && !entries.containsKey(me.getKey()))
			{
				entries.put(me.getKey(), me.getValue());
			}
		}
	}

	private Entry entryFor(int slot, int itemId)
	{
		Entry e = entries.get(slot);
		if (e == null || e.itemId != itemId)
		{
			e = new Entry();
			e.itemId = itemId;
			entries.put(slot, e);
		}
		return e;
	}

}

package com.flipgoblin;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Shows the custody verdict on the welcome screen: the screen's reported duration, our own
 * recorded gap, and the verdict, e.g. "last login 1h01m ago · ours 1h02m → ACQUITTED".
 * Unparseable text is shown too, as "unparsed → AMBIGUOUS", so a parser failure is visible
 * rather than silent. ALWAYS_ON_TOP matters: the game is already logged in while the
 * welcome screen is up, and the fullscreen welcome interface draws over every lower overlay
 * layer. The banner disappears with the screen.
 */
public class CustodyOverlay extends OverlayPanel
{
	private static final Color GOLD = new Color(0xd4, 0xaf, 0x37);
	private static final Color ACQUIT = new Color(0x3f, 0xb9, 0x50);
	private static final Color CONVICT = new Color(0xf8, 0x51, 0x49);
	private static final Color AMBIG = new Color(0xe8, 0xa0, 0x33);

	private final FlipGoblinPlugin plugin;

	@Inject
	CustodyOverlay(FlipGoblinPlugin plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		String detail = plugin.custodyOverlayDetail();
		LoginCustody.Verdict verdict = plugin.custodyOverlayVerdict();
		if (detail == null || verdict == null || !plugin.welcomeScreenVisible())
		{
			return null;
		}
		Color color = verdict == LoginCustody.Verdict.ACQUITTED ? ACQUIT
			: verdict == LoginCustody.Verdict.CONVICTED ? CONVICT : AMBIG;
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Flip Goblin " + FlipGoblinPlugin.BUILD + " custody").color(GOLD).build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left(detail).leftColor(Color.WHITE)
			.right("→ " + verdict).rightColor(color)
			.build());
		panelComponent.setPreferredSize(new Dimension(280, 0));
		return super.render(graphics);
	}
}

package com.flipgoblin;

import com.google.gson.Gson;
import java.time.Instant;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;

/**
 * The login-custody state machine. It records when our sessions end, compares each fresh
 * login's welcome-screen report against that record ({@link LoginCustody} holds the pure
 * parse and judge), and carries the verdict, the banner state, and the bank-trust chain
 * that the overlays and the asset ledger read.
 *
 * All mutation happens on the client thread. The volatile fields feed render threads.
 * The plugin forwards the raw events and reacts to the two {@link Host} callbacks; the
 * consequences for the collect ledger live there, not here.
 */
@Slf4j
final class CustodyTracker
{
	/** What the plugin does with custody outcomes. Both run on the client thread. */
	interface Host
	{
		/** A real fresh login started a new custody window. Reset the un-judged state. */
		void onNewCustodyWindow();

		/** The judge ran. Apply the acquittal payoff, or the assume-collected floor. */
		void onJudged(boolean acquitted);
	}

	private static final String SESSION_KEY = "sessionRecord";

	private final ConfigManager configManager;
	private final Gson gson;
	private final ChatMessageManager chatMessageManager;
	private final Host host;

	/** This session's record (mutable; heartbeat-saved). Null until first tick/login. */
	private LoginCustody.SessionRecord sessionRecord;
	/** The previous session's record, captured at fresh login before the store is overwritten. */
	private LoginCustody.SessionRecord prevSession;
	private boolean prevSessionLoaded;
	/** True only when the login came through the login screen. A CONNECTION_LOST reconnect
	 * skips it, shows no welcome screen, and must keep the session's custody state. */
	private boolean wasAtLoginScreen;
	private long lastHeartbeatMs;
	/** Wall-clock of the last GameTick, the only trustworthy "session was alive" instant. A
	 * frozen or disconnected client can sit logged in for an hour without ticks, so logout
	 * witnesses must anchor here, never on when handlers ran. */
	private long lastGameTickMs;
	/** Welcome-screen capture. WidgetLoaded and LOGGED_IN can arrive in either order, so the
	 * text is stashed and the judge runs when both halves are in (see maybeJudge). */
	private boolean welcomeLoaded;
	private String welcomeText;
	/** The instant the welcome text was read, and the judge's time anchor. The screen's
	 * "…ago" string is static while the user sits at the play button, so a judge that runs
	 * later must compare durations at capture time, not at its own clock. Every idle minute
	 * would otherwise read as phantom skew on our side only. */
	private long welcomeCapturedMs;
	private boolean judged;
	private boolean consoleQueued;
	private volatile boolean welcomeVisible;
	private volatile String detail;
	private volatile LoginCustody.Verdict verdict;
	/** The main-overlay banner window. Overlays cannot draw before the LOGGED_IN state, so a
	 * welcome screen shown before it never gets the CustodyOverlay. The verdict therefore
	 * also rides the main overlay for the first minute in-world, which is always drawable. */
	private volatile long bannerUntilMs;
	/** The bank snapshot's custody chain: set at bank-open, and it survives a logout only
	 * through an ACQUITTED verdict. While true, the stored bank counts in the estimate and
	 * syncs carry bankFresh=true, so history flows immediately with no bank-open gate. */
	private volatile boolean bankChainTrusted;

	CustodyTracker(ConfigManager configManager, Gson gson, ChatMessageManager chatMessageManager, Host host)
	{
		this.configManager = configManager;
		this.gson = gson;
		this.chatMessageManager = chatMessageManager;
		this.host = host;
	}

	/** Seeds the login-screen flag when the plugin comes up already at the login screen. */
	void seedAtStartUp(boolean atLoginScreen)
	{
		wasAtLoginScreen = atLoginScreen;
	}

	/**
	 * The per-tick heartbeat. lastSeen is our logout witness for crash exits; a clean
	 * logout stamps it exactly. Staleness only makes the next login's check stricter,
	 * which is the safe direction. Returns true when the 60-second save just fired, so
	 * the caller can piggyback its own staleness saves.
	 */
	boolean heartbeat(long now)
	{
		lastGameTickMs = now;
		if (now - lastHeartbeatMs < 60_000)
		{
			return false;
		}
		lastHeartbeatMs = now;
		if (sessionRecord == null)
		{
			// Plugin enabled mid-session: login instants unknown (0). The next login judges
			// AMBIGUOUS off this record, which is the honest floor.
			sessionRecord = new LoginCustody.SessionRecord();
		}
		sessionRecord.lastSeenMs = now;
		persistSessionRecord();
		return true;
	}

	/**
	 * Leaving the world (login screen or hop): stamp the logout instant and drop the
	 * welcome stash. The verdict and chain stay in memory across a hop; a real logout's
	 * next fresh login resets them in {@link #onLogin}.
	 */
	void onLeaveWorld(boolean toLoginScreen)
	{
		wasAtLoginScreen |= toLoginScreen;
		welcomeVisible = false;
		welcomeLoaded = false;
		welcomeText = null;
		welcomeCapturedMs = 0;
		if (sessionRecord != null)
		{
			// Logout witness = the last real tick, never "now": the login screen can appear
			// an hour after a silent connection death (frozen client, machine sleep), and
			// stamping wall-clock then destroys the witness the judge needs. Clean logouts
			// tick until the last moment, so anchoring on the tick costs under a second of
			// precision there. If no tick was ever seen this process, keep whatever the
			// record already holds.
			if (lastGameTickMs > 0)
			{
				sessionRecord.lastSeenMs = lastGameTickMs;
			}
			persistSessionRecord();
		}
	}

	/**
	 * A login landed. Only a real fresh login (through the login screen) starts a new
	 * custody window: capture the previous session's record before overwriting it, reset
	 * the verdict, and judge once the welcome text is in (either event order). A
	 * CONNECTION_LOST reconnect also lands here but shows no welcome screen; it keeps the
	 * session's verdict and chain and just stamps the re-login.
	 */
	void onLogin()
	{
		if (!wasAtLoginScreen)
		{
			recordLogin(false);
			return;
		}
		wasAtLoginScreen = false;
		prevSession = loadSessionRecord();
		prevSessionLoaded = true;
		judged = false;
		consoleQueued = false;
		verdict = null;
		detail = null;
		bankChainTrusted = false; // gated until the judge (or a bank-open) says otherwise
		host.onNewCustodyWindow();
		sessionRecord = new LoginCustody.SessionRecord();
		recordLogin(true);
		maybeJudge();
	}

	/** Stamps a login instant. Hops and reconnects stamp any-login; a fresh login also sets fresh. */
	void recordLogin(boolean freshLogin)
	{
		long now = Instant.now().toEpochMilli();
		if (sessionRecord == null)
		{
			sessionRecord = new LoginCustody.SessionRecord();
		}
		sessionRecord.anyLoginMs = now;
		sessionRecord.lastSeenMs = now;
		if (freshLogin)
		{
			sessionRecord.freshLoginMs = now;
		}
		persistSessionRecord();
	}

	/** The welcome screen loaded; its text is provably populated at WidgetLoaded time. */
	void onWelcomeLoaded(String text)
	{
		welcomeVisible = true;
		welcomeLoaded = true;
		welcomeText = text;
		welcomeCapturedMs = Instant.now().toEpochMilli();
		maybeJudge();
	}

	/** Click-through: the login-screen overlay stops with the screen; the console mirror fires once. */
	void onWelcomeClosed()
	{
		welcomeVisible = false;
		if (judged)
		{
			// Re-arm the main-overlay banner from click-through: the judge fires when the
			// welcome screen loads, so idling at the play button would otherwise burn the
			// banner window before the player ever enters the world.
			bannerUntilMs = System.currentTimeMillis() + 60_000;
			queueConsole();
		}
	}

	/** Witnessing the bank restarts its custody chain from this moment. */
	void trustBankChain()
	{
		bankChainTrusted = true;
		persistSessionRecord();
	}

	boolean bankChainTrusted()
	{
		return bankChainTrusted;
	}

	/** True once this login's judge has run (or a reconnect kept the previous run). */
	boolean judged()
	{
		return judged;
	}

	// --- overlay reads (render thread; the fields are volatile, written on the client thread) ---

	String overlayDetail()
	{
		return detail;
	}

	LoginCustody.Verdict overlayVerdict()
	{
		return verdict;
	}

	boolean welcomeScreenVisible()
	{
		return welcomeVisible;
	}

	/** True while the main overlay should carry the custody banner (first minute in-world). */
	boolean bannerActive()
	{
		return verdict != null && System.currentTimeMillis() < bannerUntilMs;
	}

	/**
	 * The judgement, run exactly once per fresh login when both halves are in: the
	 * previous session record (loaded at login) and the welcome screen text. The two
	 * events' order is not guaranteed, so each caller retries the join. ACQUITTED carries
	 * the bank chain across the logout; anything else keeps the gated regime until the
	 * first bank-open. Client thread.
	 */
	private void maybeJudge()
	{
		if (judged || !prevSessionLoaded || !welcomeLoaded)
		{
			return;
		}
		judged = true;
		long now = Instant.now().toEpochMilli();
		// Anchor at text-capture time, never judge time: the "…ago" string froze when the
		// screen rendered (see welcomeCapturedMs).
		long anchor = welcomeCapturedMs > 0 ? welcomeCapturedMs : now;
		LoginCustody.Report report = LoginCustody.parse(welcomeText);
		LoginCustody.Result result = LoginCustody.judge(report, prevSession, anchor);
		boolean acquitted = result.verdict == LoginCustody.Verdict.ACQUITTED;
		bankChainTrusted = acquitted && prevSession != null && prevSession.bankChainTrusted;
		persistSessionRecord();
		String ours = result.ourAgoMs <= 0 ? "?" : LoginCustody.fmtDuration(result.ourAgoMs);
		// "ended", not "last login": the report measures the previous session's END (see
		// LoginCustody), so label both sides for what they are.
		detail = report == null
			? (welcomeText == null ? "no last-login line" : "unparsed") + " · our logout " + ours
			: "ended " + LoginCustody.fmtDuration(report.agoMs) + " ago · our logout " + ours;
		verdict = result.verdict;
		bannerUntilMs = System.currentTimeMillis() + 60_000;
		log.info("[{}] custody: {} → {} (raw=\"{}\", judged {}s after capture, prevAny={}, prevFresh={}, prevSeen={}, chain={})",
			FlipGoblinPlugin.BUILD, detail, result.verdict, welcomeText, (now - anchor) / 1000,
			prevSession == null ? 0 : prevSession.anyLoginMs,
			prevSession == null ? 0 : prevSession.freshLoginMs,
			prevSession == null ? 0 : prevSession.lastSeenMs, bankChainTrusted);
		if (!welcomeVisible)
		{
			queueConsole(); // click-through beat the judge; don't lose the mirror line
		}
		host.onJudged(acquitted);
	}

	/** The one console mirror line per login. It lands in client.log for correlation. */
	private void queueConsole()
	{
		if (consoleQueued || verdict == null)
		{
			return;
		}
		consoleQueued = true;
		String meaning = verdict == LoginCustody.Verdict.ACQUITTED
			? "last session was ours"
			: verdict == LoginCustody.Verdict.CONVICTED
				? "someone was online after our last session (another client or mobile?)"
				: "can't prove the last session was ours";
		String gate = bankChainTrusted
			? "Bank snapshot trusted; full net worth restored."
			: verdict == LoginCustody.Verdict.ACQUITTED
				? "Bank photo predates an unverified gap. Open your bank once to restore full net worth."
				: "Open your bank for full net worth.";
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.value("Flip Goblin custody: " + detail + ": " + verdict + " (" + meaning + "). " + gate)
			.build());
	}

	/** Saves the session record (with the current chain state) to this character's profile. */
	private void persistSessionRecord()
	{
		if (sessionRecord == null)
		{
			return;
		}
		sessionRecord.bankChainTrusted = bankChainTrusted;
		configManager.setRSProfileConfiguration(FlipGoblinPlugin.CONFIG_GROUP, SESSION_KEY,
			gson.toJson(sessionRecord));
	}

	/** The previous session's record from this character's profile, or null (first run or corrupt). */
	private LoginCustody.SessionRecord loadSessionRecord()
	{
		String json = configManager.getRSProfileConfiguration(FlipGoblinPlugin.CONFIG_GROUP, SESSION_KEY);
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, LoginCustody.SessionRecord.class);
		}
		catch (RuntimeException e)
		{
			log.warn("corrupt session record in profile, treating as absent (AMBIGUOUS)", e);
			return null;
		}
	}
}

package com.flipgoblin;

/**
 * One Ignore click: the item's units open at {@code timestamp} stop counting as a flip.
 * Same as the website's "not a flip" button.
 */
public final class Dismissal
{
	public final int itemId;
	/** Unix ms of the click. Fills at the same ms are written off too. */
	public final long timestamp;

	public Dismissal(int itemId, long timestamp)
	{
		this.itemId = itemId;
		this.timestamp = timestamp;
	}
}

package com.flipgoblin;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("flipgoblin")
public interface FlipGoblinConfig extends Config
{
	// RuneLite renders each description as an "<html>name:<br>description</html>" tooltip. An
	// unconstrained one lays out as a single line and clips at the screen edge, so every visible
	// description wraps its text in this width-capped div.
	String DESC_OPEN = "<div style='width:300px'>";
	String DESC_CLOSE = "</div>";

	// The server URL is baked into FlipGoblinPlugin.API_BASE; there is no config item for it.
	// All real settings live in the Flip Goblin side panel's Settings tab. The items below are
	// hidden ConfigManager-backed storage the panel writes through, so values persist and
	// live-apply as normal. The one visible item is the pointer note.

	// RuneLite's config system has no plain-label or button widgets, so the pointer is a
	// checkbox acting as a pure clicker: every toggle, tick or untick, opens the panel's
	// Settings tab. We never write the value back, because a programmatic reset is not
	// repainted by the open config page and the box would look stuck. The stored value is
	// meaningless.
	@ConfigItem(
		position = 1,
		keyName = "openPanel",
		name = "→ Open FlipGoblin settings",
		description = DESC_OPEN
			+ "All FlipGoblin settings live in the Flip Goblin side panel's Settings tab (account linking, hover tooltips, graphs, opacity). Clicking this box (ticking OR unticking) opens it."
			+ DESC_CLOSE
	)
	default boolean openPanel()
	{
		return false;
	}

	@ConfigItem(
		position = 2,
		keyName = "apiToken",
		name = "Account token",
		description = DESC_OPEN
			+ "Paste the one-time token from your FlipGoblin dashboard (Settings → generate token; free account) to link THE CHARACTER YOU ARE LOGGED IN ON. Each character keeps its own token (mint one per character for separate dashboard tracking; this field always shows the current character's). Linking is the plugin's ONE data switch. While a token is set: live market data is fetched for items you view at the GE or hover in your inventory (each request carries the item id and your token, nothing else); your GE fills (item, buy/sell, price, quantity, time, GE slot) and the items you mark Ignore (item, time) sync to YOUR dashboard; those same fills (minus slot) feed FlipGoblin's shared price stream, where only blended aggregates from many contributors are ever shown; your asset snapshot (bank, inventory, equipment, GE-held items, coins) syncs to YOUR account; and this character's name rides along purely as a dashboard label. Remove the token to unlink this character; the plugin then works purely locally on it."
			+ DESC_CLOSE,
		secret = true,
		hidden = true
	)
	default String apiToken()
	{
		return "";
	}

	@ConfigItem(
		position = 3,
		keyName = "inventoryHover",
		name = "Inventory hover",
		description = DESC_OPEN
			+ "Hovering an inventory item outside the Grand Exchange (banking, skilling) shows the same FlipGoblin market tooltip that GE hovering always shows (ask/bid, after-tax margin, ROI, volume, buy limit). Requires the account token. Each price request carries the item id and your token, nothing else."
			+ DESC_CLOSE,
		hidden = true
	)
	default boolean inventoryHover()
	{
		return true;
	}

	/**
	 * A graph timeframe: the display label, plus the candle interval and point count that
	 * render it. Points × interval = the span.
	 */
	enum Timeframe
	{
		MIN_45("45 Minutes (1m)", "45 Min", "1m", 45, 60),
		HOURS_4("4 Hours (5m)", "4 Hour", "5m", 48, 300),
		HOURS_12("12 Hours (15m)", "12 Hour", "15m", 48, 900),
		DAYS_2("2 Days (1h)", "2 Day", "1h", 48, 3_600),
		DAYS_7("7 Days (4h)", "7 Day", "4h", 42, 14_400);

		final String label;
		/** Short form for readout rows, e.g. "7 Day High" / "7 Day Low". */
		final String shortName;
		final String interval;
		final int points;
		/** One bucket's span in seconds. Feeds the readout's "Next bucket" countdown. */
		final int intervalSec;

		Timeframe(String label, String shortName, String interval, int points, int intervalSec)
		{
			this.label = label;
			this.shortName = shortName;
			this.interval = interval;
			this.points = points;
			this.intervalSec = intervalSec;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		position = 4,
		keyName = "geShowTopGraph",
		name = "Show top graph",
		description = DESC_OPEN
			+ "Also show a second graph above the Grand Exchange window. Same keyed price fetch (item id only)."
			+ DESC_CLOSE,
		hidden = true
	)
	default boolean geShowTopGraph()
	{
		return false;
	}

	// The two timeframe pickers are HIDDEN here: they live in the sidebar panel; only the
	// show-top-graph master toggle stays in this settings page. The keys remain config-backed
	// so the panel writes through ConfigManager and the values persist.
	@ConfigItem(
		position = 5,
		keyName = "geTopGraph",
		name = "Top graph",
		description = "Timeframe for the graph above the Grand Exchange window (candle interval in parentheses).",
		hidden = true
	)
	default Timeframe geTopGraph()
	{
		return Timeframe.DAYS_7;
	}

	@ConfigItem(
		position = 6,
		keyName = "geBottomGraph",
		name = "Bottom graph",
		description = "Timeframe for the graph below the Grand Exchange window (candle interval in parentheses).",
		hidden = true
	)
	default Timeframe geBottomGraph()
	{
		return Timeframe.DAYS_2;
	}

	@net.runelite.client.config.Range(max = 100)
	@ConfigItem(
		position = 7,
		keyName = "gePanelOpacity",
		name = "Panel opacity",
		description = DESC_OPEN
			+ "Background opacity (%) of the GE graphs, readout panels, info panel, tooltips, and slot price tags. 100 = fully opaque."
			+ DESC_CLOSE,
		hidden = true
	)
	default int gePanelOpacity()
	{
		return 55; // ≈ the original translucent black (140/255)
	}

	@ConfigItem(
		position = 8,
		keyName = "panelScopeAll",
		name = "Panel shows all characters",
		description = DESC_OPEN
			+ "Side panel P/L and assets sum EVERY linked character (other characters counted from their locally stored 7-day fill history and last bank photo) instead of just the one logged in. Purely local: nothing extra is sent anywhere."
			+ DESC_CLOSE,
		hidden = true // the picker lives in the side panel's Session tab
	)
	default boolean panelScopeAll()
	{
		return false;
	}

	@ConfigItem(
		position = 10,
		keyName = "hideUntrackedSales",
		name = "Hide untracked sales",
		description = DESC_OPEN
			+ "Session items leaves out items with only untracked sales: sold without a buy the plugin saw (loot, stock from before tracking), so no profit is counted for them. Items with a flip always show, and the fills list still shows every sale. Display only: nothing is sent anywhere."
			+ DESC_CLOSE,
		hidden = true // set in the side panel's Settings tab
	)
	default boolean hideUntrackedSales()
	{
		return true;
	}

	@ConfigItem(
