	/** Updates the account-link status rows on both tabs. EDT only. */
	public void setLinkStatus(boolean linked, boolean locked, boolean updateRequired, String character)
	{
		characterLockedNow = locked;
		String text;
		Color color;
		String tip = null;
		if (linked && updateRequired)
		{
			// The server no longer accepts this plugin version. Nothing is lost while it waits.
			text = "UPDATE NEEDED";
			color = LOSS;
			tip = "Flip Goblin needs an update. Restart RuneLite, or click Update in the Plugin Hub, "
				+ "to install it. Your trades are kept and sync after the update.";
		}
		else if (linked && locked)
		{
			// Lapse lock: the server refuses this character. Say so loudly.
			text = character == null || character.isEmpty() ? "LOCKED" : "LOCKED · " + character;
			color = LOSS;
			tip = "This character is past the free one-character limit. Syncing and market data "
				+ "are paused. Unlink other characters on the website's Settings, or go Premium.";
		}
		else if (linked)
		{
			text = character == null || character.isEmpty() ? "linked" : "linked · " + character;
			color = PROFIT;
		}
		else
		{
			text = "not linked";
			color = MUTED;
		}
