		{
			JButton ignore = new TipButton("Ignore");
			ignore.setFont(FontManager.getRunescapeSmallFont());
			ignore.setFocusable(false);
			ignore.setForeground(Color.WHITE);
			ignore.setBackground(IGNORE_RED);
