	/** This item's session totals, or null when untraded this session. */
	SessionStats.ItemTotals sessionItemStats(int itemId)
	{
		List<TradeRecord> recs = records;
		if (recs == null || recs.isEmpty())
		{
			return null;
		}
		long buys = 0;
		long sells = 0;
		for (TradeRecord r : recs)
		{
			if (r.itemId != itemId)
			{
				continue;
			}
			if (r.side == TradeRecord.Side.BUY)
			{
				buys += r.quantity;
			}
			else
			{
				sells += r.quantity;
			}
		}
		if (buys == 0 && sells == 0)
		{
			return null;
		}
		long realized = 0;
		for (SessionStats.ItemPosition p : SessionStats.match(recs, dismissalsView()).items)
		{
			if (p.itemId == itemId)
			{
				realized = p.realized;
				break;
			}
		}
		return new SessionStats.ItemTotals(buys, sells, realized);
	}

	/**
	 * Refines a recovered fill's time. The fill's existence, price, and quantity are
	 * certain from the slot delta; only its time is a detection stamp. The public trade
	 * feed supplies candidate instants: minutes inside the offline window where the fill's
	 * side traded at exactly its price. The latest match wins, which is conservative for
	 * the 4h limit window, and no match keeps the detection time. The recovered flag and
	 * offlineSince stay, since the time remains an estimate either way, and the clientId
	 * is preserved so the server never sees a duplicate. Executor thread; the record swap
	 * hops back to the client thread.
	 */
	private void refineRecoveredFill(TradeRecord r)
	{
		PriceClient p = prices;
		if (p == null || !isOperational())
		{
			return;
		}
		int spanMin = (int) Math.min(10_080, (r.timestamp - r.offlineSince) / 60_000 + 3);
		if (spanMin < 2)
		{
			return;
		}
		PriceClient.Series s = p.fetchTicksBlocking(
			API_BASE, config.apiToken().trim(), r.itemId, spanMin);
		if (s == null)
		{
			return;
		}
		long refined = PriceClient.latestPriceMatchMs(s, r.side, r.price, r.offlineSince, r.timestamp);
		if (refined == 0 || refined == r.timestamp)
		{
			return;
		}
		clientThread.invokeLater(() ->
			applyRefinedTimes(java.util.Collections.singletonMap(r, refined)));
	}

	/**
	 * Batch time refinement for GE History imports, whose detection stamps pollute the
	 * record chronology: one 7-day tick fetch per distinct item, then the same
	 * latest-price-match rule per record. Executor thread; one client-thread hop applies
	 * everything.
	 */
	private void refineImports(List<TradeRecord> imports)
	{
		PriceClient p = prices;
		if (p == null || !isOperational())
		{
			return;
		}
		String base = API_BASE;
		String tok = config.apiToken().trim();
		Map<Integer, List<TradeRecord>> byItem = new java.util.HashMap<>();
		for (TradeRecord r : imports)
		{
			byItem.computeIfAbsent(r.itemId, k -> new ArrayList<>()).add(r);
		}
		Map<TradeRecord, Long> refinements = new java.util.HashMap<>();
		for (Map.Entry<Integer, List<TradeRecord>> e : byItem.entrySet())
		{
			PriceClient.Series s = p.fetchTicksBlocking(base, tok, e.getKey(), 10_080);
			if (s == null)
			{
				continue;
			}
			for (TradeRecord r : e.getValue())
			{
				long m = PriceClient.latestPriceMatchMs(s, r.side, r.price,
					r.timestamp - RECORDS_MAX_AGE_MS, r.timestamp);
				if (m > 0 && m != r.timestamp)
				{
					refinements.put(r, m);
				}
			}
		}
		if (!refinements.isEmpty())
		{
			clientThread.invokeLater(() -> applyRefinedTimes(refinements));
		}
	}

	/**
	 * Swaps each record for a copy at its refined time, keeping the clientId (so the
	 * server sees no duplicates) and the recovered semantics. Then re-sorts the list back
	 * to nondecreasing timestamps, since GeLimits reads in order, saves, and repaints.
	 * Client thread only.
	 */
	private void applyRefinedTimes(Map<TradeRecord, Long> refinements)
	{
		List<TradeRecord> recs = records;
		if (recs == null || refinements.isEmpty())
		{
			return;
		}
		int applied = 0;
		for (Map.Entry<TradeRecord, Long> e : refinements.entrySet())
		{
			int idx = recs.indexOf(e.getKey());
			if (idx < 0)
			{
				continue; // list was replaced (relog); the persisted copy keeps its old time
			}
			TradeRecord r = e.getKey();
			recs.set(idx, new TradeRecord(r.itemId, r.side, r.price, r.quantity, r.spent,
				r.slot, e.getValue(), true, r.offlineSince, r.clientId));
			applied++;
		}
		if (applied == 0)
		{
			return;
		}
		recs.sort(java.util.Comparator.comparingLong((TradeRecord x) -> x.timestamp));
		saveRecords();
		sessionRealized = SessionStats.match(recs, dismissalsView()).totalRealized;
		List<TradeRecord> copy = new ArrayList<>(recs);
		Map<Integer, String> names = new java.util.HashMap<>(itemNames);
		List<Dismissal> dis = new ArrayList<>(dismissalsView());
		FlipGoblinPanel target = panel;
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.update(copy, dis, names));
		}
		log.info("[{}] refined {} fill time(s) from the trade feed", BUILD, applied);
	}

	/** The session's most recent fill per side for this item: {last buy, last sell}; null when untraded. */
	TradeRecord[] lastFills(int itemId)
	{
		List<TradeRecord> recs = records;
		if (recs == null || recs.isEmpty())
		{
			return null;
		}
		TradeRecord buy = null;
		TradeRecord sell = null;
		for (TradeRecord r : recs)
		{
			if (r.itemId != itemId)
			{
				continue;
			}
			if (r.side == TradeRecord.Side.BUY)
			{
				buy = buy == null || r.timestamp >= buy.timestamp ? r : buy;
			}
			else
			{
				sell = sell == null || r.timestamp >= sell.timestamp ? r : sell;
			}
		}
		return buy == null && sell == null ? null : new TradeRecord[]{buy, sell};
	}

	/** The GE index screen's 8 slot cards, slot-ordered (hover → live-offer mapping + price tags). */
	static final int[] GE_INDEX_SLOTS = {
		net.runelite.api.gameval.InterfaceID.GeOffers.INDEX_0,
		net.runelite.api.gameval.InterfaceID.GeOffers.INDEX_1,
		net.runelite.api.gameval.InterfaceID.GeOffers.INDEX_2,
		net.runelite.api.gameval.InterfaceID.GeOffers.INDEX_3,
		net.runelite.api.gameval.InterfaceID.GeOffers.INDEX_4,
		net.runelite.api.gameval.InterfaceID.GeOffers.INDEX_5,
		net.runelite.api.gameval.InterfaceID.GeOffers.INDEX_6,
		net.runelite.api.gameval.InterfaceID.GeOffers.INDEX_7,
	};

	/**
	 * The placed offer whose index-slot card the hovered widget sits in, or null. The slot's layers
	 * carry no item id of their own (the icon is a separate child), so hovering a locked buy/sell
	 * slot needs this mapping: walk up to the INDEX_n ancestor, read that slot's live offer.
	 */
	private GrandExchangeOffer slotOffer(net.runelite.api.widgets.Widget w)
	{
		for (net.runelite.api.widgets.Widget a = w; a != null; a = a.getParent())
		{
			for (int slot = 0; slot < GE_INDEX_SLOTS.length; slot++)
			{
				if (a.getId() != GE_INDEX_SLOTS[slot])
				{
					continue;
				}
				GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
				GrandExchangeOffer o = offers == null || slot >= offers.length ? null : offers[slot];
				return o == null || o.getItemId() <= 0
					|| o.getState() == net.runelite.api.GrandExchangeOfferState.EMPTY ? null : o;
			}
		}
		return null;
	}

	/** Sell-side offer states (mirrors GePositions.sideOf's SELL arm). */
	private static boolean isSellState(net.runelite.api.GrandExchangeOfferState s)
	{
		return s == net.runelite.api.GrandExchangeOfferState.SELLING
			|| s == net.runelite.api.GrandExchangeOfferState.SOLD
			|| s == net.runelite.api.GrandExchangeOfferState.CANCELLED_SELL;
	}

	private GeHistoryImporter historyImporter;
	/** Start of the current unbroken login (epoch ms; 0 = not logged in yet this run).
	 * Hops keep it, since their gap fills arrive as recovered and drop exactness on their
	 * own; a fresh login resets it. Drives GeLimits' exact-count proof. */
	private volatile long observedSince;

	/**
	 * Polls the GE History tab through {@link GeHistoryImporter} and folds any new
	 * cost-basis records into the ledger: persist, recompute, repaint, and schedule the
	 * trade-feed time refinement.
	 */
	private void importGeHistory()
	{
		if (records == null || historyImporter == null)
		{
			return;
		}
		List<TradeRecord> importedRecs = historyImporter.poll(records, Instant.now().toEpochMilli());
		if (importedRecs == null || importedRecs.isEmpty())
		{
			return;
		}
		records.addAll(importedRecs);
		saveRecords();
		sessionRealized = SessionStats.match(records, dismissalsView()).totalRealized;
		for (TradeRecord r : records)
		{
			itemNames.computeIfAbsent(r.itemId, id -> itemManager.getItemComposition(id).getName());
		}
		List<TradeRecord> copy = new ArrayList<>(records);
		Map<Integer, String> names = new java.util.HashMap<>(itemNames);
		List<Dismissal> dis = new ArrayList<>(dismissalsView());
		FlipGoblinPanel target = panel;
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.update(copy, dis, names));
		}
		log.info("[{}] GE history: imported {} cost-basis records", BUILD, importedRecs.size());
		executor.submit(() -> refineImports(importedRecs)); // date them from the trade feed
	}

	/**
	 * Hover tooltips (complementing the always-on anchored panel). The canonical
	 * item-prices pattern: per-frame, read the LAST menu entry (what the cursor is on),
	 * canonicalize (noted → tradeable id), tooltip. With the GE open (always on) the gate is the
	 * GE window + its side inventory; outside the GE the inventoryHover toggle extends it to the
	 * inventory (standalone or bank-side; the bank widget swaps the inventory's interface id).
	 * Widgets without an item id of their own fall back to the index-slot mapping, so hovering a
	 * locked buy/sell slot reads out that offer's item too. Untradeables are skipped: the price
	 * API has nothing for them, and a null-parse never caches, so they'd refetch every frame.
	 */
	@Subscribe
	public void onBeforeRender(net.runelite.api.events.BeforeRender event)
	{
		importGeHistory();
		boolean geOpen = client.getWidget(net.runelite.api.gameval.InterfaceID.GeOffers.FRAME) != null;
		if (!geOpen && !config.inventoryHover())
		{
			return;
		}
		net.runelite.api.MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length == 0)
		{
			return;
		}
		net.runelite.api.MenuEntry last = entries[entries.length - 1];
		int group = net.runelite.api.widgets.WidgetUtil.componentToInterface(last.getParam1());
		boolean onGe = group == net.runelite.api.gameval.InterfaceID.GE_OFFERS
			|| group == net.runelite.api.gameval.InterfaceID.GE_OFFERS_SIDE;
		boolean onInventory = group == net.runelite.api.gameval.InterfaceID.INVENTORY
			|| group == net.runelite.api.gameval.InterfaceID.BANKSIDE;
		if (geOpen ? !onGe : !onInventory)
		{
			return;
		}
		net.runelite.api.widgets.Widget w = last.getWidget();
		if (w == null)
		{
			return;
		}
		int rawId = w.getItemId();
		GrandExchangeOffer slotOffer = rawId > 0 ? null : slotOffer(w);
		int itemId = rawId > 0 ? itemManager.canonicalize(rawId)
			: slotOffer == null ? -1 : itemManager.canonicalize(slotOffer.getItemId());
		if (itemId <= 0 || !itemManager.getItemComposition(itemId).isTradeable())
		{
			return;
		}
		PriceClient.ItemPrices p = priceFor(itemId);
		GeLimits.Usage usage = limitUsage(itemId, p == null ? null : p.buyLimit);
		TradeRecord[] fills = lastFills(itemId);
		TradeRecord lastBuy = fills == null ? null : fills[0];
		TradeRecord lastSell = fills == null ? null : fills[1];
		String markup = p == null ? "Flip Goblin: fetching prices…"
			: GeTooltip.build(p, usage, usage == null ? null
					: (usage.hedged ? "by " : "") + GeLimits.resetTime(usage.resetAtMs),
				lastBuy, lastBuy == null ? null : GeLimits.resetTime(lastBuy.timestamp),
				lastSell, lastSell == null ? null : GeLimits.resetTime(lastSell.timestamp));
		// A hovered SELL slot with a known buy-in shows the flipper's unrealized margin: what the
		// unsold remainder nets (tax at the OFFER's price) over the last buy fill.
		if (p != null && slotOffer != null && lastBuy != null && isSellState(slotOffer.getState()))
		{
			int remaining = slotOffer.getTotalQuantity() - slotOffer.getQuantitySold();
			if (remaining > 0)
			{
				long each = SessionStats.netFromSale(slotOffer.getPrice(), itemId) - lastBuy.price;
				markup += "</br>" + GeTooltip.flipLine(each, each * remaining);
			}
		}
		// Own TooltipComponent (not the string form) so the background can be darker than
		// RuneLite's default brown, same darkness as the GE panels,
		// at the user's configured opacity.
		net.runelite.client.ui.overlay.components.TooltipComponent tip =
			new net.runelite.client.ui.overlay.components.TooltipComponent();
		tip.setText(markup);
		tip.setModIcons(client.getModIcons());
		int alpha = Math.max(0, Math.min(100, config.gePanelOpacity())) * 255 / 100;
		tip.setBackgroundColor(new java.awt.Color(0, 0, 0, alpha));
		tooltipManager.add(new net.runelite.client.ui.overlay.tooltip.Tooltip(tip));
	}

	/** Keeps the panel's Settings tab in step with config (writes from any surface live-apply). */
	@Subscribe
	public void onConfigChanged(net.runelite.client.events.ConfigChanged event)
	{
		FlipGoblinPanel pn = panel;
		if (pn != null && CONFIG_GROUP.equals(event.getGroup()))
		{
			SwingUtilities.invokeLater(pn::refreshSettings);
		}
		// The config page's "→ Open FlipGoblin settings" pseudo-button: EVERY toggle of the box
		// (tick or untick) opens the panel on its Settings tab. No write-back: nothing else
		// reads the value, and resetting it isn't repainted by the open config page anyway.
		if (CONFIG_GROUP.equals(event.getGroup()) && "openPanel".equals(event.getKey()))
		{
			NavigationButton nav = navButton;
			if (nav != null && pn != null)
			{
				SwingUtilities.invokeLater(() ->
				{
					clientToolbar.openPanel(nav);
					pn.showSettingsTab();
				});
			}
		}
		// "All characters" scope inputs changed: a link/unlink (any profile's token store) or the
		// scope toggle itself. Reload the parsed stores off-thread, then recompute on the client
		// thread (recomputeAssets touches client-thread state).
		if (CONFIG_GROUP.equals(event.getGroup())
			&& (TOKEN_PROFILE_KEY.equals(event.getKey()) || "panelScopeAll".equals(event.getKey())))
		{
			executor.submit(() ->
			{
				loadOtherCharacters();
				clientThread.invokeLater(this::recomputeAssets);
			});
		}
		// Per-character token memory: a paste while logged in writes
		// through to THIS character's profile store; clearing the field unlinks this character.
		// While logged out the paste stays in the field only; the next character to log in
		// adopts it (see syncTokenForProfile).
		if (CONFIG_GROUP.equals(event.getGroup()) && "apiToken".equals(event.getKey()))
		{
			// A different token may carry a different lock verdict, so re-ask (also clears the
			// stale LOCKED state instantly when the token is removed).
			executor.submit(this::refreshLockStatus);
		}
		if (CONFIG_GROUP.equals(event.getGroup()) && "apiToken".equals(event.getKey()) && !mirroringToken)
		{
			String profileKey = configManager.getRSProfileKey();
			if (profileKey != null)
			{
				String v = config.apiToken().trim();
				if (v.isEmpty())
				{
					configManager.unsetRSProfileConfiguration(CONFIG_GROUP, TOKEN_PROFILE_KEY);
					configManager.unsetConfiguration(CONFIG_GROUP, TOKEN_OWNER_KEY);
				}
				else
				{
					configManager.setRSProfileConfiguration(CONFIG_GROUP, TOKEN_PROFILE_KEY, v);
					configManager.setConfiguration(CONFIG_GROUP, TOKEN_OWNER_KEY, profileKey);
				}
			}
		}
	}

	/**
	 * Per-character token memory, login half. The visible config field always shows the CURRENT
	 * character's token: a stored profile token mirrors into the field; a non-empty field with no
	 * profile entry is a fresh paste that this character ADOPTS; a field
	 * still mirroring ANOTHER character's token clears instead; each character links its own.
	 * Client thread (LOGGED_IN).
	 */
	private void syncTokenForProfile()
	{
		String profileKey = configManager.getRSProfileKey();
		if (profileKey == null)
		{
			return;
		}
		mirroringToken = true;
		try
		{
			String stored = configManager.getRSProfileConfiguration(CONFIG_GROUP, TOKEN_PROFILE_KEY);
			String field = config.apiToken().trim();
			if (stored != null && !stored.isEmpty())
			{
				if (!stored.equals(field))
				{
					configManager.setConfiguration(CONFIG_GROUP, "apiToken", stored);
				}
				configManager.setConfiguration(CONFIG_GROUP, TOKEN_OWNER_KEY, profileKey);
			}
			else if (!field.isEmpty())
			{
				String owner = configManager.getConfiguration(CONFIG_GROUP, TOKEN_OWNER_KEY);
				if (owner == null || owner.isEmpty() || owner.equals(profileKey))
				{
					configManager.setRSProfileConfiguration(CONFIG_GROUP, TOKEN_PROFILE_KEY, field);
					configManager.setConfiguration(CONFIG_GROUP, TOKEN_OWNER_KEY, profileKey);
				}
				else
				{
					configManager.setConfiguration(CONFIG_GROUP, "apiToken", "");
					configManager.unsetConfiguration(CONFIG_GROUP, TOKEN_OWNER_KEY);
				}
			}
		}
		finally
		{
			mirroringToken = false;
		}
		pushLinkStatus();
	}

	/** Off the client thread (executor). Only ever sends when the user opted in AND configured both fields. */
	private void flushIfEnabled()
	{
		SyncClient s = sync;
		if (s == null)
		{
			return;
		}
		String base = API_BASE;
		String token = config.apiToken().trim();
		if (token.isEmpty() || characterLocked)
		{
			return; // locked: queues HOLD (idempotent client ids) and drain the moment we unlock
		}
		// Never send one character's fills with another character's token.
		String owner = s.owner();
		String profile = configManager.getRSProfileKey();
		if (owner == null || (profile != null && !profile.equals(owner)))
		{
			return;
		}
		// The token is the one data switch: trades and the crowd stream both flow whenever
		// linked, disclosed together on the token config item.
		int before = s.pendingCount();
		if (before > 0)
		{
			s.flush(base, token, rsn);
			if (s.pendingCount() != before)
			{
				pendingTrades.save(s);
			}
		}
		if (s.crowdPendingCount() > 0)
		{
			s.flushCrowd(base, token);
		}
		if (s.dismissalPendingCount() > 0)
		{
			s.flushDismissals(base, token, rsn);
		}
	}

	/**
	 * Gives the sync queue to the character now logged in and adds back its saved fills. On a
	 * character switch the old queue is saved under its own character and a fresh one starts.
	 * Client thread.
	 */
	private void bindSyncToCharacter()
	{
		String profile = configManager.getRSProfileKey();
		SyncClient s = sync;
		if (profile == null || s == null || profile.equals(s.owner()))
		{
			return;
		}
		if (s.owner() == null)
		{
			s.claim(profile);
		}
		else
		{
			pendingTrades.save(s);
			s = new SyncClient(apiHttp, gson);
			s.claim(profile);
			sync = s;
		}
		pendingTrades.load(s);
		executor.submit(this::flushIfEnabled);
	}

	/** The saved queue lives in each character's RuneLite profile, beside its token. */
	private PendingTrades.Store pendingStore()
	{
		return new PendingTrades.Store()
		{
			@Override
			public String get(String profile)
			{
				return configManager.getConfiguration(CONFIG_GROUP, profile, PENDING_KEY);
			}

			@Override
			public void put(String profile, String json)
			{
				if (json == null)
				{
					configManager.unsetConfiguration(CONFIG_GROUP, profile, PENDING_KEY);
				}
				else
				{
					configManager.setConfiguration(CONFIG_GROUP, profile, PENDING_KEY, json);
				}
			}

			@Override
			public boolean linked(String profile)
			{
				String token = configManager.getConfiguration(CONFIG_GROUP, profile, TOKEN_PROFILE_KEY);
				return token != null && !token.trim().isEmpty();
			}
		};
	}

	/** Refresh website targets (executor); inert until the account link is configured.
	 *  Doubles as the lapse-lock heartbeat (every 5 min): re-verdicts before deciding to fetch. */
	private void refreshTargetsIfLinked()
	{
		refreshLockStatus();
		TargetsClient t = targets;
		if (t == null)
		{
			return;
		}
		String base = API_BASE;
		String token = config.apiToken().trim();
		if (token.isEmpty() || characterLocked)
		{
			return;
		}
		t.refresh(gson, base, token);
	}

	/** The website target (watchlist/alerts) for an item, or null. Render-thread safe. */
	TargetsClient.Target targetFor(int itemId)
	{
		TargetsClient t = targets;
		return t == null ? null : t.get(itemId);
	}

	@Provides
	FlipGoblinConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FlipGoblinConfig.class);
	}
}

package com.flipgoblin;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;

/**
 * Reads the GE History tab so buys from before the plugin ran still count as cost basis.
 * While the tab is open, each entry is parsed from its widgets: the icon child carries the
 * item id and quantity, a "Bought"/"Sold" caption sets the side, and the "… coins" text
 * closes the entry with its total. Entries become recovered records stamped at detection
 * time, since the tab shows no trade times. They stay local and are never synced, because
 * the server may already hold those fills from an earlier session. Slot -1 marks the origin.
 *
 * Client thread only. The plugin polls every frame; one open of the tab imports once.
 */
@Slf4j
final class GeHistoryImporter
{
	private final Client client;
	private final ItemManager itemManager;
	private boolean imported;

	GeHistoryImporter(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	/**
	 * Reads the History tab if it is open and not yet imported this open. Returns the new
	 * records to add (reconciled against {@code existing} and shape-deduped), or null when
	 * there is nothing to do. The caller persists, repaints, and schedules time refinement.
	 */
	List<TradeRecord> poll(List<TradeRecord> existing, long now)
	{
		Widget list = client.getWidget(InterfaceID.GeHistory.LIST);
		if (list == null)
		{
			imported = false; // tab closed; the next open re-imports (deduped)
			return null;
		}
		if (imported)
		{
			return null;
		}
		// Entries may hang off ANY child array depending on client build, so walk all three (a
		// dynamic-only walk silently imports nothing on the live client).
		List<Widget> kidList = new ArrayList<>();
		for (Widget[] grp : new Widget[][]{
			list.getDynamicChildren(), list.getStaticChildren(), list.getNestedChildren()})
		{
			if (grp != null)
			{
				Collections.addAll(kidList, grp);
			}
		}
		Widget[] kids = kidList.toArray(new Widget[0]);
		if (kids.length == 0)
		{
			return null; // not populated yet; try again next frame
		}
		imported = true;
		log.info("[{}] GE history open: {} children (dyn={}, static={}, nested={})",
			FlipGoblinPlugin.BUILD, kids.length,
			list.getDynamicChildren() == null ? 0 : list.getDynamicChildren().length,
			list.getStaticChildren() == null ? 0 : list.getStaticChildren().length,
			list.getNestedChildren() == null ? 0 : list.getNestedChildren().length);
		int entries = 0;
		String side = null;
		int iconItem = -1;
		int iconQty = 0;
		List<TradeRecord> importedRecs = new ArrayList<>();
		// Live layout, 6 children per entry: "Bought:"/"Sold:" caption →
		// "<name>x <qty>" text → the item ICON (id + qty) → the coins text, which for buys reads
		// "49,000 coins= 7 each" and for sells "1,629,000 coins(1,662,000 - 33,000)= 1,629 each"
		// (NET first, gross − tax in parens; the record wants GROSS so the flip matcher's own tax
		// math doesn't double-count).
		Pattern sidePat = Pattern.compile("^(Bought|Sold):?$");
		Pattern coinsPat = Pattern.compile("^([\\d,]+) coins(?:\\(([\\d,]+) - ([\\d,]+)\\))?.*");
		for (Widget ch : kids)
		{
			if (ch == null)
			{
				continue;
			}
			if (ch.getItemId() > 0)
			{
				iconItem = itemManager.canonicalize(ch.getItemId());
				iconQty = Math.max(1, ch.getItemQuantity());
				continue;
			}
			String plain = ch.getText() == null ? "" : ch.getText().replaceAll("<[^>]*>", "").trim();
			Matcher sm = sidePat.matcher(plain);
			if (sm.matches())
			{
				side = sm.group(1);
				continue;
			}
			Matcher m = coinsPat.matcher(plain);
			if (m.matches() && side != null && iconItem > 0)
			{
				entries++;
				// Gross transacted value: buys report it directly; sells put it in the parens.
				long gross = Long.parseLong(
					(m.group(2) != null ? m.group(2) : m.group(1)).replace(",", ""));
				// Reconcile against slot-observed fill runs: import the whole entry, only its
				// uncovered gap, or nothing. A naive shape-dedup double-counts an offer whose
				// fills were captured piecemeal (see GeHistoryReconcile).
				TradeRecord r = GeHistoryReconcile.importFor(existing, iconItem,
					side.equalsIgnoreCase("Bought") ? TradeRecord.Side.BUY : TradeRecord.Side.SELL,
					iconQty, gross, now);
				// Dedup by shape. NOTE two identical real trades (same item/side/qty/price)
				// collapse to one; the tab carries no ids, so this is the honest floor.
				if (r != null && !hasEquivalent(existing, r) && !hasEquivalent(importedRecs, r))
				{
					importedRecs.add(r);
				}
				side = null;
				iconItem = -1;
				iconQty = 0;
			}
		}
		if (importedRecs.isEmpty() && entries == 0)
		{
			// Nothing parsed from a populated list: dump a compact shape sample for diagnosis.
			StringBuilder sb = new StringBuilder();
			for (int i = 0; i < kids.length && i < 36; i++)
			{
				Widget ch = kids[i];
				if (ch == null)
				{
					continue;
				}
				String t = ch.getText() == null ? "" : ch.getText().replaceAll("<[^>]*>", "");
				sb.append(i).append(":item=").append(ch.getItemId())
					.append(",q=").append(ch.getItemQuantity())
					.append(",t=").append(t, 0, Math.min(40, t.length())).append(" | ");
			}
			log.info("[{}] GE history: no entries parsed from {} children: {}",
				FlipGoblinPlugin.BUILD, kids.length, sb);
		}
		return importedRecs;
	}

	/** An already-known record with the same item, side, quantity, and price (import dedup). */
	private static boolean hasEquivalent(List<TradeRecord> records, TradeRecord r)
	{
		for (TradeRecord x : records)
		{
			if (x.itemId == r.itemId && x.side == r.side && x.quantity == r.quantity && x.price == r.price)
			{
				return true;
			}
		}
		return false;
	}
}

package com.flipgoblin;

import java.util.ArrayList;
import java.util.List;

/**
 * Reconciles GE History imports against fills the plugin already saw live, so an import can
 * never double-count an offer that was partly captured as it happened.
 *
 * Model: a History entry is one completed offer (side, item, total quantity, gross coins).
 * Its live counterpart is a contiguous run of fills for the same item and side on one slot.
 * An entry is matched against the run whose average price agrees. That gives three
 * outcomes: no matching run means the offer predates the plugin and imports whole; full
 * coverage means skip it; partial coverage means import only the missing gap, which also
 * heals fills lost to a capture hole. Two same-price offers on the same slot merge into
 * one run and read as covered. That bias is accepted because it never inflates the ledger.
 *
 * Pure and single-threaded (client thread), like the differ.
 */
final class GeHistoryReconcile
{
	/** Average prices within 1 gp count as the same offer, allowing rounding on partial fills. */
	private static final long PRICE_TOLERANCE = 1;

	private GeHistoryReconcile()
	{
	}

	/**
	 * Groups slot-observed fills of one (item, side) into contiguous same-slot runs, newest
	 * first, each as {quantity, spent}. Fills of other items or sides may interleave freely.
	 * A slot change within the filtered view starts the next, older run.
	 */
	static List<long[]> runs(List<TradeRecord> records, int itemId, TradeRecord.Side side)
	{
		List<long[]> out = new ArrayList<>();
		long[] run = null;
		int runSlot = Integer.MIN_VALUE;
		for (int i = records.size() - 1; i >= 0; i--)
		{
			TradeRecord r = records.get(i);
			if (r.itemId != itemId || r.side != side || r.slot < 0)
			{
				continue;
			}
			if (run == null || r.slot != runSlot)
			{
				run = new long[]{0, 0};
				out.add(run);
				runSlot = r.slot;
			}
			run[0] += r.quantity;
			run[1] += r.spent;
		}
		return out;
	}

	/**
	 * Decides what a History entry ({@code qty} units for {@code gross} coins) should add to
	 * the ledger: the whole entry, just the uncovered gap, or null when it is fully covered.
	 * Imports carry slot -1 and the recovered flag, like all history imports. Callers still
	 * shape-dedup so reopening the tab stays a no-op.
	 */
	static TradeRecord importFor(List<TradeRecord> records, int itemId, TradeRecord.Side side,
		int qty, long gross, long now)
	{
		if (qty <= 0)
		{
			return null;
		}
		long[] run = matchingRun(records, itemId, side, qty, gross);
		if (run == null)
		{
			return new TradeRecord(itemId, side, gross / qty, qty, gross, -1, now, true, 0);
		}
		if (run[0] >= qty)
		{
			return null; // the run holds everything the entry claims; nothing to import
		}
		int gapQty = qty - (int) run[0];
		long gapSpent = Math.max(0, gross - run[1]);
		return new TradeRecord(itemId, side, gapSpent / gapQty, gapQty, gapSpent, -1, now, true, 0);
	}

	/**
	 * Finds the price-agreeing run with the largest quantity, or null when none agrees.
	 * Largest, not newest, keeps the comparison conservative when several offers ran at the
	 * same price: a newer half-filled offer must not shrink an older entry's coverage and
	 * re-import quantity the older run already accounts for.
	 */
	private static long[] matchingRun(List<TradeRecord> records, int itemId, TradeRecord.Side side,
		long qty, long gross)
	{
		long entryAvg = Math.round((double) gross / qty);
		long[] best = null;
		for (long[] run : runs(records, itemId, side))
		{
			long runAvg = Math.round((double) run[1] / run[0]);
			if (Math.abs(entryAvg - runAvg) <= PRICE_TOLERANCE && (best == null || run[0] > best[0]))
			{
				best = run;
			}
		}
		return best;
	}
}

package com.flipgoblin;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Market info wrapped around the Grand Exchange window: an always-on graph below the
 * window, an opt-in second graph above it (both timeframes configurable), and an info
 * panel to the right. While the player is setting up or viewing an offer, the panel shows
 * that item's market data: ask/bid, after-tax margin, ROI, 24h volume per side, buy limit,
 * and data age. The charts span the GE window's width, each with a readout panel at its
 * right edge, because text drawn over the lines was unreadable. Always on; there is no
 * config toggle.
 *
 * There are two triggers because the client models them differently: composing an offer
 * sets the TRADINGPOST_SEARCH varp (reset to -1 on confirm), while viewing a placed offer
 * only sets the GE_SELECTEDSLOT varbit (1-based; 0 means the index screen). In the second
 * case the item comes from that slot's live offer, which also feeds the "Your offer"
 * progress line.
 *
 * Anchors to the GE widget's live bounds. Renders nothing when the GE is closed or no
 * item is selected. Prices come from PriceClient's cache, so render never blocks.
 */
@Slf4j
public class GeInfoOverlay extends Overlay
{
	private static final Color GOLD = new Color(0xd4, 0xaf, 0x37);
	private static final Color PROFIT = new Color(0x3f, 0xb9, 0x50);
	private static final Color LOSS = new Color(0xf8, 0x51, 0x49);
	private static final Color MUTED = Color.LIGHT_GRAY;
	// Chart series colors: the website's exactly (apps/web/lib/candles.ts ASK_COLOR / BID_COLOR).
	private static final Color ASK_LINE = new Color(0xe8, 0xb0, 0x4f);
	private static final Color BID_LINE = new Color(0x38, 0xbd, 0xf8);
	/** The purchase-price reference line while selling a tracked flip. */
	private static final Color REF_LINE = new Color(0xf8, 0x51, 0x49, 190);
	// Trade-dot colors use the site's DOT_MAX_ALPHA (0.6) exactly: softer than the lines they sit on.
	private static final Color ASK_DOT = new Color(0xe8, 0xb0, 0x4f, 153);
	private static final Color BID_DOT = new Color(0x38, 0xbd, 0xf8, 153);
	/** One background for the chart boxes and every panel, at the configured opacity. */
	private Color panelBg()
	{
		int a = Math.max(0, Math.min(100, config.gePanelOpacity())) * 255 / 100;
		return new Color(0, 0, 0, a);
	}

	private final Client client;
	private final FlipGoblinPlugin plugin;
	private final FlipGoblinConfig config;
	private final PanelComponent panel = new PanelComponent();
	// The readout panels persist (one per chart slot) because PanelComponent draws its
	// background from the size cached on the previous render. A fresh instance per frame
	// painted a tiny default square with no visible background.
	private final PanelComponent topReadout = new PanelComponent();
	private final PanelComponent botReadout = new PanelComponent();
	private String lastGate;

	/** Chart box height. */
	private static final int CHART_H = 176;
	private static final int GAP = 6;
	/** The price typed into a new offer. A 64-bit varp that RuneLite has not named yet. */
	private static final int GE_SETUP_PRICE_VARP = 5753;

	@Inject
	GeInfoOverlay(Client client, FlipGoblinPlugin plugin, FlipGoblinConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Do not use isHidden() here. It walks the ancestor chain, and this interface's root
		// layer reads hidden on the live client even while the GE is plainly on screen.
		// Loaded versus null is the real open/closed signal: the widget goes null when the
		// GE closes.
		Widget ge = client.getWidget(InterfaceID.GeOffers.FRAME);
		if (ge == null)
		{
			trace("FRAME null (GE closed, or child index moved on this client rev)");
			return null;
		}
		Rectangle b = ge.getBounds();
		if (b == null || b.width <= 0 || b.height <= 0)
		{
			trace("degenerate bounds " + b);
			return null; // open/close transition frame: no real geometry to anchor to yet
		}
		int varp = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		GrandExchangeOffer viewed = viewedOffer(varp);
		int itemId = viewed != null ? viewed.getItemId() : varp;
		if (itemId <= 0)
		{
			// Slot price tags belong only on the index screen. "No item selected" is not
			// enough of a check: composing into an empty slot keeps the item varp unset
			// while the setup screen covers the cards, and a stray tag would float over
			// "Choose an item…". GE_SELECTEDSLOT is set the whole time any slot screen is
			// open, so 0 means the index screen, where the cards are visible.
			if (client.getVarbitValue(VarbitID.GE_SELECTEDSLOT) == 0)
			{
				drawSlotPrices(graphics);
			}
			trace("no item: varp=" + varp
				+ " selectedSlot=" + client.getVarbitValue(VarbitID.GE_SELECTEDSLOT));
			return null;
		}
		trace("rendering item=" + itemId + (viewed != null ? " (viewed offer)" : " (setup)")
			+ " at " + b.x + "," + b.y + " " + b.width + "x" + b.height);

		PriceClient.ItemPrices p = plugin.priceFor(itemId);
		// Flip context: selling something this plugin saw us buy. This powers the panel's
		// purchase, break-even, and expected-P/L rows, and the red purchase-price line on
		// the graphs. The setup side comes from the composer varbits, and a placed sell
		// carries its own price. The cost basis is the last tracked buy, the same basis as
		// the Last buy row.
		boolean setupSell = viewed == null && client.getVarbitValue(VarbitID.GE_NEWOFFER_TYPE) == 1;
		boolean viewedSell = viewed != null && sellSide(viewed.getState())
			&& viewed.getTotalQuantity() - viewed.getQuantitySold() > 0;
		TradeRecord[] fills = plugin.lastFills(itemId);
		TradeRecord lastBuy = fills == null ? null : fills[0];
		long purchasePrice = (setupSell || viewedSell) && lastBuy != null ? lastBuy.price : 0;

		panel.getChildren().clear();
		panel.getChildren().add(TitleComponent.builder()
			.text(p != null && p.name != null ? p.name : plugin.overlayName(itemId)).color(GOLD).build());
		if (viewed != null)
		{
			addYourOfferRow(viewed);
		}
		if (p == null)
		{
			addNoDataRows();
		}
		else
		{
			addMarketRows(p);
			addFlipRows(p, itemId, setupSell || viewedSell, viewedSell, viewed, lastBuy, purchasePrice);
			addLimitRows(p, itemId);
			addActivityRows(p, itemId, fills);
		}
		return layoutPanelAndCharts(graphics, b, p, itemId, purchasePrice);
	}

	/** The "Your offer" progress row for a viewed placed offer. */
	private void addYourOfferRow(GrandExchangeOffer viewed)
	{
		boolean buy = viewed.getState() == GrandExchangeOfferState.BUYING
			|| viewed.getState() == GrandExchangeOfferState.BOUGHT
			|| viewed.getState() == GrandExchangeOfferState.CANCELLED_BUY;
		panel.getChildren().add(LineComponent.builder()
			.left("Your offer")
			.right((buy ? "Buy " : "Sell ") + viewed.getQuantitySold() + "/" + viewed.getTotalQuantity()
				+ " @ " + Gp.exact(viewed.getPrice()))
			.rightColor(Color.WHITE)
			.build());
	}

	/** What to show while no market data is available: why, not a spinner forever. */
	private void addNoDataRows()
	{
		if (plugin.isLinked() && plugin.isCharacterLocked())
		{
			// Lapse lock: the server refuses this character. Say why instead of
			// spinning on "fetching" forever.
			panel.getChildren().add(LineComponent.builder()
				.left("Character locked").leftColor(Color.RED).build());
			panel.getChildren().add(LineComponent.builder()
				.left("another linked character holds the slot.").leftColor(MUTED).build());
			panel.getChildren().add(LineComponent.builder()
				.left("unlink it at:").leftColor(MUTED).build());
			panel.getChildren().add(LineComponent.builder()
				.left("flipgoblin.com/settings").leftColor(MUTED).build());
		}
		else if (!plugin.isLinked())
		{
			// Market data needs a linked account. Say so instead of spinning forever
			// on "fetching".
			panel.getChildren().add(LineComponent.builder()
				.left("Link your Flip Goblin account (free)").leftColor(GOLD).build());
			panel.getChildren().add(LineComponent.builder()
				.left("for live prices, margins + charts:").leftColor(MUTED).build());
			panel.getChildren().add(LineComponent.builder()
				.left("flipgoblin.com/settings").leftColor(MUTED).build());
		}
		else
		{
			panel.getChildren().add(LineComponent.builder().left("fetching prices…").leftColor(MUTED).build());
		}
	}

	/** The live market rows: ask, bid, tax and limit, market margin. */
	private void addMarketRows(PriceClient.ItemPrices p)
	{
		// Real prices are exact; undercutting is decided in the last coins.
		panel.getChildren().add(LineComponent.builder()
			.left("Buy (ask)").right(Gp.exactOrDash(p.ask)).rightColor(Color.WHITE).build());
		panel.getChildren().add(LineComponent.builder()
			.left("Sell (bid)").right(Gp.exactOrDash(p.bid)).rightColor(Color.WHITE).build());
		panel.getChildren().add(LineComponent.builder()
			.left("Tax / limit")
			.right(Gp.exactOrDash(p.tax) + " / " + (p.buyLimit == null ? "—" : String.valueOf(p.buyLimit)))
			.rightColor(MUTED)
			.build());
		Color marginColor = p.margin == null ? MUTED : p.margin > 0 ? PROFIT : LOSS;
		panel.getChildren().add(LineComponent.builder()
			.left("Market Margin")
			.right(Gp.exactOrDash(p.margin) + (p.roi == null ? "" : String.format(" · %.1f%%", p.roi * 100)))
			.rightColor(marginColor)
			.build());
	}

	/**
	 * The flip rows. While selling (composing a sell offer or viewing a placed one), show
	 * the tracked purchase price, the after-tax break-even ask, and, once a price is set,
	 * the expected P/L at that price. With no tracked buy the section still shows a dash
	 * instead of hiding, because a vanished row reads as "where's my margin?".
	 */
	private void addFlipRows(PriceClient.ItemPrices p, int itemId, boolean selling,
		boolean viewedSell, GrandExchangeOffer viewed, TradeRecord lastBuy, long purchasePrice)
	{
		if (!selling)
		{
			return;
		}
		panel.getChildren().add(LineComponent.builder().left(" ").build()); // spacer
		if (lastBuy == null)
		{
			panel.getChildren().add(LineComponent.builder()
				.left("Flip")
				.right("(no tracked buy)")
				.rightColor(MUTED)
				.build());
			return;
		}
		panel.getChildren().add(LineComponent.builder()
			.left("Purchase price")
			.right(Gp.exact(purchasePrice))
			.rightColor(Color.WHITE)
			.build());
		panel.getChildren().add(LineComponent.builder()
			.left("Break-even")
			.right(Gp.exact(SessionStats.breakevenAsk(purchasePrice, itemId)))
			.rightColor(GOLD)
			.build());
		long setPrice = viewedSell ? viewed.getPrice()
			: client.getVarpLongValue(GE_SETUP_PRICE_VARP);
		long qty = viewedSell ? viewed.getTotalQuantity() - viewed.getQuantitySold()
			: Math.max(1, client.getVarbitValue(VarbitID.GE_NEWOFFER_QUANTITY));
		if (setPrice > 0)
		{
			long each = SessionStats.netFromSale(setPrice, itemId) - purchasePrice;
			panel.getChildren().add(LineComponent.builder()
				.left("Expected P/L")
				.right(Gp.exact(each) + "/ea · " + Gp.shortForm(each * qty))
				.rightColor(each > 0 ? PROFIT : each < 0 ? LOSS : MUTED)
				.build());
		}
	}

	/** The 4h buy-limit rows: bought, limit left, and the reset countdown. */
	private void addLimitRows(PriceClient.ItemPrices p, int itemId)
	{
		// The 4h buy-limit usage seen this session. "≥" because buys before the plugin
		// ran are invisible. Red once the known count reaches the limit.
		GeLimits.Usage limit = plugin.limitUsage(itemId, p.buyLimit);
		// exact means the whole window was watched live, so no ≥/≤ hedging.
		boolean exact = limit != null && limit.exact;
		if (limit != null)
		{
			boolean capped = p.buyLimit != null && limit.used >= p.buyLimit;
			panel.getChildren().add(LineComponent.builder()
				.left("Bought (4h)")
				.right((exact ? "" : "≥") + limit.used + (p.buyLimit == null ? "" : "/" + p.buyLimit))
				.rightColor(capped ? LOSS : MUTED)
				.build());
		}
		// The useful complement: what can still be bought this window. "≤" because
		// unseen pre-session buys can only shrink it.
		if (p.buyLimit != null)
		{
			long left = Math.max(0, p.buyLimit - (limit == null ? 0 : limit.used));
			panel.getChildren().add(LineComponent.builder()
				.left("Limit left")
				.right((exact ? "" : "≤") + left)
				.rightColor(left == 0 ? LOSS : Color.WHITE)
				.build());
		}
		// The window's reset moment on its own row, with a Next-Update-style countdown
		// beside the wall-clock time.
		if (limit != null)
		{
			// When recovered fills are involved, the reset time is only an upper bound.
			String by = limit.hedged ? "by " : "";
			long resetIn = Math.max(0, (limit.resetAtMs - System.currentTimeMillis()) / 1000);
			panel.getChildren().add(LineComponent.builder()
				.left("Limit resets")
				.right(by + GeLimits.resetTime(limit.resetAtMs) + (resetIn == 0 ? " · now" : " · in " + dur(resetIn)))
				.rightColor(MUTED)
				.build());
		}
	}

	/** Volume, watchlist targets, the session's own trades, and the refresh countdown. */
	private void addActivityRows(PriceClient.ItemPrices p, int itemId, TradeRecord[] fills)
	{
		panel.getChildren().add(LineComponent.builder()
			.left("24h vol (ask/bid)")
			.right(numOrDash(p.askVolume) + " / " + numOrDash(p.bidVolume))
			.rightColor(MUTED)
			.build());
		// The user's website targets for this item: the watched flag and alert
		// thresholds, managed on the site. Absent silently when not linked.
		TargetsClient.Target target = plugin.targetFor(itemId);
		if (target != null)
		{
			if (target.watched)
			{
				panel.getChildren().add(LineComponent.builder()
					.left("★ on your watchlist")
					.leftColor(GOLD)
					.build());
			}
			for (TargetsClient.TargetAlert a : target.alerts)
			{
				if (a.enabled)
				{
					panel.getChildren().add(LineComponent.builder()
						.left("alert")
						.leftColor(MUTED)
						.right(TargetsClient.alertLabel(a))
						.rightColor(GOLD)
						.build());
				}
			}
		}
		// The user's own trades for this item, from this session only.
		SessionStats.ItemTotals session = plugin.sessionItemStats(itemId);
		if (session != null)
		{
			panel.getChildren().add(LineComponent.builder()
				.left("You (7d)")
				.right(session.bought + "B/" + session.sold + "S · " + Gp.shortForm(session.realized))
				.rightColor(session.realized > 0 ? PROFIT : session.realized < 0 ? LOSS : MUTED)
				.build());
		}
		// The session's most recent fill per side: the entry and exit prices this offer is priced against.
		if (fills != null)
		{
			if (fills[0] != null)
			{
				panel.getChildren().add(LineComponent.builder()
					.left("Last buy")
					.right(Gp.exact(fills[0].price) + " ×" + fills[0].quantity
						+ " · " + GeLimits.resetTime(fills[0].timestamp))
					.rightColor(Color.WHITE)
					.build());
			}
			if (fills[1] != null)
			{
				panel.getChildren().add(LineComponent.builder()
					.left("Last sell")
					.right(Gp.exact(fills[1].price) + " ×" + fills[1].quantity
						+ " · " + GeLimits.resetTime(fills[1].timestamp))
					.rightColor(Color.WHITE)
					.build());
			}
		}
		// Countdown to the next detail refresh. The fetch fires when the API's cache
		// entry turns over, so hitting zero coincides with fresh data actually arriving.
		long nextS = Math.max(0,
			(plugin.nextDetailFetch(itemId) - System.currentTimeMillis()) / 1000);
		panel.getChildren().add(LineComponent.builder()
			.left("Next Update").right(nextS == 0 ? "now" : "in " + nextS + "s")
			.rightColor(MUTED).build());
	}

	/**
	 * Lays out the info panel to the right of the GE window (clamped on-canvas) and the
	 * charts above and below it, then draws them. Returns the overlay's total size.
	 */
	private Dimension layoutPanelAndCharts(Graphics2D graphics, Rectangle b,
		PriceClient.ItemPrices p, int itemId, long purchasePrice)
	{
		Color bg = panelBg();
		panel.setBackgroundColor(bg);
		topReadout.setBackgroundColor(bg);
		botReadout.setBackgroundColor(bg);
		int panelWidth = Math.max(230, b.width / 2);
		int px = Math.min(b.x + b.width + GAP, client.getCanvasWidth() - panelWidth - 4);
		int py = b.y;
		panel.setPreferredSize(new Dimension(panelWidth, 0));
		graphics.translate(px, py);
		Dimension d = panel.render(graphics);
		graphics.translate(-px, -py);

		int chartW = Math.max(460, b.width);
		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		int top = b.y;
		int bottom = Math.max(b.y + b.height, py + (d == null ? 0 : d.height));
		int right = px + panelWidth;
		FlipGoblinConfig.Timeframe topTf = config.geTopGraph();
		FlipGoblinConfig.Timeframe botTf = config.geBottomGraph();
		PriceClient.Series topS = !config.geShowTopGraph() || p == null
			? null : plugin.seriesFor(itemId, topTf.interval, topTf.points);
		PriceClient.Series botS = p == null
			? null : plugin.seriesFor(itemId, botTf.interval, botTf.points);
		if (topS != null && topS.ask.length >= 2)
		{
			int cy = Math.max(4, b.y - CHART_H - GAP);
			drawChartAt(graphics, topS, volumeSource(topTf, topS, itemId), volArrival(topTf, itemId),
				bg, chartW, panelWidth, b.x, cy, mouse, topTf, topReadout, itemId, purchasePrice);
			top = Math.min(top, cy);
			right = Math.max(right, b.x + chartW + GAP + panelWidth);
		}
		if (botS != null && botS.ask.length >= 2)
		{
			int cy = b.y + b.height + GAP;
			drawChartAt(graphics, botS, volumeSource(botTf, botS, itemId), volArrival(botTf, itemId),
				bg, chartW, panelWidth, b.x, cy, mouse, botTf, botReadout, itemId, purchasePrice);
			bottom = Math.max(bottom, cy + CHART_H);
			right = Math.max(right, b.x + chartW + GAP + panelWidth);
		}

		return new Dimension(right - b.x, bottom - top);
	}

	/**
	 * Where a graph's volume pane reads from. Candle graphs carry their own volumes. The 1m
	 * tick graph borrows the 5m grid, since ticks carry no volume and the site renders
	 * 5m-window blocks there. The 48-slot depth matches the 4 Hours timeframe so both share
	 * one cache entry.
	 */
	private PriceClient.Series volumeSource(FlipGoblinConfig.Timeframe tf, PriceClient.Series s, int itemId)
	{
		return "1m".equals(tf.interval) ? plugin.seriesFor(itemId, "5m", 48) : s;
	}

	/** The observed volume-arrival marker for the 1m graph's 5m companion; null for candle graphs. */
	private PriceClient.VolArrival volArrival(FlipGoblinConfig.Timeframe tf, int itemId)
	{
		return "1m".equals(tf.interval) ? plugin.volArrival(itemId, "5m") : null;
	}

	/** Translates to (x, y), draws one chart box + readout panel with the mouse mapped into that space. */
	private static void drawChartAt(Graphics2D g, PriceClient.Series s, PriceClient.Series volSrc,
		PriceClient.VolArrival volArrival, Color bg, int width, int sideWidth, int x, int y,
		net.runelite.api.Point mouse, FlipGoblinConfig.Timeframe tf, PanelComponent side, int itemId,
		long refPrice)
	{
		int mx = mouse == null ? -1 : mouse.getX() - x;
		int my = mouse == null ? -1 : mouse.getY() - y;
		g.translate(x, y);
		drawChart(g, s, volSrc, volArrival, bg, width, sideWidth, mx, my, tf, side, itemId, refPrice);
		g.translate(-x, -y);
	}

	/**
	 * The slot-card price tags. Each active offer's card gets its side's live market price:
	 * the ask for sell offers, the bid for buy offers. Green when our offer is priced to
	 * fill (a sell at or below the ask, a buy at or above the bid), red otherwise. Drawn
	 * centered on the card's progress bar over a dark translucent backing sized to the
	 * text, since placements in the name area collided with two-line item names. Only
	 * called on the index screen; the details and setup screens cover the cards.
	 */
	private void drawSlotPrices(Graphics2D g)
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return;
		}
		java.awt.Font prevFont = g.getFont();
		g.setFont(net.runelite.client.ui.FontManager.getRunescapeSmallFont());
		java.awt.FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < FlipGoblinPlugin.GE_INDEX_SLOTS.length && i < offers.length; i++)
		{
			GrandExchangeOffer o = offers[i];
			if (o == null || o.getItemId() <= 0 || o.getState() == GrandExchangeOfferState.EMPTY)
			{
				continue;
			}
			Widget slot = client.getWidget(FlipGoblinPlugin.GE_INDEX_SLOTS[i]);
			Rectangle sb = slot == null ? null : slot.getBounds();
			if (sb == null || sb.width <= 0 || sb.height <= 0)
			{
				continue;
			}
			boolean buyOffer = o.getState() == GrandExchangeOfferState.BUYING
				|| o.getState() == GrandExchangeOfferState.BOUGHT
				|| o.getState() == GrandExchangeOfferState.CANCELLED_BUY;
			PriceClient.ItemPrices p = plugin.priceFor(o.getItemId());
			Long market = p == null ? null : buyOffer ? p.bid : p.ask;
			if (market == null)
			{
				continue;
			}
			Rectangle bar = barBounds(slot, sb);
			if (bar == null)
			{
				bar = new Rectangle(sb.x + 4, sb.y + sb.height - 18, sb.width - 8, 15);
			}
			String txt = Gp.exact(market);
			boolean fills = buyOffer ? o.getPrice() >= market : o.getPrice() <= market;
			int tw = fm.stringWidth(txt);
			int tx = bar.x + (bar.width - tw) / 2;
			int baseline = bar.y + (bar.height + fm.getAscent() - fm.getDescent()) / 2;
			g.setColor(panelBg());
			g.fillRect(tx - 3, bar.y + 1, tw + 6, bar.height - 2);
			g.setColor(Color.BLACK);
			g.drawString(txt, tx + 1, baseline + 1);
			g.setColor(fills ? PROFIT : LOSS);
			g.drawString(txt, tx, baseline);
		}
		g.setFont(prevFont);
	}

	/**
	 * The slot card's offer-progress bar: the widest short (≤20px) NON-TEXT child in the card's
	 * bottom half; null when not found (caller falls back to the card's bottom strip). Text-bearing
	 * children are excluded because the offer-PRICE label sits directly under the bar with near-
	 * identical geometry and would win the width contest.
	 */
	private static Rectangle barBounds(Widget slot, Rectangle sb)
	{
		Rectangle best = null;
		Widget[][] groups = {slot.getStaticChildren(), slot.getDynamicChildren(), slot.getNestedChildren()};
		for (Widget[] grp : groups)
		{
			if (grp == null)
			{
				continue;
			}
			for (Widget ch : grp)
			{
				String t = ch == null ? null : ch.getText();
				Rectangle b = ch == null || (t != null && !t.isEmpty()) ? null : ch.getBounds();
				if (b == null || b.height <= 0 || b.height > 20 || b.y < sb.y + sb.height / 2)
				{
					continue;
				}
				if (best == null || b.width > best.width)
				{
					best = b;
				}
			}
		}
		return best;
	}

	/**
	 * Logs the render verdict whenever it changes: a handful of lines per GE visit, silent
	 * otherwise. Kept at info level on purpose, so a silently blank panel names which gate
	 * tripped.
	 */
	private void trace(String gate)
	{
		if (!gate.equals(lastGate))
		{
			lastGate = gate;
			log.info("[{}] GE panel: {}", FlipGoblinPlugin.BUILD, gate);
		}
	}

	/**
	 * The placed offer whose details screen is open, or null. Only consulted when no offer is being
	 * composed (composing wins, since its varp carries the item before any offer exists). GE_SELECTEDSLOT
	 * stays set while composing INTO an empty slot, so the EMPTY guard keeps pre-selection blank.
	 */
	private GrandExchangeOffer viewedOffer(int composingItemId)
	{
		if (composingItemId > 0)
		{
			return null;
		}
		int slot = client.getVarbitValue(VarbitID.GE_SELECTEDSLOT) - 1;
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (slot < 0 || offers == null || slot >= offers.length)
		{
			return null;
		}
		GrandExchangeOffer o = offers[slot];
		return o == null || o.getState() == GrandExchangeOfferState.EMPTY || o.getItemId() <= 0 ? null : o;
	}

	/** Sell-side offer states (mirrors GePositions.sideOf's SELL arm). */
	private static boolean sellSide(GrandExchangeOfferState s)
	{
		return s == GrandExchangeOfferState.SELLING
			|| s == GrandExchangeOfferState.SOLD
			|| s == GrandExchangeOfferState.CANCELLED_SELL;
	}

	private static final java.time.format.DateTimeFormatter HOVER_TIME =
		java.time.format.DateTimeFormatter.ofPattern("MMM d HH:mm");

	/**
	 * Draws one series in a translucent box at (0, 0) plus its readout panel to the right,
	 * because text over the lines was unreadable. The panel always shows high/low. Inside
	 * the box a crosshair snaps to the nearest bucket, and the panel reads out time, ask,
	 * bid, and spread (raw, before tax). The step lines, series colors, and the mirrored
	 * volume pane in the bottom fifth (ask up, bid down) match the website's lines view.
	 * {@code volSrc} supplies the volumes: the series itself for candle graphs, or the 5m
	 * companion grid for the 1m graph.
	 */
	private static void drawChart(Graphics2D g, PriceClient.Series s, PriceClient.Series volSrc,
		PriceClient.VolArrival volArrival, Color bg, int width, int sideWidth, int mx, int my,
		FlipGoblinConfig.Timeframe tf, PanelComponent side, int itemId, long refPrice)
	{
		final int h = CHART_H;
		final int pad = 3;
		g.setColor(bg);
		g.fillRect(0, 0, width, h);

		double min = Double.POSITIVE_INFINITY;
		double max = Double.NEGATIVE_INFINITY;
		for (int i = 0; i < s.ask.length; i++)
		{
			for (double v : new double[]{s.ask[i], s.bid[i]})
			{
				if (!Double.isNaN(v))
				{
					min = Math.min(min, v);
					max = Math.max(max, v);
				}
			}
		}
		if (!(max > min))
		{
			return; // flat/empty series: box only
		}

		int n = s.ask.length;
		double xStep = (double) (width - 2 * pad) / (n - 1);
		// Prices live in the top ~4/5 of the box; the bottom fifth is the volume pane (site parity).
		final int volH = h / 5;
		final int priceH = h - volH;

		// The website's step lines carry the last price across quiet buckets: a NaN side
		// means no trade that bucket, not price unknown. So carry each side forward before
		// drawing, and rarely traded items render plateaus instead of holes. Leading NaNs,
		// before the item's first data, stay blank. The 1m tick series arrives pre-carried.
		double[] ask = locf(s.ask);
		double[] bid = locf(s.bid);

		double[][] vols = mapVolumes(s, volSrc, n);
		double[] askVol = vols[0];
		double[] bidVol = vols[1];
		drawVolumePane(g, askVol, bidVol, volSrc != s, width, h, volH, pad, xStep);

		java.awt.Stroke prevStroke = g.getStroke();
		g.setStroke(new java.awt.BasicStroke(2f, java.awt.BasicStroke.CAP_BUTT, java.awt.BasicStroke.JOIN_MITER));
		drawSeriesLine(g, bid, BID_LINE, width, priceH, pad, min, max);
		drawSeriesLine(g, ask, ASK_LINE, width, priceH, pad, min, max);
		g.setStroke(prevStroke);
		// The purchase-price reference line while selling a tracked flip, drawn only when
		// it falls inside the plotted range. The panel's Purchase price row always has it.
		if (refPrice > 0 && refPrice >= min && refPrice <= max)
		{
			int ry = (int) (pad + (priceH - 2 * pad - 1) * (1 - (refPrice - min) / (max - min)));
			g.setColor(REF_LINE);
			g.drawLine(pad, ry, width - pad, ry);
		}
		// Dots only where the database actually has a fill, matching the website's 1m trade
		// markers. Candle series carry no flags and get none.
		drawTradeDots(g, bid, s.bidReal, BID_DOT, width, priceH, pad, min, max);
		drawTradeDots(g, ask, s.askReal, ASK_DOT, width, priceH, pad, min, max);

		addReadoutHeader(side, tf, sideWidth, min, max);
		if (volSrc != s)
		{
			addVolumeCountdown(side, volSrc, volArrival);
		}

		if (mx >= pad && mx <= width - pad && my >= 0 && my < h)
		{
			int i = Math.max(0, Math.min(n - 1, (int) Math.round((mx - pad) / xStep)));
			int cx = pad + (int) Math.round(i * xStep);
			g.setColor(new Color(255, 255, 255, 80));
			g.drawLine(cx, 2, cx, h - 3);
			markPoint(g, bid[i], BID_LINE, cx, priceH, pad, min, max);
			markPoint(g, ask[i], ASK_LINE, cx, priceH, pad, min, max);

			boolean hasAsk = !Double.isNaN(ask[i]);
			boolean hasBid = !Double.isNaN(bid[i]);
			if (s.time[i] > 0)
			{
				side.getChildren().add(LineComponent.builder()
					.left("Time")
					.right(HOVER_TIME.format(java.time.Instant.ofEpochSecond(s.time[i])
						.atZone(java.time.ZoneId.systemDefault())) + " (" + ago(s.time[i]) + ")")
					.rightColor(MUTED)
					.build());
			}
			side.getChildren().add(LineComponent.builder()
				.left("Ask").right(hasAsk ? Gp.exact((long) ask[i]) : "—").rightColor(ASK_LINE).build());
			side.getChildren().add(LineComponent.builder()
				.left("Bid").right(hasBid ? Gp.exact((long) bid[i]) : "—").rightColor(BID_LINE).build());
			if (hasAsk && hasBid)
			{
				side.getChildren().add(LineComponent.builder()
					.left("Spread").right(Gp.exact((long) (ask[i] - bid[i]))).rightColor(Color.WHITE).build());
			}
			// The flip math at the hovered bucket's prices: the sell tax at that ask, and
			// the after-tax margin of buying its bid and selling its ask.
			if (hasAsk)
			{
				long tax = SessionStats.geSellTax((long) ask[i], itemId);
				side.getChildren().add(LineComponent.builder()
					.left("Tax (ask)").right(Gp.exact(tax)).rightColor(MUTED).build());
				if (hasBid)
				{
					long margin = (long) ask[i] - tax - (long) bid[i];
					side.getChildren().add(LineComponent.builder()
						.left("Margin (after tax)").right(Gp.exact(margin))
						.rightColor(margin > 0 ? PROFIT : margin < 0 ? LOSS : MUTED)
						.build());
				}
			}
			if (!Double.isNaN(askVol[i]) || !Double.isNaN(bidVol[i]))
			{
				side.getChildren().add(LineComponent.builder()
					.left(volSrc != s ? "Vol (5m win)" : "Vol (ask/bid)")
					.right(vol(askVol[i]) + " / " + vol(bidVol[i]))
					.rightColor(MUTED)
					.build());
			}
		}

		g.translate(width + GAP, 0);
		side.render(g);
		g.translate(-(width + GAP), 0);
	}

	/**
	 * Maps each chart slot to its volumes from {@code volSrc} by bucket time. For candle
	 * graphs the source is the series itself. For the 1m graph the 5m grid resolves each
	 * minute to its window, drawing contiguous blocks like the site. NaN means no data.
	 * Volumes are never carried forward. Returns {askVol, bidVol}.
	 */
	private static double[][] mapVolumes(PriceClient.Series s, PriceClient.Series volSrc, int n)
	{
		double[] askVol = new double[n];
		double[] bidVol = new double[n];
		java.util.Arrays.fill(askVol, Double.NaN);
		java.util.Arrays.fill(bidVol, Double.NaN);
		if (volSrc != null && volSrc.askVol != null && volSrc.time.length > 1)
		{
			long vStart = volSrc.time[0];
			long vStep = volSrc.time[1] - volSrc.time[0];
			for (int i = 0; i < n; i++)
			{
				int vi = (int) Math.floorDiv(s.time[i] - vStart, vStep);
				if (vi >= 0 && vi < volSrc.time.length)
				{
					askVol[i] = volSrc.askVol[vi];
					bidVol[i] = volSrc.bidVol[vi];
				}
			}
		}
		return new double[][]{askVol, bidVol};
	}

	/** The readout panel's fixed rows: title, high, low, and the refresh countdown. */
	private static void addReadoutHeader(PanelComponent side, FlipGoblinConfig.Timeframe tf,
		int sideWidth, double min, double max)
	{
		side.getChildren().clear();
		side.setPreferredSize(new Dimension(sideWidth, 0));
		side.getChildren().add(TitleComponent.builder().text(tf.label).color(GOLD).build());
		side.getChildren().add(LineComponent.builder()
			.left(tf.shortName + " High").right(Gp.exact((long) max)).rightColor(Color.WHITE).build());
		side.getChildren().add(LineComponent.builder()
			.left(tf.shortName + " Low").right(Gp.exact((long) min)).rightColor(Color.WHITE).build());
		// Freshness. A plateau makes the refresh loop invisible, so count down to the next
		// bucket boundary, the moment the picture can actually shift. Once it crosses zero,
		// PriceClient retries on the fast cadence until the new bucket's data lands, so the
		// paint follows the data rather than the coarse TTL.
		long nextIn = tf.intervalSec - (System.currentTimeMillis() / 1000) % tf.intervalSec;
		side.getChildren().add(LineComponent.builder()
			.left("Next Update").right("in " + dur(nextIn)).rightColor(MUTED).build());
	}

	/**
	 * The 1m graph's volume rides the 5m windows, since ticks carry none, so it moves on a
	 * slower cadence than the price line. Count that down too, or the quiet pane reads as
	 * missing data. The Wiki publishes a window's volumes only after it closes, so the
	 * countdown is observation-driven: the next rollup is expected one window after the
	 * last one actually reached this client. Polling keeps retrying past zero ("due"), and
	 * the estimate self-corrects every cycle. Before the first observation, fall back to
	 * the boundary plus a typical publication lag.
	 */
	private static void addVolumeCountdown(PanelComponent side, PriceClient.Series volSrc,
		PriceClient.VolArrival volArrival)
	{
		long volStep = volSrc != null && volSrc.time.length > 1
			? volSrc.time[1] - volSrc.time[0] : 300;
		long nowSec = System.currentTimeMillis() / 1000;
		long nextVolIn;
		if (volArrival != null)
		{
			nextVolIn = volArrival.observedMs / 1000 + volStep - nowSec;
		}
		else
		{
			final long publishLag = 90;
			long since = nowSec % volStep;
			nextVolIn = since < publishLag ? publishLag - since : volStep + publishLag - since;
		}
		side.getChildren().add(LineComponent.builder()
			.left("Next Volume Update")
			.right(nextVolIn <= 0 ? "due" : "in " + dur(nextVolIn))
			.rightColor(MUTED)
			.build());
	}

	/** Formats a compact duration such as "1h 5m", "4m", or "32s". */
	private static String dur(long s)
	{
		long h = s / 3_600;
		long m = (s % 3_600) / 60;
		if (h > 0)
		{
			return h + "h" + (m > 0 ? " " + m + "m" : "");
		}
		return m > 0 ? m + "m" : s + "s";
	}

	/** Formats a relative age such as "2d 4h ago", "1h 23m ago", or "12s ago". */
	private static String ago(long epochSec)
	{
		long s = Math.max(0, System.currentTimeMillis() / 1000 - epochSec);
		long d = s / 86_400;
		long h = (s % 86_400) / 3_600;
		long m = (s % 3_600) / 60;
		if (d > 0)
		{
			return d + "d" + (h > 0 ? " " + h + "h" : "") + " ago";
		}
		if (h > 0)
		{
			return h + "h" + (m > 0 ? " " + m + "m" : "") + " ago";
		}
		return m > 0 ? m + "m ago" : s + "s ago";
	}

	/** A filled dot on the hovered bucket's value. Skipped when the side is NaN there. */
	private static void markPoint(Graphics2D g, double v, Color color, int cx, int h, int pad,
		double min, double max)
	{
		if (Double.isNaN(v))
		{
			return;
		}
		int yy = pad + (int) Math.round((h - 2 * pad - 1) * (1 - (v - min) / (max - min)));
		g.setColor(color);
		g.fillOval(cx - 2, yy - 2, 5, 5);
	}

	/**
	 * The website lines view's step interpolation: hold each bucket's value flat to the
	 * next x. One Path2D per gap-free run, stroked with butt caps, because per-segment
	 * drawLine left overlapping square caps at every vertex, which the client's
	 * stretched-mode upscale rendered as a dot at every point.
	 */
	private static void drawSeriesLine(Graphics2D g, double[] v, Color color, int width, int h,
		int pad, double min, double max)
	{
		g.setColor(color);
		int n = v.length;
		double xStep = (double) (width - 2 * pad) / (n - 1);
		java.awt.geom.Path2D.Double path = null;
		double prevY = 0;
		for (int i = 0; i < n; i++)
		{
			if (Double.isNaN(v[i]))
			{
				if (path != null)
				{
					g.draw(path);
					path = null;
				}
				continue;
			}
			double x = pad + i * xStep;
			double yy = pad + (h - 2 * pad - 1) * (1 - (v[i] - min) / (max - min));
			if (path == null)
			{
				path = new java.awt.geom.Path2D.Double();
				path.moveTo(x, yy);
			}
			else
			{
				path.lineTo(x, prevY); // hold flat
				path.lineTo(x, yy); // then step
			}
			prevY = yy;
		}
		if (path != null)
		{
			g.draw(path);
		}
	}

	/** Carries the last value forward: quiet buckets hold the previous price, and leading NaNs stay. */
	private static double[] locf(double[] v)
	{
		double[] out = v.clone();
		double cur = Double.NaN;
		for (int i = 0; i < out.length; i++)
		{
			if (Double.isNaN(out[i]))
			{
				out[i] = cur;
			}
			else
			{
				cur = out[i];
			}
		}
		return out;
	}

	// Volume bar colors: the website's ASK_VOL_COLOR / BID_VOL_COLOR exactly (0.5 alpha).
	private static final Color ASK_VOL = new Color(0xe8, 0xb0, 0x4f, 128);
	private static final Color BID_VOL = new Color(0x38, 0xbd, 0xf8, 128);

	/**
	 * The mirrored volume pane in the box's bottom fifth, matching the site: ask bars up
	 * from the midline, bid bars down, scaled to the window's max. Candle graphs draw
	 * per-bucket bars; {@code blocks}, the 1m graph's 5m-window volumes, draw contiguous,
	 * one block per window.
	 */
	private static void drawVolumePane(Graphics2D g, double[] askVol, double[] bidVol,
		boolean blocks, int width, int h, int volH, int pad, double xStep)
	{
		double maxVol = 0;
		for (int i = 0; i < askVol.length; i++)
		{
			for (double v : new double[]{askVol[i], bidVol[i]})
			{
				if (!Double.isNaN(v))
				{
					maxVol = Math.max(maxVol, v);
				}
			}
		}
		if (maxVol <= 0)
		{
			return;
		}
		int mid = h - volH / 2;
		int half = volH / 2 - 2;
		int bw = blocks ? (int) Math.ceil(xStep) : Math.max(2, (int) (xStep * 0.7));
		for (int i = 0; i < askVol.length; i++)
		{
			int x = pad + (int) Math.round(i * xStep) - bw / 2;
			if (!Double.isNaN(askVol[i]) && askVol[i] > 0)
			{
				int bh = Math.max(1, (int) Math.round(half * askVol[i] / maxVol));
				g.setColor(ASK_VOL);
				g.fillRect(x, mid - bh, bw, bh);
			}
			if (!Double.isNaN(bidVol[i]) && bidVol[i] > 0)
			{
				int bh = Math.max(1, (int) Math.round(half * bidVol[i] / maxVol));
				g.setColor(BID_VOL);
				g.fillRect(x, mid, bw, bh);
			}
		}
	}

	private static String vol(double v)
	{
		return Double.isNaN(v) ? "—" : Gp.shortForm((long) v);
	}

	/** A small dot on each slot where a real fill landed, like the site's 1m markers. No-op without flags. */
	private static void drawTradeDots(Graphics2D g, double[] v, boolean[] real, Color color,
		int width, int h, int pad, double min, double max)
	{
		if (real == null)
		{
			return;
		}
		g.setColor(color);
		int n = v.length;
		double xStep = (double) (width - 2 * pad) / (n - 1);
		for (int i = 0; i < n; i++)
		{
			if (!real[i] || Double.isNaN(v[i]))
			{
				continue;
			}
			int x = pad + (int) Math.round(i * xStep);
			int yy = pad + (int) Math.round((h - 2 * pad - 1) * (1 - (v[i] - min) / (max - min)));
			g.fillOval(x - 2, yy - 2, 4, 4);
		}
	}

	private static String numOrDash(Long n)
	{
		return Gp.shortOrDash(n);
	}
}

package com.flipgoblin;

import java.util.ArrayList;
import java.util.List;

/**
 * Tracks GE buy-limit usage seen this session. The game's rule: an item's 4-hour limit
 * window opens at the first buy after the previous window expired, every buy inside the
 * window counts toward the limit, and the count fully resets when the window ends.
 *
 * Only buys the plugin saw are counted. Buys made before the plugin ran are invisible, so
 * the count is usually a lower bound and the UI shows "≥". Fills recovered at login have
 * uncertain times, so they only count what can be proven; see {@link #usage} for how.
 */
final class GeLimits
{
	static final long WINDOW_MS = 4 * 60 * 60 * 1000L;

	private GeLimits()
	{
	}

	/** One item's provable buy-limit usage. */
	static final class Usage
	{
		/** Units provably bought in a window still active now. */
		final long used;
		/** The latest possible reset time (epoch ms). With hedged set, the real reset may come sooner. */
		final long resetAtMs;
		/** True when the whole window was watched live, so the count is exact. */
		final boolean exact;
		/** True when recovered fills contributed, so the UI hedges the reset time. */
		final boolean hedged;

		Usage(long used, long resetAtMs, boolean exact, boolean hedged)
		{
			this.used = used;
			this.resetAtMs = resetAtMs;
			this.exact = exact;
			this.hedged = hedged;
		}
	}

	/**
	 * Returns the usage of the window active at {@code now}, or null when no usage can be
	 * proven. Records are read in list order, which is event order. {@code buyLimit} is
	 * the item's 4-hour limit, or 0 when unknown.
	 *
	 * The count is exact rather than a lower bound when the whole window was watched: while
	 * this client is logged in the account cannot trade anywhere else, so if the window
	 * opened inside our unbroken observation span and every counted fill was seen live,
	 * nothing was missed. The UI drops the ≥/≤ markers in that case.
	 *
	 * Recovered fills need more care, because we only know each one happened somewhere
	 * between its offlineSince bound and its detection time. Counting them at detection
	 * time would pin the window at login and claim "limit spent" long after the real limit
	 * may have reset. So the count is what survives even when every recovered fill is
	 * placed as early as its bounds and the buy limit allow, which is the timeline that
	 * frees the limit soonest. If even that timeline leaves an active window, the usage is
	 * provable. If not, nothing can be claimed and the result is null. For example, buying
	 * two limits overnight proves the limit is still spent while the offline gap is under
	 * eight hours (the second window cannot have expired), and proves nothing after that.
	 * When recovered fills contributed, the hedged flag is set and the reset time is only
	 * an upper bound (the real reset may come sooner).
	 */
	static Usage usage(List<TradeRecord> records, int itemId, long now, long observedSince, long buyLimit)
	{
		long anchor = 0;
		long used = 0;
		boolean anyRecovered = false;
		List<TradeRecord> buys = new ArrayList<>();
		for (TradeRecord r : records)
		{
			// Only slot-observed fills count. History imports (slot -1) can be arbitrarily
			// old with estimated times, and counting those at detection time would pollute
			// the window with days-old buys.
			if (r.itemId != itemId || r.side != TradeRecord.Side.BUY || r.slot < 0)
			{
				continue;
			}
			buys.add(r);
			if (anchor == 0 || r.timestamp >= anchor + WINDOW_MS)
			{
				anchor = r.timestamp; // first buy opens the window; a post-expiry buy opens the next
				used = 0;
				anyRecovered = false;
			}
			used += r.quantity;
			anyRecovered |= r.recovered;
		}
		if (anchor == 0 || now >= anchor + WINDOW_MS)
		{
			return null;
		}
		if (!anyRecovered)
		{
			boolean exact = observedSince > 0 && observedSince <= anchor;
			return new Usage(used, anchor + WINDOW_MS, exact, false);
		}
		long provable = provableUsed(buys, now, buyLimit);
		if (provable <= 0)
		{
			return null;
		}
		return new Usage(provable, anchor + WINDOW_MS, false, true);
	}

	/**
	 * The buy count that provably still lies in an active window when every recovered fill
	 * is placed as early as its time bounds and the buy limit allow. Live fills sit at
	 * their real times. A recovered fill starts at its offlineSince bound and waits for a
	 * window reset when the current one is full. A recovered fill with no offlineSince
	 * bound could be arbitrarily old and proves nothing, so it is skipped. If this early
	 * placement would force a live fill into an already-full window, the model does not
	 * fit the data, and only the live fills are counted.
	 */
	private static long provableUsed(List<TradeRecord> buys, long now, long buyLimit)
	{
		List<TradeRecord> placeable = new ArrayList<>();
		for (TradeRecord r : buys)
		{
			if (!r.recovered || r.offlineSince > 0)
			{
				placeable.add(r);
			}
		}
		// Sort by earliest possible time; the sort is stable, so same-time fills keep event order.
		placeable.sort((a, b) -> Long.compare(
			a.recovered ? a.offlineSince : a.timestamp,
			b.recovered ? b.offlineSince : b.timestamp));
		long anchor = -1;
		long used = 0;
		long cursor = 0;
		for (TradeRecord r : placeable)
		{
			long q = r.quantity;
			long t = Math.max(r.recovered ? r.offlineSince : r.timestamp, cursor);
			while (q > 0)
			{
				if (anchor < 0 || t >= anchor + WINDOW_MS)
				{
					anchor = t;
					used = 0;
				}
				long room = buyLimit > 0 ? buyLimit - used : q;
				if (room <= 0)
				{
					if (!r.recovered)
					{
						// A live fill cannot wait for a reset; its time is real. The
						// early-placement model is infeasible, so count only live fills.
						return liveOnlyUsed(buys, now);
					}
					t = anchor + WINDOW_MS;
					continue;
				}
				long take = Math.min(q, room);
				used += take;
				q -= take;
				cursor = t;
			}
		}
		return anchor >= 0 && now < anchor + WINDOW_MS ? used : 0;
	}

	/** The active-window count over live fills only, ignoring every recovered fill. */
	private static long liveOnlyUsed(List<TradeRecord> buys, long now)
	{
		long anchor = 0;
		long used = 0;
		for (TradeRecord r : buys)
		{
			if (r.recovered)
			{
				continue;
			}
			if (anchor == 0 || r.timestamp >= anchor + WINDOW_MS)
			{
				anchor = r.timestamp;
				used = 0;
			}
			used += r.quantity;
		}
		return anchor > 0 && now < anchor + WINDOW_MS ? used : 0;
	}

	/** Formats a reset instant as "HH:mm" local time. */
	static String resetTime(long epochMs)
	{
		return java.time.format.DateTimeFormatter.ofPattern("HH:mm").format(
			java.time.Instant.ofEpochMilli(epochMs).atZone(java.time.ZoneId.systemDefault()));
	}
}

package com.flipgoblin;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Turns RuneLite's {@code GrandExchangeOffer} events into individual fill records. RuneLite
 * reports an offer's cumulative state, not deltas, and replays every non-empty slot on
 * login, so each event is diffed against a per-slot baseline to find what actually changed.
 * Pure and single-threaded (RuneLite events arrive on the client thread).
 *
 * The differ can start empty, which makes the login replay only establish baselines, or it
 * can be seeded with the previous session's saved baselines, in which case fills that
 * happened while offline show up as the first diff. Both cases are the same operation,
 * diffing against a prior baseline; only the seed source differs.
 *
 * Recovered fills are marked. The game exposes no fill timestamps, so a fill's
 * {@code timestamp} is always the time we detected it. For a fill recovered at login that
 * can be long after the real fill, so the record carries {@code recovered=true} and
 * {@code offlineSince}, bounding the true fill time to somewhere between the two.
 */
public final class GeOfferDiffer
{
	/** Last-seen cumulative for a slot's current offer. Public so persistence can round-trip it via Gson. */
	public static final class SlotState
	{
		public final int itemId;
		public final int quantitySold;
		public final long spent;
		/** When this slot state was last seen live (epoch ms). Bounds any recovered fill's time window. */
		public final long lastSeen;
		/**
		 * Offer identity guards: side, total quantity, and set price. Item id and counters
		 * alone are a weak identity. Without these, a stale re-fire of a completed offer's
		 * state, diffed against a fresh baseline of the same item, would book the whole dead
		 * offer as a live fill.
		 */
		public final TradeRecord.Side side;
		public final int totalQuantity;
		public final long price;

		public SlotState(int itemId, int quantitySold, long spent, long lastSeen,
			TradeRecord.Side side, int totalQuantity, long price)
		{
			this.itemId = itemId;
			this.quantitySold = quantitySold;
			this.spent = spent;
			this.lastSeen = lastSeen;
			this.side = side;
			this.totalQuantity = totalQuantity;
			this.price = price;
		}

	}

	private final Map<Integer, SlotState> baseline = new HashMap<>();
	/** Slots whose baseline came from the saved seed and have not yet seen a live event this session. */
	private final Set<Integer> seededSlots = new HashSet<>();

	public GeOfferDiffer()
	{
	}

	/** Seeds the differ with the previous session's baselines so offline fills can be recovered. */
	public GeOfferDiffer(Map<Integer, SlotState> seed)
	{
		if (seed != null)
		{
			baseline.putAll(seed);
			seededSlots.addAll(seed.keySet());
		}
	}

	/** A copy of the current per-slot baselines, for saving. */
	public Map<Integer, SlotState> snapshotBaseline()
	{
		return new HashMap<>(baseline);
	}

	/**
	 * Detects the logout EMPTY storm. When the client leaves the logged-in state it clears
	 * its GE memory and fires an EMPTY event for every slot. Those are client-side resets,
	 * not collections. Folding one in would wipe the slot's baseline, and fills landing
	 * while offline could then never be recovered on the next login. Callers must drop the
	 * event entirely when this returns true, as RuneLite's own GE plugin does.
	 */
	public static boolean isLogoutClear(GrandExchangeOfferState offerState, net.runelite.api.GameState gameState)
	{
		return offerState == GrandExchangeOfferState.EMPTY && gameState != net.runelite.api.GameState.LOGGED_IN;
	}

	/**
	 * Folds one offer event into the baseline. Returns a fill only when the event carries
	 * newly transacted quantity for the same ongoing offer. The first sighting of an offer
	 * only records a baseline, which is what keeps the login replay silent.
	 */
	public Optional<TradeRecord> onOffer(int slot, OfferSnapshot next, long ts)
	{
		// Any live event on a slot ends its seeded status. Remember whether this event was the first.
		boolean wasSeeded = seededSlots.remove(slot);

		if (next.state == GrandExchangeOfferState.EMPTY)
		{
			// The slot was collected or cleared. Forget its baseline so the next offer starts fresh.
			baseline.remove(slot);
			return Optional.empty();
		}

		SlotState prev = baseline.get(slot);
		// Anything that fails the identity check means a different offer now occupies the
		// slot, so record a baseline and emit nothing (see OfferStates.sameOffer).
		TradeRecord.Side nextSide = OfferStates.sideOf(next.state);
		boolean sameOffer = prev != null && OfferStates.sameOffer(prev.itemId, prev.side,
			prev.totalQuantity, prev.price, prev.quantitySold, prev.spent, next);

		baseline.put(slot, new SlotState(next.itemId, next.quantitySold, next.spent, ts,
			nextSide, next.totalQuantity, next.price));

		if (!sameOffer)
		{
			// A new or unknown offer, or a login replay against an empty baseline. Baseline only.
			return Optional.empty();
		}

		int qtyDelta = next.quantitySold - prev.quantitySold;
		if (qtyDelta <= 0)
		{
			// A state-only transition with no new fill, such as BUYING to BOUGHT at the same quantity.
			return Optional.empty();
		}

		long spentDelta = next.spent - prev.spent;
		// A delta can span units filled at different prices, so the per-item price is an average.
		// The exact spent delta is kept on the record so no coins are lost to rounding.
		long price = Math.round((double) spentDelta / qtyDelta);
		// A fill against a still-seeded baseline happened while we were not watching. Mark it
		// recovered and bound its true time instead of letting it read as a fresh trade.
		long offlineSince = wasSeeded ? prev.lastSeen : 0;
		return Optional.of(new TradeRecord(
			next.itemId, nextSide, price, qtyDelta, spentDelta, slot, ts, wasSeeded, offlineSince));
	}
}

package com.flipgoblin;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;

/**
 * The 8 GE slots as live positions: every ask and bid the player has standing, with its
 * fill progress and lifecycle phase. Rebuilt for free on every login because RuneLite
 * replays all slot states, so nothing needs persisting.
 *
 * Lifecycle: WORKING (offer live and filling), then COMPLETE (fully bought or sold) or
 * CANCELLED (aborted), then collected, at which point an EMPTY event removes the slot.
 * OSRS has no in-place "modify offer". A modification is a cancel plus a re-place, and
 * this model shows it as exactly that.
 *
 * This is also the source of GE-side assets for the ledger, but only what the GE machine
 * is provably holding: a WORKING buy's unfilled coin escrow and a WORKING sell's unsold
 * stock. Everything waiting in the collection box counts zero here, because any stack can
 * be collected at any moment without an event firing, and counting it would double-count.
 * {@link CollectLedger} adds the collectable value back from witnessed signals.
 *
 * Pure and single-threaded (client thread), like the differ.
 */
public final class GePositions
{
	public enum Phase
	{
		WORKING, COMPLETE, CANCELLED
	}

	public static final class Position
	{
		public final int slot;
		public final int itemId;
		public final TradeRecord.Side side;
		public final long price;
		public final int totalQuantity;
		public final int quantitySold;
		public final long spent;
		public final Phase phase;
		/** When we first saw this offer in the slot. Survives across events, resets when the slot is reused. */
		public final long firstSeen;
		public final long lastUpdate;

		Position(int slot, int itemId, TradeRecord.Side side, long price, int totalQuantity, int quantitySold,
			long spent, Phase phase, long firstSeen, long lastUpdate)
		{
			this.slot = slot;
			this.itemId = itemId;
			this.side = side;
			this.price = price;
			this.totalQuantity = totalQuantity;
			this.quantitySold = quantitySold;
			this.spent = spent;
			this.phase = phase;
			this.firstSeen = firstSeen;
			this.lastUpdate = lastUpdate;
		}
	}

	private final Map<Integer, Position> bySlot = new HashMap<>();

	/** Folds in one offer event. EMPTY means collected or cleared, and the position leaves the board. */
	public void onOffer(int slot, OfferSnapshot next, long ts)
	{
		if (next.state == GrandExchangeOfferState.EMPTY)
		{
			bySlot.remove(slot);
			return;
		}
		Position prev = bySlot.get(slot);
		// Anything that fails the identity check means the slot was reused, and the
		// position's clock restarts (see OfferStates.sameOffer).
		boolean sameOffer = prev != null && OfferStates.sameOffer(prev.itemId, prev.side,
			prev.totalQuantity, prev.price, prev.quantitySold, prev.spent, next);
		long firstSeen = sameOffer ? prev.firstSeen : ts;
		bySlot.put(slot, new Position(slot, next.itemId, OfferStates.sideOf(next.state), next.price,
			next.totalQuantity, next.quantitySold, next.spent, OfferStates.phaseOf(next.state), firstSeen, ts));
	}

	/** Current positions, slot-ordered. */
	public List<Position> active()
	{
		List<Position> out = new ArrayList<>(bySlot.values());
		out.sort((a, b) -> Integer.compare(a.slot, b.slot));
		return out;
	}

	/**
	 * Items the GE machine is provably holding: only a WORKING sell's unsold remainder (see
	 * the class doc for why everything else counts zero). Zero-quantity pairs are omitted.
	 */
	public int[][] heldItemPairs()
	{
		List<int[]> pairs = new ArrayList<>();
		for (Position p : bySlot.values())
		{
			// Only a WORKING sell's unsold remainder is still on the GE machine; all else counts zero.
			int qty = (p.side == TradeRecord.Side.SELL && p.phase == Phase.WORKING)
				? p.totalQuantity - p.quantitySold
				: 0;
			if (qty > 0)
			{
				pairs.add(new int[]{p.itemId, qty});
			}
		}
		return pairs.toArray(new int[0][]);
	}

	/**
	 * Coins the GE machine is provably holding: only a WORKING buy's unfilled escrow,
	 * {@code price × (total − sold)} (see the class doc for why everything else counts zero).
	 */
	public long heldCoins()
	{
		long coins = 0;
		for (Position p : bySlot.values())
		{
			// Only a WORKING buy's unfilled escrow is committed to the machine; all else counts zero.
			if (p.side == TradeRecord.Side.BUY && p.phase == Phase.WORKING)
			{
				coins += p.price * (long) (p.totalQuantity - p.quantitySold);
			}
		}
		return coins;
	}

}

package com.flipgoblin;

/**
 * Builds the hover-tooltip text for items in the GE window, using RuneLite's tooltip markup
 * ({@code <col>} tags and {@code </br>} line breaks). No client classes are imported, so
 * the class stays pure and unit-testable.
 */
final class GeTooltip
{
	private static final String GOLD = "d4af37";
	private static final String PROFIT = "3fb950";
	private static final String LOSS = "f85149";
	private static final String MUTED = "9e9e9e";

	private GeTooltip()
	{
	}

	/** Multi-line tooltip for one item's market data. */
	static String build(PriceClient.ItemPrices p)
	{
		return build(p, null, null);
	}

	/**
	 * Same as {@link #build(PriceClient.ItemPrices)}, plus the session's 4-hour buy-limit
	 * usage when a window is active. {@code resetsAt} is formatted by the caller so this
	 * class stays free of clocks and timezones.
	 */
	static String build(PriceClient.ItemPrices p, GeLimits.Usage usage, String resetsAt)
	{
		StringBuilder sb = new StringBuilder();
		if (p.name != null)
		{
			sb.append(col(GOLD, p.name)).append("</br>");
		}
		sb.append("Buy ").append(Gp.shortOrDash(p.ask)).append(" · Sell ").append(Gp.shortOrDash(p.bid)).append("</br>");
		String marginColor = p.margin == null ? MUTED : p.margin > 0 ? PROFIT : LOSS;
		sb.append("Margin ").append(col(marginColor, Gp.shortOrDash(p.margin)
			+ (p.roi == null ? "" : String.format(" (%.1f%%)", p.roi * 100)))).append(" after tax")
			.append(p.tax == null ? "" : " (" + Gp.shortOrDash(p.tax) + ")").append("</br>");
		sb.append(col(MUTED, "24h vol " + Gp.shortOrDash(p.askVolume) + "/" + Gp.shortOrDash(p.bidVolume)
			+ " · Limit " + (p.buyLimit == null ? "—" : String.valueOf(p.buyLimit))));
		if (usage != null)
		{
			boolean capped = p.buyLimit != null && usage.used >= p.buyLimit;
			// The bought count is a lower bound, except when the whole window was watched
			// live. Then the count and "left" are exact.
			sb.append("</br>").append(col(capped ? LOSS : MUTED,
				"Bought " + (usage.exact ? "" : "≥") + usage.used + (p.buyLimit == null ? ""
					: "/" + p.buyLimit + " · left " + (usage.exact ? "" : "≤")
						+ Math.max(0, p.buyLimit - usage.used))
					+ " · limit resets " + resetsAt));
		}
		return sb.toString();
	}

	/**
	 * Same as {@link #build(PriceClient.ItemPrices, long[], String)}, plus the session's
	 * most recent fill per side. Either fill may be null. The times are formatted by the
	 * caller, for the same reason as {@code resetsAt}.
	 */
	static String build(PriceClient.ItemPrices p, GeLimits.Usage usage, String resetsAt,
		TradeRecord lastBuy, String buyAt, TradeRecord lastSell, String sellAt)
	{
		StringBuilder sb = new StringBuilder(build(p, usage, resetsAt));
		if (lastBuy != null || lastSell != null)
		{
			sb.append("</br>").append(col(MUTED, "Last"
				+ (lastBuy == null ? "" : " buy " + Gp.shortOrDash(lastBuy.price) + " ×" + lastBuy.quantity + " " + buyAt)
				+ (lastBuy != null && lastSell != null ? " ·" : "")
				+ (lastSell == null ? "" : " sell " + Gp.shortOrDash(lastSell.price) + " ×" + lastSell.quantity + " " + sellAt)));
		}
		return sb.toString();
	}

	/**
	 * The flipper's unrealized margin line for a hovered SELL offer: the offer price net of tax
	 * minus the last buy-in, per item and across the unsold remainder. Sign-colored.
	 */
	static String flipLine(long each, long total)
	{
		return col(each > 0 ? PROFIT : each < 0 ? LOSS : MUTED,
			"Flip " + Gp.exact(each) + "/ea · " + Gp.shortOrDash(total) + " unrealized");
	}

	private static String col(String hex, String text)
	{
		return "<col=" + hex + ">" + text + "</col>";
	}

}

package com.flipgoblin;

import java.util.Locale;

/**
 * Formats exact gp amounts for real price records such as fills, standing offers, live
 * ask/bid, margins, and tax. A real price always shows every digit ("14,000"), never an
 * abbreviation ("14.0k"), because flipping is won in the last few coins. Aggregate totals
 * like session P/L still use the short k/m form.
 */
final class Gp
{
	private Gp()
	{
	}

	static String exact(long n)
	{
		return String.format(Locale.US, "%,d", n);
	}

	static String exactOrDash(Long n)
	{
		return n == null ? "—" : exact(n);
	}

	/** The short k/m/b form for aggregate totals: "2.1b", "1.4m", "23.5k", "950". */
	static String shortForm(long n)
	{
		long abs = Math.abs(n);
		String s;
		if (abs >= 999_950_000)
		{
			// Starts where "%.1fm" would round up to "1000.0m".
			s = String.format(Locale.US, "%.1fb", abs / 1_000_000_000.0);
		}
		else if (abs >= 1_000_000)
		{
			s = String.format(Locale.US, "%.1fm", abs / 1_000_000.0);
		}
		else if (abs >= 10_000)
		{
			s = String.format(Locale.US, "%.1fk", abs / 1_000.0);
		}
		else
		{
			s = Long.toString(abs);
		}
		return (n < 0 ? "-" : "") + s;
	}

	static String shortOrDash(Long n)
	{
		return n == null ? "—" : shortForm(n);
	}
}

package com.flipgoblin;

/** Item ids the plugin refers to by number. */
final class ItemIds
