package com.flipgoblin;

import java.util.ArrayList;
import java.util.List;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfile;
import net.runelite.client.config.RuneScapeProfileType;

/**
 * Lists and unlinks the characters that hold an account token. Each token is stored per
 * RuneScape profile, and this class enumerates those stores across all profiles so the
 * Settings tab can manage them without logging each character in. The token itself never
 * leaves this machine's config; only a masked tail is ever displayed.
 */
final class LinkedCharacters
{
	/** Shared with FlipGoblinPlugin, which stores tokens under these same keys. */
	static final String TOKEN_PROFILE_KEY = "apiTokenChar";
	static final String TOKEN_OWNER_KEY = "apiTokenOwnerProfile";

	private LinkedCharacters()
	{
	}

	/** One linked character: profile identity + display bits. */
	static final class Row
	{
		final String profileKey;
		final String name;
		/** The token's last 4 characters, enough to match against the website's list. */
		final String tokenTail;
		/** True for the character currently logged in. Its token drives the syncs. */
		final boolean current;

		Row(String profileKey, String name, String tokenTail, boolean current)
		{
			this.profileKey = profileKey;
			this.name = name;
			this.tokenTail = tokenTail;
			this.current = current;
		}
	}

	/** Masks a token down to its last 4 characters for display. Pure. */
	static String tail(String token)
	{
		String t = token == null ? "" : token.trim();
		return t.length() <= 4 ? t : "…" + t.substring(t.length() - 4);
	}

	/** Display name for a profile row. Non-standard worlds (leagues, beta, DMM) get a type tag. Pure. */
	static String displayName(String name, RuneScapeProfileType type)
	{
		String base = name == null || name.isEmpty() ? "(unnamed)" : name;
		return type == null || type == RuneScapeProfileType.STANDARD
			? base
			: base + " (" + type.name().toLowerCase().replace('_', ' ') + ")";
	}

	/** Every profile holding a token, current character first, then by name. */
	static List<Row> list(ConfigManager cm)
	{
		String currentKey = cm.getRSProfileKey();
		List<Row> rows = new ArrayList<>();
		List<RuneScapeProfile> profiles = cm.getRSProfiles();
		if (profiles == null)
		{
			return rows; // pre-session/harness: nothing enumerable yet
		}
		for (RuneScapeProfile p : profiles)
		{
			String key = p.getKey();
			if (key == null)
			{
				continue;
			}
			String token = cm.getConfiguration(FlipGoblinPlugin.CONFIG_GROUP, key, TOKEN_PROFILE_KEY);
			if (token == null || token.trim().isEmpty())
			{
				continue;
			}
			rows.add(new Row(key, displayName(p.getDisplayName(), p.getType()), tail(token),
				key.equals(currentKey)));
		}
		rows.sort((a, b) -> a.current != b.current ? (a.current ? -1 : 1) : a.name.compareToIgnoreCase(b.name));
		return rows;
	}

	/**
	 * Unlinks one character by dropping its stored token. If the visible token field is
	 * currently mirroring this profile, the field and the owner marker are cleared too.
	 * Leaving them in place would let the next login re-adopt the token we just removed.
	 */
	static void unlink(ConfigManager cm, String profileKey)
	{
		cm.unsetConfiguration(FlipGoblinPlugin.CONFIG_GROUP, profileKey, TOKEN_PROFILE_KEY);
		String owner = cm.getConfiguration(FlipGoblinPlugin.CONFIG_GROUP, TOKEN_OWNER_KEY);
		if (profileKey.equals(owner))
		{
			cm.unsetConfiguration(FlipGoblinPlugin.CONFIG_GROUP, TOKEN_OWNER_KEY);
			// Fires the plugin's ConfigChanged handler, which re-clears profile/owner idempotently.
			cm.setConfiguration(FlipGoblinPlugin.CONFIG_GROUP, "apiToken", "");
		}
	}
}

package com.flipgoblin;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Judges whether anyone used the account between our sessions, using the welcome screen's
 * "You last logged in … ago" line. Despite its wording, that line measures from the END of
 * the previous session, not from its login. This was established against client logs.
 * We therefore compare the report against our own recorded logout time, as durations, so
 * clock differences cancel out. Pure logic only; widget reading and state live in the plugin.
 *
 * Verdicts (every uncertainty resolves to the cautious side):
 * - ACQUITTED: the reported session end matches our recorded logout within display
 *   rounding, at minute precision or finer. This rules out a hidden session almost
 *   entirely, because a hidden session ends after our logout and its report would read
 *   newer than ours. The one residual: a hidden session that starts and ends inside the
 *   same rounding step as our logout cannot be detected.
 * - CONVICTED: the report is newer than our recorded logout. Someone was online after us.
 * - AMBIGUOUS: no stored record, unparseable text, hour or day rounding (wide enough to
 *   hide a whole session), or a report older than our own logout, which means our own
 *   record cannot be trusted.
 */
final class LoginCustody
{
	/**
	 * Slack for rounding and timing: the heartbeat can leave lastSeen up to about a minute
	 * stale after a crash, the server records a hard-close logout with its own lag, and the
	 * display rounds down to its finest unit. 90 seconds covers all of these. A hidden
	 * session shorter than the slack could not reach the bank anyway.
	 */
	static final long SLACK_MS = 90_000;

	/**
	 * Acquittal requires the display to round at minute precision or finer. Every observed
	 * format carries minutes even at hour scale ("7 hours, 59 minutes ago"). A coarser
	 * display leaves a window a whole session could hide in, so it judges AMBIGUOUS.
	 */
	static final long MAX_ACQUIT_GRANULARITY_MS = 60_000;

	enum Verdict
	{
		ACQUITTED, CONVICTED, AMBIGUOUS
	}

	/** Our saved per-character session record. */
	static final class SessionRecord
	{
		/** Last fresh login (epoch ms, 0 = unknown). Diagnostics only; the welcome report
		 * measures session end, so the judge never compares logins. */
		long freshLoginMs;
		/** Last login of any kind (fresh, hop, or reconnect). Diagnostics only. */
		long anyLoginMs;
		/** Our recorded logout time: refreshed by a heartbeat about once a minute and stamped
		 * on clean logout. This is what the judge compares against the welcome report. A
		 * crash leaves it up to one heartbeat stale, which SLACK_MS absorbs. */
		long lastSeenMs;
		/** True while the stored bank snapshot can still be trusted: set when the bank is
		 * opened, carried across a logout only by an ACQUITTED verdict, and false the moment
		 * a gap is not provably ours. */
		boolean bankChainTrusted;
	}

	/** A parsed "You last logged in …" line: the rounded-down duration and how finely it was displayed. */
	static final class Report
	{
		/** The reported gap in ms, rounded down; "1 hour, 1 min" parses to 61 minutes. */
		final long agoMs;
		/** The finest unit displayed, in ms. This is the width of the rounding step. */
		final long granularityMs;

		Report(long agoMs, long granularityMs)
		{
			this.agoMs = agoMs;
			this.granularityMs = granularityMs;
		}
	}

	/** The verdict plus the age of our own recorded logout, for the "ours" part of the display. */
	static final class Result
	{
		final Verdict verdict;
		/** How old our recorded session end was when judged. 0 means no record. */
		final long ourAgoMs;

		Result(Verdict verdict, long ourAgoMs)
		{
			this.verdict = verdict;
			this.ourAgoMs = ourAgoMs;
		}
	}

	private static final Pattern REPORT = Pattern.compile("(?i)last logged in\\s+(.+?)\\s+ago");
	private static final Pattern COMPONENT = Pattern.compile(
		"(?i)^(\\d{1,6}|an?|one)\\s+(day|hour|min(?:ute)?|sec(?:ond)?)s?$");

	private LoginCustody()
	{
	}

	/**
	 * Parses the welcome-screen line into a rounded-down duration. Formats seen live include
	 * "You last logged in 40 minutes ago.", "…a minute ago.", and "1 hour, 1 min ago". So:
	 * comma-separated (value, unit) parts, where a/an/one mean 1 and the units are
	 * day/hour/min(ute)/sec(ond) with an optional plural. Returns null for anything else,
	 * and the caller must display that failure as AMBIGUOUS rather than hide it.
	 */
	static Report parse(String rawText)
	{
		if (rawText == null)
		{
			return null;
		}
		String plain = rawText.replaceAll("<[^>]*>", " ").replaceAll("\\s+", " ").trim();
		Matcher m = REPORT.matcher(plain);
		if (!m.find())
		{
			return null;
		}
		long total = 0;
		long gran = 0;
		for (String part : m.group(1).split(",\\s*|\\s+and\\s+"))
		{
			Matcher pm = COMPONENT.matcher(part.trim());
			if (!pm.matches())
			{
				return null;
			}
			String q = pm.group(1).toLowerCase();
			long n = q.equals("a") || q.equals("an") || q.equals("one") ? 1 : Long.parseLong(q);
			String unit = pm.group(2).toLowerCase();
			long unitMs = unit.startsWith("day") ? 86_400_000L
				: unit.startsWith("hour") ? 3_600_000L
				: unit.startsWith("min") ? 60_000L : 1_000L;
			total += n * unitMs;
			gran = gran == 0 ? unitMs : Math.min(gran, unitMs);
		}
		return gran == 0 ? null : new Report(total, gran);
	}

	/**
	 * The judgement. The report says when the most recent session ended, and a rounded-down
	 * display means the true instant lies somewhere in [agoMs, agoMs + granularity).
	 * Compare our recorded logout:
	 *
	 * - Inside that window (with slack) at minute precision or finer: ACQUITTED. A hidden
	 *   session would end after our logout, so its report would read newer than our record.
	 * - Report newer than our logout: CONVICTED. Someone was online after us.
	 * - Report older than our logout: AMBIGUOUS, not convicted. The server says the last
	 *   session ended before we think we were online, so our own record is what cannot be
	 *   trusted (a clock jump or a lost config write).
	 * - Inside the window but with hour or day rounding: AMBIGUOUS. The step is wide
	 *   enough to hide an entire session.
	 *
	 * The recorded login instants are never compared. Doing so would falsely convict every
	 * reconnect, because the report measures session end. They stay for diagnostics only.
	 */
	static Result judge(Report report, SessionRecord prev, long nowMs)
	{
		if (prev == null || prev.lastSeenMs <= 0)
		{
			return new Result(Verdict.AMBIGUOUS, 0);
		}
		long seenAgo = nowMs - prev.lastSeenMs;
		if (report == null)
		{
			return new Result(Verdict.AMBIGUOUS, seenAgo);
		}
		if (seenAgo >= report.agoMs + report.granularityMs + SLACK_MS)
		{
			return new Result(Verdict.CONVICTED, seenAgo);
		}
		if (seenAgo < report.agoMs - SLACK_MS)
		{
			return new Result(Verdict.AMBIGUOUS, seenAgo);
		}
		return new Result(report.granularityMs <= MAX_ACQUIT_GRANULARITY_MS
			? Verdict.ACQUITTED : Verdict.AMBIGUOUS, seenAgo);
	}

	/** Formats a compact duration such as "1h01m", "40m", or "2d3h". */
	static String fmtDuration(long ms)
	{
		long min = Math.max(0, ms) / 60_000;
		long d = min / 1_440;
		long h = min % 1_440 / 60;
		long m = min % 60;
		if (d > 0)
		{
			return d + "d" + (h > 0 ? h + "h" : "");
		}
		if (h > 0)
		{
			return h + "h" + String.format("%02dm", m);
		}
		return m + "m";
	}
}

package com.flipgoblin;

import net.runelite.api.GrandExchangeOfferState;

/**
 * A plain-data copy of a {@code GrandExchangeOffer} taken at one event. It decouples
 * {@link GeOfferDiffer} from the RuneLite interface so tests can build fixtures without a
 * client mock. {@code spent} is widened to {@code long} so delta arithmetic cannot overflow.
 */
public final class OfferSnapshot
{
	public final int itemId;
	public final GrandExchangeOfferState state;
	public final int totalQuantity;
	public final int quantitySold;
	public final long spent;
	/** The offer's per-item price. The position tracker and the escrow math both use it. */
	public final long price;

	public OfferSnapshot(int itemId, GrandExchangeOfferState state, int totalQuantity, int quantitySold, long spent,
		long price)
	{
		this.itemId = itemId;
		this.state = state;
		this.totalQuantity = totalQuantity;
		this.quantitySold = quantitySold;
		this.spent = spent;
		this.price = price;
	}
}

package com.flipgoblin;

import net.runelite.api.GrandExchangeOfferState;

/**
 * The one place offer states are interpreted. The differ, the positions board, and the
 * collect ledger all read the same events; keeping side, phase, and offer identity here
 * stops the copies from drifting apart.
 */
final class OfferStates
{
	private OfferStates()
	{
	}

	/** The trade side of a non-EMPTY offer state. */
	static TradeRecord.Side sideOf(GrandExchangeOfferState state)
	{
		switch (state)
		{
			case BUYING:
			case BOUGHT:
			case CANCELLED_BUY:
				return TradeRecord.Side.BUY;
			case SELLING:
			case SOLD:
			case CANCELLED_SELL:
				return TradeRecord.Side.SELL;
			default:
				throw new IllegalArgumentException("no side for state " + state);
		}
	}

	/** The lifecycle phase of a non-EMPTY offer state. */
	static GePositions.Phase phaseOf(GrandExchangeOfferState state)
	{
		switch (state)
		{
			case BUYING:
			case SELLING:
				return GePositions.Phase.WORKING;
			case BOUGHT:
			case SOLD:
				return GePositions.Phase.COMPLETE;
			case CANCELLED_BUY:
			case CANCELLED_SELL:
				return GePositions.Phase.CANCELLED;
			default:
				throw new IllegalArgumentException("no phase for state " + state);
		}
	}

	/**
	 * Whether {@code next} is the same ongoing offer as a previously seen state. The full
	 * identity must match (item, side, total quantity, set price) and the cumulative
	 * counters must not go backwards. Item and counters alone are a weak identity: a stale
	 * re-fire of a completed offer's state, diffed against a fresh baseline of the same
	 * item, would pass it and read as a giant live fill.
	 */
	static boolean sameOffer(int prevItemId, TradeRecord.Side prevSide, int prevTotalQuantity,
		long prevPrice, int prevQuantitySold, long prevSpent, OfferSnapshot next)
	{
		return prevItemId == next.itemId
			&& prevSide == sideOf(next.state)
			&& prevTotalQuantity == next.totalQuantity
			&& prevPrice == next.price
			&& next.quantitySold >= prevQuantitySold
			&& next.spent >= prevSpent;
	}
}

package com.flipgoblin;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.List;
import lombok.extern.slf4j.Slf4j;

/**
 * Saves each character's unsent fills in its RuneLite profile, so a restart or a plugin
 * update never loses them. Only linked characters are saved: an unlinked queue never sends.
 */
@Slf4j
final class PendingTrades
{
	/** Where the saved queue lives. The plugin backs this with ConfigManager. */
	interface Store
	{
		String get(String profile);

		/** Saves the queue, or removes it when {@code json} is null. */
		void put(String profile, String json);

		boolean linked(String profile);
	}

	static final int MAX_SAVED = 5000;
	private static final Type TYPE = new TypeToken<List<TradeRecord>>() { }.getType();

	private final Store store;
	private final Gson gson;

	PendingTrades(Store store, Gson gson)
	{
		this.store = store;
		this.gson = gson;
	}

	/** Saves the queue under its character. Keeps the newest fills if there are too many. */
	void save(SyncClient sync)
	{
		String owner = sync.owner();
		if (owner == null)
		{
			return;
		}
		List<TradeRecord> queue = sync.pendingSnapshot();
		if (queue.isEmpty() || !store.linked(owner))
		{
			store.put(owner, null);
			return;
		}
		if (queue.size() > MAX_SAVED)
		{
			queue = queue.subList(queue.size() - MAX_SAVED, queue.size());
		}
		store.put(owner, gson.toJson(queue, TYPE));
	}

	/** Adds the character's saved fills back to its queue. */
	void load(SyncClient sync)
	{
		String owner = sync.owner();
		String json = owner == null ? null : store.get(owner);
		if (json == null || json.isEmpty())
		{
			return;
		}
		try
		{
			List<TradeRecord> saved = gson.fromJson(json, TYPE);
			if (saved != null)
			{
				sync.restore(saved);
				log.debug("restored {} unsent fills", saved.size());
			}
		}
		catch (JsonParseException e)
		{
			log.warn("saved unsent fills are unreadable, skipping them", e);
		}
	}
}

package com.flipgoblin;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Read-only market data for the GE info panel, fetched from the keyed /plugin routes.
 * Works stale-while-revalidate: {@code get()} returns the cached row instantly (or null)
 * and kicks off one background refresh when stale, so it is safe to call from overlay
 * render every frame. Only the item id and the token leave the client, never any account
 * data (COMPLIANCE.md documents this).
 */
@Slf4j
public final class PriceClient
{
	/** One item's flip metrics as served by the API. A null means that side never traded or cannot be priced. */
	public static final class ItemPrices
	{
		public final int itemId;
		public final String name;
		public final Long ask;
		public final Long bid;
		public final Long margin;
		public final Double roi;
		public final Long tax;
		public final Long buyLimit;
		public final Long askVolume;
		public final Long bidVolume;
		public final long fetchedAt;

		ItemPrices(int itemId, String name, Long ask, Long bid, Long margin, Double roi, Long tax,
			Long buyLimit, Long askVolume, Long bidVolume, long fetchedAt)
		{
			this.itemId = itemId;
			this.name = name;
			this.ask = ask;
			this.bid = bid;
			this.margin = margin;
			this.roi = roi;
			this.tax = tax;
			this.buyLimit = buyLimit;
			this.askVolume = askVolume;
			this.bidVolume = bidVolume;
			this.fetchedAt = fetchedAt;
		}
	}

	/**
	 * One chart series for the offer panel. The arrays are bucket-aligned, and time holds
	 * each bucket's epoch seconds for the hover readout. A side that did not trade in a
	 * bucket is NaN, and the renderer skips those segments, same as the site's lines.
	 *
	 * A series is either TICKS (per-minute trade points, carrying real-fill flags) or
	 * CANDLES (bucketed closes, carrying per-bucket volumes). Build one with
	 * {@link #ticks} or {@link #candles}.
	 */
	public static final class Series
	{
		public enum Kind
		{
			TICKS, CANDLES
		}

		public final Kind kind;
		public final long[] time;
		public final double[] ask;
		public final double[] bid;
		/** Marks slots where a real fill landed. Tick series only; null for candles. */
		public final boolean[] askReal;
		public final boolean[] bidReal;
		/** Traded volume per slot. Candle series only; null for ticks. NaN means no bucket
		 * data. Volumes are per-bucket sums and are never carried forward like prices. */
		public final double[] askVol;
		public final double[] bidVol;
		public final long fetchedAt;

		static Series ticks(long[] time, double[] ask, double[] bid, boolean[] askReal,
			boolean[] bidReal, long fetchedAt)
		{
			return new Series(Kind.TICKS, time, ask, bid, askReal, bidReal, null, null, fetchedAt);
		}

		static Series candles(long[] time, double[] ask, double[] bid, double[] askVol,
			double[] bidVol, long fetchedAt)
		{
			return new Series(Kind.CANDLES, time, ask, bid, null, null, askVol, bidVol, fetchedAt);
		}

		Series(Kind kind, long[] time, double[] ask, double[] bid, boolean[] askReal,
			boolean[] bidReal, double[] askVol, double[] bidVol, long fetchedAt)
		{
			this.kind = kind;
			this.time = time;
			this.ask = ask;
			this.bid = bid;
			this.askReal = askReal;
			this.bidReal = bidReal;
			this.askVol = askVol;
			this.bidVol = bidVol;
			this.fetchedAt = fetchedAt;
		}
	}

	static final long TTL_MS = 60_000; // matches the endpoint's edge-cache window
	static final long SERIES_TTL_MS = 300_000; // coarse buckets; refetching faster is waste
	/** Tick-graph refresh span in minutes. The overlap covers the Wiki's publication lag. */
	static final int TICK_TAIL_SPAN = 3;
	/** Candle tail refreshes resample onto this many grid slots, enough overlap for the merge. */
	static final int CANDLE_TAIL_SLOTS = 3;
	/** Retry delay while the current bucket is unpainted: near-immediate, but no request storm. */
	static final long BOUNDARY_RETRY_MS = 5_000;

	/** One bucket's span per interval key. Drives the boundary-aware refresh. */
	private static long intervalMs(String interval)
	{
		switch (interval)
		{
			case "5m":
				return 300_000L;
			case "15m":
				return 900_000L;
			case "1h":
				return 3_600_000L;
			case "4h":
				return 14_400_000L;
			case "12h":
				return 43_200_000L;
			case "1d":
				return 86_400_000L;
			default:
				return 60_000L; // the "1m" tick grid
		}
	}

	private final OkHttpClient http;
	// The client's Gson, injected by the plugin. The Plugin Hub forbids fresh Gson instances.
	private final Gson gson;
	private final Map<Integer, ItemPrices> cache = new ConcurrentHashMap<>();
	private final Set<Integer> inflight = ConcurrentHashMap.newKeySet();
	private final Map<String, Series> seriesCache = new ConcurrentHashMap<>();
	private final Set<String> seriesInflight = ConcurrentHashMap.newKeySet();
	/** When each series' newest volume-bearing bucket first reached this client. */
	private final Map<String, VolArrival> volArrivals = new ConcurrentHashMap<>();
	/** Next-fetch instants (epoch ms) learned from the API's cache headers. Keyed by
	 * "d:&lt;itemId&gt;" for the detail fetch, and by the series key otherwise. */
	private final Map<String, Long> nextFetchAt = new ConcurrentHashMap<>();

	/**
	 * How long until the API's edge cache serves fresh data, read from a response's headers
	 * (s-maxage minus age), plus a small margin and a floor. Returns -1 when the headers are
	 * absent, and the caller keeps its fixed TTL.
	 */
	static long cacheCycleDelayMs(String cacheControl, String age)
	{
		if (cacheControl == null || age == null)
		{
			return -1;
		}
		java.util.regex.Matcher m =
			java.util.regex.Pattern.compile("s-maxage=(\\d+)").matcher(cacheControl);
		if (!m.find())
		{
			return -1;
		}
		long ageSec;
		try
		{
			ageSec = Long.parseLong(age.trim());
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
		if (ageSec < 0)
		{
			return -1;
		}
		return Math.max(3_000, (Long.parseLong(m.group(1)) - ageSec) * 1000 + 1_500);
	}

	/** When the next detail fetch is scheduled (epoch ms). Drives the panel's countdown. */
	public long nextDetailFetch(int itemId)
	{
		Long n = nextFetchAt.get("d:" + itemId);
		if (n != null)
		{
			return n;
		}
		ItemPrices p = cache.get(itemId);
		return p == null ? 0 : p.fetchedAt + TTL_MS;
	}

	public PriceClient(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	/**
	 * The freshest known prices for the item, or null until the first fetch lands. Starts
	 * one background refresh when missing or stale. Never blocks, so it is safe from render.
	 */
	public ItemPrices get(String apiBase, String token, int itemId)
	{
		long now = System.currentTimeMillis();
		ItemPrices cached = cache.get(itemId);
		Long learned = nextFetchAt.get("d:" + itemId);
		long nextAt = cached == null ? now
			: learned != null ? learned : cached.fetchedAt + TTL_MS;
		if ((cached == null || now >= nextAt) && inflight.add(itemId))
		{
			fetch(apiBase, token, itemId);
		}
		return cached;
	}

	private void fetch(String apiBase, String token, int itemId)
	{
		// Keyed access: market data flows through the Bearer-token /plugin routes.
		Request request = new Request.Builder()
			.url(apiBase.replaceAll("/+$", "") + "/plugin/items/" + itemId)
			.header("Authorization", "Bearer " + token)
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				inflight.remove(itemId);
				log.debug("price fetch failed for {}: {}", itemId, e.toString());
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response res = response)
				{
					if (res.isSuccessful() && res.body() != null)
					{
						long fetchedAt = System.currentTimeMillis();
						ItemPrices parsed = parse(itemId, res.body().string(), fetchedAt, gson);
						if (parsed != null)
						{
							cache.put(itemId, parsed);
							long d = cacheCycleDelayMs(res.header("cache-control"), res.header("age"));
							nextFetchAt.put("d:" + itemId, fetchedAt + (d > 0 ? d : TTL_MS));
						}
					}
				}
				catch (RuntimeException e)
				{
					log.debug("price parse failed for {}: {}", itemId, e.toString());
				}
				finally
				{
					inflight.remove(itemId);
				}
			}
		});
	}

	/**
	 * The freshest known series for (item, interval), or null until the first fetch lands.
	 * Fine intervals (1m through 1h) refresh on the endpoint's cache cadence, since their
	 * live bucket moves. Coarser ones wait SERIES_TTL_MS. Safe from render.
	 */
	public Series getSeries(String apiBase, String token, int itemId, String interval, int limit)
	{
		long now = System.currentTimeMillis();
		String key = itemId + ":" + interval;
		boolean coarse = "4h".equals(interval) || "12h".equals(interval) || "1d".equals(interval);
		Series cached = seriesCache.get(key);
		// The next fetch fires when the API's cache entry turns over, learned from each
		// response, not on a blind TTL. Coarse intervals keep their slow cadence, and
		// missing headers fall back to the fixed TTLs.
		Long learned = nextFetchAt.get(key);
		long nextAt = cached == null ? now
			: learned != null ? learned : cached.fetchedAt + (coarse ? SERIES_TTL_MS : TTL_MS);
		// Once the wall clock enters a bucket the cached grid does not show yet, refetch
		// near-immediately. The grids are computed client-side, so that fetch slides the
		// window at the boundary even while the server still serves the older body, and the
		// new bucket's values follow as the data lands.
		if (cached != null && cached.time.length > 0)
		{
			long bucketStartSec = now / intervalMs(interval) * (intervalMs(interval) / 1000);
			if (cached.time[cached.time.length - 1] < bucketStartSec)
			{
				nextAt = Math.min(nextAt, cached.fetchedAt + BOUNDARY_RETRY_MS);
			}
		}
		if ((cached == null || now >= nextAt) && seriesInflight.add(key))
		{
			// "1m" is not a candle interval; it reads raw per-side trade points from /ticks.
			// The first load fetches the full window. Every refresh after that fetches only
			// a small tail and merges it client-side, sliding the window and dropping the
			// oldest entries. All parameters are fixed, so every plugin user shares one
			// server cache entry per item.
			boolean tail = cached != null;
			String base = apiBase.replaceAll("/+$", "");
			String url = "1m".equals(interval)
				? base + "/plugin/items/" + itemId + "/ticks?limit=" + (tail ? TICK_TAIL_SPAN + 3 : limit + 15)
					+ "&span=" + (tail ? TICK_TAIL_SPAN : limit + 1)
				: base + "/plugin/items/" + itemId + "/candles?interval=" + interval
					+ "&limit=" + (tail ? 2 : limit);
			Request request = new Request.Builder().url(url)
				.header("Authorization", "Bearer " + token)
				.build();
			http.newCall(request).enqueue(new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					seriesInflight.remove(key);
					log.debug("series fetch failed for {}: {}", key, e.toString());
				}

				@Override
				public void onResponse(Call call, Response response) throws IOException
				{
					try (Response res = response)
					{
						if (res.isSuccessful() && res.body() != null)
						{
							String body = res.body().string();
							long fetchedAt = System.currentTimeMillis();
							boolean coarse = "4h".equals(interval) || "12h".equals(interval)
								|| "1d".equals(interval);
							long cycle = coarse ? SERIES_TTL_MS
								: cacheCycleDelayMs(res.header("cache-control"), res.header("age"));
							Series parsed = "1m".equals(interval)
								? parseTicks(body, tail ? TICK_TAIL_SPAN : limit, fetchedAt, gson)
								: resample(parseSeries(body, fetchedAt, gson),
									(int) (intervalMs(interval) / 1000),
									tail ? CANDLE_TAIL_SLOTS : limit, fetchedAt);
							if (parsed == null)
							{
								return;
							}
							if (!tail)
							{
								seriesCache.put(key, parsed);
								noteVolArrival(key, parsed);
								nextFetchAt.put(key, fetchedAt + (cycle > 0 ? cycle : TTL_MS));
								return;
							}
							// The tick grid is minutes+1 slots (through the live minute).
							int maxLen = "1m".equals(interval) ? limit + 1 : limit;
							Series merged = mergeTail(seriesCache.get(key), parsed, maxLen);
							if (merged != null)
							{
								seriesCache.put(key, merged);
								noteVolArrival(key, merged);
								nextFetchAt.put(key, fetchedAt + (cycle > 0 ? cycle : TTL_MS));
							}
							else
							{
								// The cache is too old to patch (the client was away). Drop
								// it so the next render does a full-depth fetch.
								seriesCache.remove(key);
								nextFetchAt.remove(key);
							}
						}
					}
					catch (RuntimeException e)
					{
						log.debug("series parse failed for {}: {}", key, e.toString());
					}
					finally
					{
						seriesInflight.remove(key);
					}
				}
			});
		}
		return cached;
	}

	/**
	 * Patches a small tail refresh into a full cached series: overwrite the overlapped
	 * buckets with the fresh truth, append new ones, and trim the head to {@code maxLen} so
	 * the window slides at constant size. Real-fill flags merge the same way when both
	 * sides carry them. Returns null when the tail does not overlap the cached range's last
	 * entries (the client was away longer than the tail covers), and the caller then drops
	 * the cache entry and refetches at full depth.
	 */
	static Series mergeTail(Series cached, Series tail, int maxLen)
	{
		if (cached == null || tail.time.length == 0)
		{
			return null;
		}
		int at = -1;
		int searchBack = tail.time.length + 2;
		for (int i = cached.time.length - 1; i >= 0 && i >= cached.time.length - searchBack; i--)
		{
			if (cached.time[i] == tail.time[0])
			{
				at = i;
				break;
			}
		}
		if (at < 0)
		{
			return null;
		}
		int total = at + tail.time.length;
		int drop = Math.max(0, total - maxLen);
		int len = total - drop;
		boolean flags = cached.askReal != null && tail.askReal != null;
		boolean vols = cached.askVol != null && tail.askVol != null;
		long[] time = new long[len];
		double[] ask = new double[len];
		double[] bid = new double[len];
		boolean[] askReal = flags ? new boolean[len] : null;
		boolean[] bidReal = flags ? new boolean[len] : null;
		double[] askVol = vols ? new double[len] : null;
		double[] bidVol = vols ? new double[len] : null;
		for (int i = drop; i < at; i++)
		{
			time[i - drop] = cached.time[i];
			ask[i - drop] = cached.ask[i];
			bid[i - drop] = cached.bid[i];
			if (flags)
			{
				askReal[i - drop] = cached.askReal[i];
				bidReal[i - drop] = cached.bidReal[i];
			}
			if (vols)
			{
				askVol[i - drop] = cached.askVol[i];
				bidVol[i - drop] = cached.bidVol[i];
			}
		}
		for (int i = 0; i < tail.time.length; i++)
		{
			// A NaN tail slot means the small response just did not include that bucket, so
			// keep the cached truth instead of erasing it. A naive merge erodes volumes
			// bucket by bucket. Flags do come from the tail, since it covers its whole span.
			int idx = at - drop + i;
			int ci = at + i;
			boolean hasCached = ci < cached.time.length;
			time[idx] = tail.time[i];
			ask[idx] = Double.isNaN(tail.ask[i]) && hasCached ? cached.ask[ci] : tail.ask[i];
			bid[idx] = Double.isNaN(tail.bid[i]) && hasCached ? cached.bid[ci] : tail.bid[i];
			if (flags)
			{
				askReal[idx] = tail.askReal[i];
				bidReal[idx] = tail.bidReal[i];
			}
			if (vols)
			{
				askVol[idx] = Double.isNaN(tail.askVol[i]) && hasCached ? cached.askVol[ci] : tail.askVol[i];
				bidVol[idx] = Double.isNaN(tail.bidVol[i]) && hasCached ? cached.bidVol[ci] : tail.bidVol[i];
			}
		}
		return new Series(tail.kind, time, ask, bid, askReal, bidReal, askVol, bidVol, tail.fetchedAt);
	}

	// Bulk latest bids for the panel's asset valuation, matching the dashboard's numbers:
	// one slim fetch of [id, ask, bid] triplets, refreshed at most every BULK_TTL_MS. A
	// bank's estimated value does not need the chart's faster cadence.
	static final long BULK_TTL_MS = 5 * 60_000;
	private volatile java.util.Map<Integer, Long> bulkBids;
	private volatile long bulkBidsAt;

	/** The latest id→bid map, or null before the first fetch. Safe from render. */
	java.util.Map<Integer, Long> bulkBids()
	{
		return bulkBids;
	}

	/** Executor only. Refetches past the TTL. Returns true when a fresh map was installed. */
	boolean refreshBulkBids(String apiBase, String token)
	{
		if (bulkBids != null && System.currentTimeMillis() - bulkBidsAt < BULK_TTL_MS)
		{
			return false;
		}
		Request request = new Request.Builder()
			.url(apiBase.replaceAll("/+$", "") + "/plugin/prices")
			.header("Authorization", "Bearer " + token)
			.build();
		try (Response res = http.newCall(request).execute())
		{
			if (!res.isSuccessful() || res.body() == null)
			{
				return false;
			}
			java.util.Map<Integer, Long> parsed = parseBulkBids(res.body().string(), gson);
			if (parsed == null)
			{
				return false;
			}
			bulkBids = parsed;
			bulkBidsAt = System.currentTimeMillis();
			return true;
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("bulk prices fetch failed: {}", e.toString());
			return false;
		}
	}

	/** Parses the /plugin/prices body into an id→bid map. Rows with no bid are dropped. Pure. */
	static java.util.Map<Integer, Long> parseBulkBids(String json, Gson gson)
	{
		try
		{
			JsonObject o = gson.fromJson(json, JsonObject.class);
			if (o == null || !o.has("prices") || !o.get("prices").isJsonArray())
			{
				return null;
			}
			java.util.Map<Integer, Long> out = new java.util.HashMap<>();
			for (JsonElement el : o.getAsJsonArray("prices"))
			{
				if (!el.isJsonArray())
				{
					continue;
				}
				com.google.gson.JsonArray t = el.getAsJsonArray();
				if (t.size() < 3 || t.get(0).isJsonNull() || t.get(2).isJsonNull())
				{
					continue;
				}
				out.put(t.get(0).getAsInt(), t.get(2).getAsLong());
			}
			return out;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/**
	 * Blocking one-shot ticks fetch for refining a recovered fill's time. Executor threads
	 * only, never the client thread. Returns null on any failure, and the refinement then
	 * just keeps the detection time.
	 */
	Series fetchTicksBlocking(String apiBase, String token, int itemId, int minutes)
	{
		Request request = new Request.Builder()
			.url(apiBase.replaceAll("/+$", "") + "/plugin/items/" + itemId
				+ "/ticks?limit=" + Math.min(10_080, minutes + 15) + "&span=" + Math.min(10_080, minutes))
			.header("Authorization", "Bearer " + token)
			.build();
		try (Response res = http.newCall(request).execute())
		{
			if (!res.isSuccessful() || res.body() == null)
			{
				return null;
			}
			return parseTicks(res.body().string(), Math.min(10_080, minutes), System.currentTimeMillis(), gson);
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("refine ticks fetch failed for {}: {}", itemId, e.toString());
			return null;
		}
	}

	/**
	 * The latest minute inside [fromMs, toMs] where the fill's side traded at exactly
	 * {@code price}, or 0 when none did. My buy fill is someone insta-selling (the bid
	 * series), and my sell fill is someone insta-buying (the ask series). Only real trade
	 * minutes count; carried plateaus never match.
	 */
	static long latestPriceMatchMs(Series s, TradeRecord.Side side, long price, long fromMs, long toMs)
	{
		double[] vals = side == TradeRecord.Side.BUY ? s.bid : s.ask;
		boolean[] real = side == TradeRecord.Side.BUY ? s.bidReal : s.askReal;
		if (real == null)
		{
			return 0;
		}
		long best = 0;
		for (int i = 0; i < s.time.length; i++)
		{
			long tMs = s.time[i] * 1000;
			if (real[i] && !Double.isNaN(vals[i]) && (long) vals[i] == price
				&& tMs >= fromMs && tMs <= toMs)
			{
				best = Math.max(best, tMs);
			}
		}
		return best;
	}

	/** When a series' newest published volume first reached this client. */
	public static final class VolArrival
	{
		/** The volume-bearing bucket (epoch seconds). */
		public final long bucketSec;
		/** When it was first observed here (epoch ms). */
		public final long observedMs;

		VolArrival(long bucketSec, long observedMs)
		{
			this.bucketSec = bucketSec;
			this.observedMs = observedMs;
		}
	}

	/**
	 * When the given interval's newest published volume first reached this client, or
	 * null before any volume data. Safe from render.
	 */
	public VolArrival volArrival(int itemId, String interval)
	{
		return volArrivals.get(itemId + ":" + interval);
	}

	/** Records the moment a newer volume-bearing bucket first shows up in the cached series. */
	private void noteVolArrival(String key, Series s)
	{
		if (s.askVol == null)
		{
			return;
		}
		long newest = 0;
		for (int i = s.time.length - 1; i >= 0; i--)
		{
			if (!Double.isNaN(s.askVol[i]) || !Double.isNaN(s.bidVol[i]))
			{
				newest = s.time[i];
				break;
			}
		}
		if (newest == 0)
		{
			return;
		}
		final long bucket = newest;
		volArrivals.compute(key, (k, prev) ->
			prev != null && prev.bucketSec >= bucket ? prev : new VolArrival(bucket, System.currentTimeMillis()));
	}

	/**
	 * Snaps a candle series onto a uniform bucket grid ending at the current bucket. The
	 * endpoint only returns buckets that exist, so a rarely traded item would otherwise
	 * render by event index, the window could not slide when nothing traded, and hover
	 * times would go stale. Rows land in their bucket's slot. Quiet slots carry the
	 * previous values, matching the site's plateau lines, and rows older than the window
	 * seed that carry. Slots before the item's first-ever data stay NaN.
	 */
	static Series resample(Series s, int intervalSec, int points, long nowMs)
	{
		if (s == null)
		{
			return null;
		}
		long start = (nowMs / 1000 / intervalSec - (points - 1)) * intervalSec;
		boolean vols = s.askVol != null;
		long[] time = new long[points];
		double[] ask = new double[points];
		double[] bid = new double[points];
		double[] askVol = vols ? new double[points] : null;
		double[] bidVol = vols ? new double[points] : null;
		for (int i = 0; i < points; i++)
		{
			time[i] = start + (long) i * intervalSec;
			ask[i] = Double.NaN;
			bid[i] = Double.NaN;
			if (vols)
			{
				askVol[i] = Double.NaN;
				bidVol[i] = Double.NaN;
			}
		}
		double curAsk = Double.NaN;
		double curBid = Double.NaN;
		int filled = 0; // slots [0, filled) already hold the carried plateau
		for (int i = 0; i < s.time.length; i++)
		{
			int slot = (int) Math.min(points - 1L, Math.floorDiv(s.time[i] - start, intervalSec));
			while (filled < slot)
			{
				ask[filled] = curAsk;
				bid[filled] = curBid;
				filled++;
			}
			if (!Double.isNaN(s.ask[i]))
			{
				curAsk = s.ask[i];
			}
			if (!Double.isNaN(s.bid[i]))
			{
				curBid = s.bid[i];
			}
			if (slot >= 0)
			{
				ask[slot] = curAsk;
				bid[slot] = curBid;
				if (vols)
				{
					// Volumes are per-bucket sums: placed, never carried. A quiet bucket is zero.
					askVol[slot] = s.askVol[i];
					bidVol[slot] = s.bidVol[i];
				}
				filled = slot + 1;
			}
		}
		while (filled < points)
		{
			ask[filled] = curAsk;
			bid[filled] = curBid;
			filled++;
		}
		return Series.candles(time, ask, bid, askVol, bidVol, s.fetchedAt);
	}

	/**
	 * Parses a ticks response into the last {@code minutes} as a per-minute grid. The wire
	 * rows are one-sided trade points, so each side carries forward between trades: a
	 * plateau is the price between trades, exactly the site's 1m step lines, and the final
	 * carry extends through the current minute. Slots before the item's first-ever known
	 * price stay NaN. Pure.
	 */
	static Series parseTicks(String body, int minutes, long now, Gson gson)
	{
		JsonObject root;
		try
		{
			root = gson.fromJson(body, JsonObject.class);
		}
		catch (RuntimeException e)
		{
			return null;
		}
		if (root == null || !root.has("ticks") || !root.get("ticks").isJsonArray())
		{
			return null;
		}
		com.google.gson.JsonArray ticks = root.getAsJsonArray("ticks");
		long startMin = now / 60_000L - minutes;
		int slots = minutes + 1; // ..through the current (live) minute
		long[] time = new long[slots];
		double[] ask = new double[slots];
		double[] bid = new double[slots];
		boolean[] askReal = new boolean[slots];
		boolean[] bidReal = new boolean[slots];
		for (int i = 0; i < slots; i++)
		{
			time[i] = (startMin + i) * 60;
			ask[i] = Double.NaN;
			bid[i] = Double.NaN;
		}
		double curAsk = Double.NaN;
		double curBid = Double.NaN;
		int filled = 0; // slots [0, filled) already hold the carried plateau
		for (int i = 0; i < ticks.size(); i++)
		{
			JsonObject t = ticks.get(i).getAsJsonObject();
			JsonElement te = t.get("time");
			long ts = te == null || te.isJsonNull() ? 0 : te.getAsLong();
			int slot = (int) Math.min(slots - 1L, ts / 60 - startMin);
			while (filled < slot) // plateau up to this trade's minute
			{
				ask[filled] = curAsk;
				bid[filled] = curBid;
				filled++;
			}
			double a = firstFinite(t, "ask");
			double b = firstFinite(t, "bid");
			if (!Double.isNaN(a))
			{
				curAsk = a;
			}
			if (!Double.isNaN(b))
			{
				curBid = b;
			}
			// A derived pre-tracking fill paints like any plateau but never gets a trade-dot
			// flag. The site follows the same rule: synthetic averages never get dots.
			boolean derived = t.has("src") && !t.get("src").isJsonNull();
			if (slot >= 0)
			{
				ask[slot] = curAsk;
				bid[slot] = curBid;
				askReal[slot] |= !derived && !Double.isNaN(a);
				bidReal[slot] |= !derived && !Double.isNaN(b);
				filled = slot + 1;
			}
		}
		while (filled < slots) // plateau through "now"
		{
			ask[filled] = curAsk;
			bid[filled] = curBid;
			filled++;
		}
		return Series.ticks(time, ask, bid, askReal, bidReal, now);
	}

	/**
	 * Parses a candles response. Per bucket, the side's close falls back to the window
	 * average (synthetic historical buckets carry only averages), else NaN. Pure.
	 */
	static Series parseSeries(String body, long now, Gson gson)
	{
		JsonObject root;
		try
		{
			root = gson.fromJson(body, JsonObject.class);
		}
		catch (RuntimeException e)
		{
			return null;
		}
		if (root == null || !root.has("candles") || !root.get("candles").isJsonArray())
		{
			return null;
		}
		com.google.gson.JsonArray candles = root.getAsJsonArray("candles");
		long[] time = new long[candles.size()];
		double[] ask = new double[candles.size()];
		double[] bid = new double[candles.size()];
		double[] askVol = new double[candles.size()];
		double[] bidVol = new double[candles.size()];
		for (int i = 0; i < candles.size(); i++)
		{
			JsonObject c = candles.get(i).getAsJsonObject();
			JsonElement t = c.get("time");
			time[i] = t == null || t.isJsonNull() ? 0 : t.getAsLong();
			ask[i] = firstFinite(c, "askClose", "avgAsk");
			bid[i] = firstFinite(c, "bidClose", "avgBid");
			askVol[i] = firstFinite(c, "askVolume");
			bidVol[i] = firstFinite(c, "bidVolume");
		}
		return Series.candles(time, ask, bid, askVol, bidVol, now);
	}

	private static double firstFinite(JsonObject o, String... keys)
	{
		for (String key : keys)
		{
			JsonElement e = o.get(key);
			if (e != null && !e.isJsonNull())
			{
				return e.getAsDouble();
			}
		}
		return Double.NaN;
	}

	/** Parses an item detail body. Returns null when the shape does not match. Pure. */
	static ItemPrices parse(int itemId, String body, long now, Gson gson)
	{
		JsonObject root;
		try
		{
			root = gson.fromJson(body, JsonObject.class);
		}
		catch (RuntimeException e)
		{
			return null; // not even JSON-object-shaped; same contract as a missing "item"
		}
		if (root == null || !root.has("item") || !root.get("item").isJsonObject())
		{
			return null;
		}
		JsonObject item = root.getAsJsonObject("item");
		return new ItemPrices(
			itemId,
			str(item, "name"),
			lng(item, "ask"),
			lng(item, "bid"),
			lng(item, "margin"),
			dbl(item, "roi"),
			lng(item, "tax"),
			lng(item, "buyLimit"),
			lng(item, "askVolume"),
			lng(item, "bidVolume"),
			now);
	}

	private static Long lng(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e == null || e.isJsonNull() ? null : e.getAsLong();
	}

	private static Double dbl(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e == null || e.isJsonNull() ? null : e.getAsDouble();
	}

	private static String str(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e == null || e.isJsonNull() ? null : e.getAsString();
	}
}

package com.flipgoblin;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Session P/L. FIFO-matches the session's {@link TradeRecord}s into realized profit and
 * open positions.
 *
 * The matcher and the tax math mirror the website's, so the in-client numbers agree with
 * the dashboard. Pure and single-threaded (client thread). Rebuilt from scratch on every
 * update, since a session holds tens of records at most.
 */
public final class SessionStats
{
	public static final double GE_TAX_RATE = 0.02;
	public static final long GE_TAX_CAP = 5_000_000L;

	/**
	 * Items exempt from GE tax, per the OSRS Wiki's "Grand Exchange" page. Mirrors the
	 * website's list; keep the two identical.
	 */
	private static final java.util.Set<Integer> GE_TAX_EXEMPT_IDS = new java.util.HashSet<>(java.util.Arrays.asList(
		13190, // Old school bond
		3008, 3010, 3012, 3014, // Energy potion (4/3/2/1)
		882, 806, 884, 807, 558, 886, 808, // bronze/iron/steel arrows+darts, mind rune
		365, 2309, 1891, 2140, 2142, 347, 379, 355, 2327, 351, 329, 315, 361, // low-level food
		8011, 8010, 28824, 8009, 3853, 28790, 8008, 2552, 8013, 8007, // teleport items
		1755, 5325, 1785, 2347, 1733, 233, 5341, 8794, 5329, 5343, 1735, 952, 5331 // tools
	));

	/** GE sell tax: 2% rounded down, capped at 5m, and zero for exempt items. */
	public static long geSellTax(long price, int itemId)
	{
		if (price <= 0 || GE_TAX_EXEMPT_IDS.contains(itemId))
		{
			return 0;
		}
		return Math.min((long) Math.floor(price * GE_TAX_RATE), GE_TAX_CAP);
	}

	/** Sale proceeds net of GE tax. */
	public static long netFromSale(long price, int itemId)
	{
		return price - geSellTax(price, itemId);
	}

	/**
	 * The smallest ask that nets at least {@code costBasis} after tax. Exempt items break
	 * even at cost. The small ±2 scan absorbs the tax rounding, where a plain divide can
	 * land 1 gp short.
	 */
	public static long breakevenAsk(long costBasis, int itemId)
	{
		if (costBasis <= 0)
		{
			return 0;
		}
		if (GE_TAX_EXEMPT_IDS.contains(itemId))
		{
			return costBasis;
		}
		long[] candidates = {(long) Math.ceil(costBasis / (1 - GE_TAX_RATE)), costBasis + GE_TAX_CAP};
		long best = Long.MAX_VALUE;
		for (long c : candidates)
		{
			for (long s = c - 2; s <= c + 2; s++)
			{
				if (s >= costBasis && s < best && netFromSale(s, itemId) >= costBasis)
				{
					best = s;
				}
			}
		}
		return best;
	}

	/** One item's session totals: units bought, units sold, and realized P/L. */
	public static final class ItemTotals
	{
		public final long bought;
		public final long sold;
		public final long realized;

		public ItemTotals(long bought, long sold, long realized)
		{
			this.bought = bought;
			this.sold = sold;
			this.realized = realized;
		}
	}

	/** Per-item session position (the panel's row model). */
	public static final class ItemPosition
	{
		public final int itemId;
		public int matchedQty;
		public long realized;
		public int openQty;
		public long openCost;
		public int unmatchedSellQty;
		/** Per-side totals over every fill, matched or not. */
		public long boughtQty;
		public long boughtValue;
		public long boughtMinPrice = Long.MAX_VALUE;
		public long boughtMaxPrice;
		public long soldQty;
		public long soldValue;
		public long soldMinPrice = Long.MAX_VALUE;
		public long soldMaxPrice;
		/** Units written off by Ignore. Later sells never match them. */
		public long ignoredQty;

		ItemPosition(int itemId)
		{
			this.itemId = itemId;
		}
	}

	private static final class BuyLot
	{
		int qty;
		final long price;

		BuyLot(int qty, long price)
		{
			this.qty = qty;
			this.price = price;
		}
	}

	/** FIFO-matches records, which arrive in chronological order. Pure. */
	public static Result match(List<TradeRecord> records)
	{
		return match(records, java.util.Collections.emptyList());
	}

	/**
	 * FIFO-matches records with Ignore events applied in time order. An Ignore writes off the
	 * item's open lots, including a fill at the same instant. Both lists are chronological. Pure.
	 */
	public static Result match(List<TradeRecord> records, List<Dismissal> dismissals)
	{
		Map<Integer, Deque<BuyLot>> lots = new HashMap<>();
		Map<Integer, ItemPosition> positions = new HashMap<>();
		int nextDismissal = 0;

		for (TradeRecord r : records)
		{
			while (nextDismissal < dismissals.size() && dismissals.get(nextDismissal).timestamp < r.timestamp)
			{
				writeOff(dismissals.get(nextDismissal++), lots, positions);
			}
			ItemPosition p = positions.computeIfAbsent(r.itemId, ItemPosition::new);
			if (r.side == TradeRecord.Side.BUY)
			{
				p.boughtQty += r.quantity;
				p.boughtValue += (long) r.quantity * r.price;
				p.boughtMinPrice = Math.min(p.boughtMinPrice, r.price);
				p.boughtMaxPrice = Math.max(p.boughtMaxPrice, r.price);
				lots.computeIfAbsent(r.itemId, k -> new ArrayDeque<>()).addLast(new BuyLot(r.quantity, r.price));
				p.openQty += r.quantity;
				p.openCost += (long) r.quantity * r.price;
				continue;
			}
			p.soldQty += r.quantity;
			p.soldValue += (long) r.quantity * r.price;
			p.soldMinPrice = Math.min(p.soldMinPrice, r.price);
			p.soldMaxPrice = Math.max(p.soldMaxPrice, r.price);
			int remaining = r.quantity;
			long netPerUnit = netFromSale(r.price, r.itemId);
			Deque<BuyLot> q = lots.getOrDefault(r.itemId, new ArrayDeque<>());
			while (remaining > 0 && !q.isEmpty())
			{
				BuyLot lot = q.peekFirst();
				int take = Math.min(remaining, lot.qty);
				p.realized += (long) take * (netPerUnit - lot.price);
				p.matchedQty += take;
				p.openQty -= take;
				p.openCost -= (long) take * lot.price;
				lot.qty -= take;
				remaining -= take;
				if (lot.qty == 0)
				{
					q.pollFirst();
				}
			}
			if (remaining > 0)
			{
				p.unmatchedSellQty += remaining;
			}
		}

		while (nextDismissal < dismissals.size())
		{
			writeOff(dismissals.get(nextDismissal++), lots, positions);
		}

		long total = 0;
		List<ItemPosition> out = new ArrayList<>(positions.values());
		out.sort((a, b) -> Integer.compare(a.itemId, b.itemId));
		for (ItemPosition p : out)
		{
			total += p.realized;
		}
		return new Result(total, out);
	}

	/** Removes the item's open lots from its position. No-op when nothing is open. */
	private static void writeOff(Dismissal d, Map<Integer, Deque<BuyLot>> lots, Map<Integer, ItemPosition> positions)
	{
		Deque<BuyLot> q = lots.get(d.itemId);
		ItemPosition p = positions.get(d.itemId);
		if (q == null || q.isEmpty() || p == null)
		{
			return;
		}
		for (BuyLot lot : q)
		{
			p.openQty -= lot.qty;
			p.openCost -= (long) lot.qty * lot.price;
			p.ignoredQty += lot.qty;
		}
		q.clear();
	}

	/**
	 * Whether the hide settings hide this card. A card with a flip or open units always shows;
	 * otherwise every kind it has (untracked sales, ignored units) must have its setting on.
	 */
	static boolean hiddenCard(ItemPosition p, boolean hideUntracked, boolean hideIgnored)
	{
		if (p.openQty > 0 || p.matchedQty > 0)
		{
			return false;
		}
		boolean untracked = p.unmatchedSellQty > 0;
		boolean ignored = p.ignoredQty > 0;
		if (!untracked && !ignored)
		{
			return false;
		}
		return (!untracked || hideUntracked) && (!ignored || hideIgnored);
	}

	public static final class Result
	{
		public final long totalRealized;
		public final List<ItemPosition> items;

		Result(long totalRealized, List<ItemPosition> items)
		{
			this.totalRealized = totalRealized;
			this.items = items;
		}
	}

	private SessionStats()
	{
	}
}

package com.flipgoblin;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * The opt-in trade sync client. Sends captured fills to the user's Flip Goblin account
 * ({@code POST /plugin/flips} with a bearer token) using RuneLite's shared OkHttp.
 *
 * Fills queue locally. Each flush sends the whole pending batch and only clears it on a
 * 2xx. A failure keeps the queue intact for the next attempt, which is safe because every
 * record carries a clientId UUID and the server dedups on (user, clientId), so re-sending
 * changes nothing. A 4xx means the batch itself is bad (a bug, not a passing failure), so
 * it is logged loudly and dropped rather than wedging the queue forever. Batches cap at
 * the server's limit of 500.
 *
 * COMPLIANCE: this only runs when the user has linked their account, and the token config
 * item carries the full disclosure. The payload is exactly the disclosed fields: item,
 * side, price, quantity, time, GE slot, and the dedup id.
 */
@Slf4j
public final class SyncClient
{
	static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	static final int MAX_BATCH = 500;

	private final OkHttpClient http;
	// The client's Gson, injected by the plugin. The Plugin Hub forbids fresh Gson instances.
	private final Gson gson;
	private final Deque<TradeRecord> pending = new ArrayDeque<>();
	// The crowdsource stream keeps its own queue, so trade sync and price contribution
	// never share a fate. Both flow under the one account link. Events age out client-side
	// (the server rejects stale timestamps anyway), so an offline evening never floods
	// rejects on login.
	private final Deque<TradeRecord> crowdPending = new ArrayDeque<>();
	static final int CROWD_MAX_BATCH = 100;
	// Ignore/Undo events. Order matters (an Undo removes the newest ignore), so they send one
	// at a time. Synchronized: the client thread enqueues while the executor flushes.
	private final Deque<DismissalOp> dismissalOps = new ArrayDeque<>();
	/** The op being sent now. An Undo can no longer cancel it. */
	private DismissalOp dismissalInFlight;

	/** A queued Ignore, or an Undo when {@code restore}. */
	static final class DismissalOp
	{
		final Dismissal dismissal;
		final boolean restore;

		DismissalOp(Dismissal dismissal, boolean restore)
		{
			this.dismissal = dismissal;
			this.restore = restore;
		}
	}
	static final long CROWD_MAX_AGE_MS = 60_000; // server slack is ±90s; stay comfortably inside
	/** The RuneLite profile of the character these fills belong to, or null before the first login. */
	private volatile String owner;

	public SyncClient(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	/** The account link's server-side verdict (the /plugin/me witness route). */
	public enum LinkCheck
	{
		/** Token valid and this character is active: full operation. */
		OK,
		/** Lapse lock: more linked characters than the account's tier allows. Refuse all operation. */
		LOCKED,
		/** The token is unknown or revoked. Syncs would fail with a 401 anyway. */
		INVALID,
		/** Network or server trouble. Keep the previous state rather than flapping on a blip. */
		UNREACHABLE
	}

	/** True when the 401 body is the lapse lock rather than a bad token. Pure. */
	static boolean lockedBody(int code, String body)
	{
		return code == 401 && body != null && body.contains("character locked");
	}

	/**
	 * Asks the server whether this token operates (GET /plugin/me). Blocking, so call it
	 * from the executor. The lock check is the point: a locked character must show as
	 * locked and go dark, not silently queue forever.
	 */
	public LinkCheck checkLink(String apiBase, String token)
	{
		Request request = new Request.Builder()
			.url(apiBase.replaceAll("/+$", "") + "/plugin/me")
			.header("Authorization", "Bearer " + token)
			.build();
		try (Response res = http.newCall(request).execute())
		{
			if (res.isSuccessful())
			{
				return LinkCheck.OK;
			}
			String body = res.body() == null ? "" : res.body().string();
			if (lockedBody(res.code(), body))
			{
				return LinkCheck.LOCKED;
			}
			return res.code() == 401 ? LinkCheck.INVALID : LinkCheck.UNREACHABLE;
		}
		catch (IOException e)
		{
			log.debug("link check unreachable: {}", e.toString());
			return LinkCheck.UNREACHABLE;
		}
	}

	String owner()
	{
		return owner;
	}

	/** Ties this queue to a character. Done once, at that character's login. */
	void claim(String profile)
	{
		owner = profile;
	}

	/** Queues a fill for the next flush. */
	public synchronized void enqueue(TradeRecord record)
	{
		pending.addLast(record);
	}

	public synchronized int pendingCount()
	{
		return pending.size();
	}

	/** A copy of the unsent fills, oldest first. */
	synchronized List<TradeRecord> pendingSnapshot()
	{
		return new ArrayList<>(pending);
	}

	/**
	 * Adds saved fills back to the queue, skipping any already queued. Appended, never put in
	 * front: a flush in flight removes the oldest fills when it succeeds.
	 */
	synchronized void restore(List<TradeRecord> saved)
	{
		java.util.Set<String> queued = new java.util.HashSet<>();
		for (TradeRecord r : pending)
		{
			queued.add(r.clientId);
		}
		for (TradeRecord r : saved)
		{
			if (r != null && queued.add(r.clientId))
			{
				pending.addLast(r);
			}
		}
	}

	/** Queues an Ignore for the next flush. */
	public synchronized void enqueueDismissal(Dismissal d)
	{
		dismissalOps.addLast(new DismissalOp(d, false));
	}

	/** Queues the Undo of {@code d}, or just drops that Ignore if it is still unsent. */
	public synchronized void enqueueRestore(Dismissal d)
	{
		for (java.util.Iterator<DismissalOp> it = dismissalOps.descendingIterator(); it.hasNext(); )
		{
			DismissalOp op = it.next();
			if (!op.restore && op.dismissal == d && op != dismissalInFlight)
			{
				it.remove();
				return;
			}
		}
		dismissalOps.addLast(new DismissalOp(d, true));
	}

	public synchronized int dismissalPendingCount()
	{
		return dismissalOps.size();
	}

	/** Wire body: Ignore = {itemId, ts}, Undo = {itemId}. */
	static JsonObject dismissalBody(DismissalOp op)
	{
		JsonObject o = new JsonObject();
		o.addProperty("itemId", op.dismissal.itemId);
		if (!op.restore)
		{
			o.addProperty("ts", op.dismissal.timestamp);
		}
		return o;
	}

	/**
	 * Sends queued Ignore/Undo events in order. Blocking; call from the executor. A 4xx is
	 * dropped so it never wedges the queue; other failures stop and retry next time.
	 */
	public boolean flushDismissals(String apiBase, String token, String character)
	{
		while (true)
		{
			DismissalOp op;
			synchronized (this)
			{
				op = dismissalOps.peekFirst();
				dismissalInFlight = op;
			}
			if (op == null)
			{
				return true;
			}
			Request.Builder rb = new Request.Builder()
				.url(apiBase.replaceAll("/+$", "") + (op.restore ? "/plugin/flips/restore" : "/plugin/flips/dismiss"))
				.header("Authorization", "Bearer " + token)
				.post(RequestBody.create(JSON, gson.toJson(dismissalBody(op))));
			if (character != null && !character.isEmpty())
			{
				rb.header("X-FlipGoblin-Character", character);
			}
			boolean done;
			try (Response res = http.newCall(rb.build()).execute())
			{
				if (res.isSuccessful())
				{
					done = true;
				}
				else if (UpdateGate.rejectsForGood(res.code()))
				{
					log.warn("{} rejected with HTTP {}, dropping it", op.restore ? "undo-ignore" : "ignore", res.code());
					done = true;
				}
				else
				{
					log.debug("ignore sync failed with HTTP {}, will retry", res.code());
					done = false;
				}
			}
			catch (IOException e)
			{
				log.debug("ignore sync unreachable, will retry: {}", e.toString());
				done = false;
			}
			synchronized (this)
			{
				dismissalInFlight = null;
				if (done && dismissalOps.peekFirst() == op)
				{
					dismissalOps.pollFirst();
				}
			}
			if (!done)
			{
				return false;
			}
		}
	}

	/** Queues a live fill for the crowd stream. Recovered fills never qualify; their times are stale. */
	public void enqueueCrowd(TradeRecord record)
	{
		if (!record.recovered)
		{
			crowdPending.addLast(record);
		}
	}

	public int crowdPendingCount()
	{
		return crowdPending.size();
	}

	/** The exact wire payload for one batch. Pinned by unit tests against the server contract. */
	static JsonObject buildPayload(List<TradeRecord> batch)
	{
		JsonArray arr = new JsonArray();
		for (TradeRecord r : batch)
		{
			JsonObject o = new JsonObject();
			o.addProperty("itemId", r.itemId);
			o.addProperty("side", r.side == TradeRecord.Side.BUY ? "buy" : "sell");
			o.addProperty("price", r.price);
			o.addProperty("qty", r.quantity);
			o.addProperty("ts", r.timestamp);
			if (r.slot >= 0)
			{
				o.addProperty("geSlot", r.slot);
			}
			if (r.recovered)
			{
				// Detected at login rather than observed live: ts is the detection time, and the
				// true fill happened between offlineSince and ts. The dashboard renders these honestly.
				o.addProperty("recovered", true);
				if (r.offlineSince > 0)
				{
					o.addProperty("offlineSince", r.offlineSince);
				}
			}
			o.addProperty("clientId", r.clientId);
			arr.add(o);
		}
		JsonObject body = new JsonObject();
		body.add("flips", arr);
		return body;
	}

	/** Bank and inventory churn is noise. One push a minute is plenty. */
	static final long ASSET_SYNC_WINDOW_MS = 60_000;
	/** Offer-board changes are user actions, and the dashboard should show a placed or
	 * changed order on its next poll, so they fast-path the throttle. 3 seconds still
	 * coalesces the burst of events one placed order fires. */
	static final long OFFER_SYNC_WINDOW_MS = 3_000;

	/** The offers section of an assets body. {@link #assetsJson} emits it last. Pure. */
	static String offersSection(String body)
	{
		if (body == null)
		{
			return "";
		}
		int i = body.indexOf("\"offers\":");
		return i < 0 ? "" : body.substring(i);
	}

	/** The delay before the next assets push. Pure. */
	static long assetDrainDelayMs(boolean offersChanged, long lastPushMs, long now)
	{
		long window = offersChanged ? OFFER_SYNC_WINDOW_MS : ASSET_SYNC_WINDOW_MS;
		long floor = offersChanged ? 1_000 : 2_000; // still let the event burst settle
		return Math.max(floor, lastPushMs + window - now);
	}

	/**
	 * The assets snapshot payload: (item, quantity) pairs with coins riding under the coin
	 * item id, the bank capture time when one exists, and the live GE offers board. The
	 * offers list is always present, and [] means no standing offers. Pure and
	 * unit-testable; it mirrors the server's parser.
	 */
	static String assetsJson(AssetSnapshot snapshot, long bankTs, boolean bankFresh,
		List<GePositions.Position> offers)
	{
		JsonObject body = new JsonObject();
		JsonArray pairs = new JsonArray();
		for (AssetSnapshot.Entry e : snapshot.entries)
		{
			JsonArray pair = new JsonArray();
			pair.add(e.itemId);
			pair.add(e.qty);
			pairs.add(pair);
		}
		body.add("pairs", pairs);
		if (bankTs > 0)
		{
			body.addProperty("bankAt", bankTs);
		}
		// False means the bank part is not trusted this session (neither witnessed nor
		// carried by an ACQUITTED custody chain), so the server must not record a history
		// point from this body.
		body.addProperty("bankFresh", bankFresh);
		JsonArray arr = new JsonArray();
		for (GePositions.Position p : offers)
		{
			JsonObject o = new JsonObject();
			o.addProperty("slot", p.slot);
			o.addProperty("itemId", p.itemId);
			o.addProperty("side", p.side == TradeRecord.Side.BUY ? "buy" : "sell");
			o.addProperty("price", p.price);
			o.addProperty("total", p.totalQuantity);
			o.addProperty("filled", p.quantitySold);
			o.addProperty("phase", p.phase == GePositions.Phase.WORKING ? "working"
				: p.phase == GePositions.Phase.COMPLETE ? "done" : "cancelled");
			arr.add(o);
		}
		body.add("offers", arr);
		return body.toString();
	}

	/**
	 * One-shot assets push (POST /plugin/assets). The server keeps only the latest, so
	 * there is no queue, and a failed push simply waits for the next change. Blocking;
	 * call from the executor.
	 */
	public boolean pushAssets(String apiBase, String token, String character, String bodyJson)
	{
		Request.Builder rb = new Request.Builder()
			.url(apiBase.replaceAll("/+$", "") + "/plugin/assets")
			.header("Authorization", "Bearer " + token)
			.post(RequestBody.create(JSON, bodyJson));
		if (character != null && !character.isEmpty())
		{
			rb.header("X-FlipGoblin-Character", character); // a display label only; the token is the identity
		}
		Request request = rb.build();
		try (Response res = http.newCall(request).execute())
		{
			if (!res.isSuccessful())
			{
				log.debug("assets push failed with HTTP {}", res.code());
			}
			return res.isSuccessful();
		}
		catch (java.io.IOException e)
		{
			log.debug("assets push failed: {}", e.toString());
			return false;
		}
	}

	/** The crowd wire payload: exactly the disclosed fields. The GE slot is deliberately absent. */
	static JsonObject buildCrowdPayload(List<TradeRecord> batch)
	{
		JsonArray arr = new JsonArray();
		for (TradeRecord r : batch)
		{
			JsonObject o = new JsonObject();
			o.addProperty("itemId", r.itemId);
			o.addProperty("side", r.side == TradeRecord.Side.BUY ? "buy" : "sell");
			o.addProperty("price", r.price);
			o.addProperty("quantity", r.quantity);
			o.addProperty("ts", r.timestamp / 1000); // wire is unix SECONDS
			o.addProperty("clientId", r.clientId);
			arr.add(o);
		}
		JsonObject body = new JsonObject();
		body.add("events", arr);
		return body;
	}

	/**
	 * Flushes the crowd queue (POST /crowd/prices). Best effort: stale events are dropped
	 * client-side, and server-side skips are the server's call and never retried. Blocking;
	 * call from the executor.
	 */
	public boolean flushCrowd(String apiBase, String token)
	{
		long cutoff = System.currentTimeMillis() - CROWD_MAX_AGE_MS;
		while (!crowdPending.isEmpty() && crowdPending.peekFirst().timestamp < cutoff)
		{
			crowdPending.pollFirst(); // too old to pass the server's timestamp window; not worth a request
		}
		if (crowdPending.isEmpty())
		{
			return true;
		}
		List<TradeRecord> batch = new ArrayList<>();
		int n = Math.min(crowdPending.size(), CROWD_MAX_BATCH);
		java.util.Iterator<TradeRecord> it = crowdPending.iterator();
		for (int i = 0; i < n; i++)
		{
			batch.add(it.next());
		}
		Request request = new Request.Builder()
			.url(apiBase.replaceAll("/+$", "") + "/crowd/prices")
			.header("Authorization", "Bearer " + token)
			.post(RequestBody.create(JSON, gson.toJson(buildCrowdPayload(batch))))
			.build();
		try (Response res = http.newCall(request).execute())
		{
			if (res.isSuccessful())
			{
				for (int i = 0; i < n; i++)
				{
					crowdPending.pollFirst();
				}
				return crowdPending.isEmpty();
			}
			if (UpdateGate.rejectsForGood(res.code()))
			{
				log.warn("crowd submit rejected with HTTP {}, dropping {} events", res.code(), n);
				for (int i = 0; i < n; i++)
				{
					crowdPending.pollFirst();
				}
			}
			return false;
		}
		catch (IOException e)
		{
			log.debug("crowd submit unreachable, will retry: {}", e.toString());
			return false;
		}
	}

	/**
	 * Sends everything pending, up to MAX_BATCH; callers loop if needed. Blocking, so call
	 * it from the executor. Returns true when the queue drained.
	 */
	public boolean flush(String apiBase, String token, String character)
	{
		List<TradeRecord> batch = new ArrayList<>();
		int n;
		synchronized (this)
		{
			if (pending.isEmpty())
			{
				return true;
			}
			n = Math.min(pending.size(), MAX_BATCH);
			java.util.Iterator<TradeRecord> it = pending.iterator();
			for (int i = 0; i < n; i++)
			{
				batch.add(it.next());
			}
		}

		Request.Builder rb = new Request.Builder()
			.url(apiBase.replaceAll("/+$", "") + "/plugin/flips")
			.header("Authorization", "Bearer " + token)
			.post(RequestBody.create(JSON, gson.toJson(buildPayload(batch))));
		if (character != null && !character.isEmpty())
		{
			rb.header("X-FlipGoblin-Character", character); // a display label only; the token is the identity
		}
		Request request = rb.build();
		try (Response res = http.newCall(request).execute())
		{
			if (res.isSuccessful())
			{
				int left = drop(n);
				log.debug("synced {} fills ({} still pending)", n, left);
				return left == 0;
			}
			if (UpdateGate.rejectsForGood(res.code()))
			{
				// The batch itself is malformed (a bug). Drop it rather than wedge the queue forever.
				log.warn("sync rejected with HTTP {}, dropping {} records", res.code(), n);
				drop(n);
				return false;
			}
			log.debug("sync failed with HTTP {}, will retry ({} pending)", res.code(), pendingCount());
			return false;
		}
		catch (IOException e)
		{
			log.debug("sync unreachable, will retry ({} pending): {}", pendingCount(), e.toString());
			return false;
		}
	}

	/** Removes the n oldest fills (the batch just sent). Returns how many are left. */
	private synchronized int drop(int n)
	{
		for (int i = 0; i < n; i++)
		{
			pending.pollFirst();
		}
		return pending.size();
	}
}

package com.flipgoblin;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Fetches the user's website watchlist and alert rules so they can be shown beside the
 * live price while composing an offer. Refreshed on a slow cadence. The plugin never
 * changes targets; they are managed on the website. Fetches run in the background, and
 * rendering reads the last successfully fetched map.
 */
@Slf4j
public final class TargetsClient
{
	/** One alert rule as the overlay renders it. */
	public static final class TargetAlert
	{
		public final String metric;
		public final String op;
		public final long threshold;
		public final boolean enabled;

		public TargetAlert(String metric, String op, long threshold, boolean enabled)
		{
			this.metric = metric;
			this.op = op;
			this.threshold = threshold;
			this.enabled = enabled;
		}
	}

	public static final class Target
	{
		public final boolean watched;
		public final List<TargetAlert> alerts;

		public Target(boolean watched, List<TargetAlert> alerts)
		{
			this.watched = watched;
			this.alerts = alerts;
		}
	}

	private final OkHttpClient http;
	private volatile Map<Integer, Target> targets = Collections.emptyMap();

	public TargetsClient(OkHttpClient http)
	{
		this.http = http;
	}

	/** The last fetched target for an item, or null. Safe to call from render. */
	public Target get(int itemId)
	{
		return targets.get(itemId);
	}

	/** Formats one rule the way the website words it, e.g. "Buy ≤ 1,000,000" or "ROI ≥ 2.5%". Pure. */
	static String alertLabel(TargetAlert a)
	{
		String metric = "bid".equals(a.metric) ? "Buy"
			: "ask".equals(a.metric) ? "Sell"
			: "margin".equals(a.metric) ? "Margin" : "ROI";
		String op = "gte".equals(a.op) ? "≥" : "≤";
		String value = "roi".equals(a.metric)
			? trimPct(a.threshold / 100.0) + "%"
			: Gp.exact(a.threshold);
		return metric + " " + op + " " + value;
	}

	private static String trimPct(double pct)
	{
		String s = String.format(java.util.Locale.ROOT, "%.2f", pct);
		return s.replaceAll("\\.?0+$", "");
	}

	/** Parses the /plugin/targets response body. Returns null on malformed JSON. Pure. */
	static Map<Integer, Target> parse(Gson gson, String body)
	{
		try
		{
			JsonObject root = gson.fromJson(body, JsonObject.class);
			if (root == null || !root.has("targets") || !root.get("targets").isJsonArray())
			{
				return null;
			}
			Map<Integer, Target> out = new HashMap<>();
			JsonArray arr = root.getAsJsonArray("targets");
			for (JsonElement el : arr)
			{
				JsonObject t = el.getAsJsonObject();
				int itemId = t.get("itemId").getAsInt();
				boolean watched = t.has("watched") && t.get("watched").getAsBoolean();
				List<TargetAlert> alerts = new ArrayList<>();
				if (t.has("alerts") && t.get("alerts").isJsonArray())
				{
					for (JsonElement a : t.getAsJsonArray("alerts"))
					{
						JsonObject ao = a.getAsJsonObject();
						alerts.add(new TargetAlert(
							ao.get("metric").getAsString(),
							ao.get("op").getAsString(),
							ao.get("threshold").getAsLong(),
							!ao.has("enabled") || ao.get("enabled").getAsBoolean()));
					}
				}
				out.put(itemId, new Target(watched, alerts));
			}
			return out;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** Fetches the targets in the background. Keeps the previous map on any failure. */
	public void refresh(Gson gson, String apiBase, String token)
	{
		Request request = new Request.Builder()
			.url(apiBase.replaceAll("/+$", "") + "/plugin/targets")
			.header("Authorization", "Bearer " + token)
			.get()
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("targets refresh failed", e);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					if (!r.isSuccessful() || r.body() == null)
					{
						log.debug("targets refresh HTTP {}", r.code());
						return;
					}
					Map<Integer, Target> parsed = parse(gson, r.body().string());
					if (parsed != null)
					{
						targets = parsed;
					}
				}
			}
		});
	}
}

package com.flipgoblin;

/**
 * One buy or sell fill. {@code spent} keeps the exact gp of this fill alongside the derived
 * per-item {@code price} so accounting never loses coins to rounding.
 */
public final class TradeRecord
{
	public enum Side
	{
		BUY, SELL
	}

	/** Random dedup id. The server upserts on (user, clientId), so a re-sent batch changes nothing. */
	public final String clientId;
	public final int itemId;
	public final Side side;
	public final long price;
	public final int quantity;
	public final long spent;
	public final int slot;
	public final long timestamp;
	/**
	 * True when this fill was found at login rather than seen live. It happened while we were
	 * not watching, so {@code timestamp} is when we detected it, not when it filled. The game
	 * exposes no fill timestamps, so the true time is only known to lie somewhere between
	 * {@code offlineSince} and {@code timestamp}.
	 */
	public final boolean recovered;
	/** Earliest possible true time of a recovered fill (epoch ms). 0 means unknown or not recovered. */
	public final long offlineSince;

	/** A live fill, observed as it happened. */
	public TradeRecord(int itemId, Side side, long price, int quantity, long spent, int slot, long timestamp)
	{
		this(itemId, side, price, quantity, spent, slot, timestamp, false, 0);
	}

	public TradeRecord(int itemId, Side side, long price, int quantity, long spent, int slot, long timestamp,
		boolean recovered, long offlineSince)
	{
		this(itemId, side, price, quantity, spent, slot, timestamp, recovered, offlineSince,
			java.util.UUID.randomUUID().toString());
	}

	/**
	 * Full form including {@code clientId}. Used to rewrite an existing record, for example
	 * to refine a recovered fill's time, without minting a new dedup id, so the server never
	 * sees a duplicate.
	 */
	public TradeRecord(int itemId, Side side, long price, int quantity, long spent, int slot, long timestamp,
		boolean recovered, long offlineSince, String clientId)
	{
		this.itemId = itemId;
		this.side = side;
		this.price = price;
		this.quantity = quantity;
		this.spent = spent;
		this.slot = slot;
		this.timestamp = timestamp;
		this.recovered = recovered;
		this.offlineSince = offlineSince;
		this.clientId = clientId;
	}

	@Override
	public String toString()
	{
		return String.format("TradeRecord{item=%d side=%s price=%d qty=%d spent=%d slot=%d ts=%d%s}",
			itemId, side, price, quantity, spent, slot, timestamp,
			recovered ? " recovered(since=" + offlineSince + ")" : "");
	}
}

package com.flipgoblin;

import java.io.IOException;
import okhttp3.Interceptor;
import okhttp3.MediaType;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Sends the plugin version with every request to our API, and pauses the API once the server
 * answers 426 (this version is too old). After that, every API call gets a local 426 without
 * touching the network until RuneLite restarts and installs the update. Queued trades are kept,
 * because the sync code never drops a batch on 426.
 */
final class UpdateGate implements Interceptor
{
	static final String HEADER = "X-FlipGoblin-Version";
	static final int UPGRADE_REQUIRED = 426;

	private final String version;
	private final String apiBase;
	private final Runnable onRequired;
	private volatile boolean required;

	UpdateGate(String version, String apiBase, Runnable onRequired)
	{
		this.version = version;
		this.apiBase = apiBase.replaceAll("/+$", "");
		this.onRequired = onRequired;
	}

	/** True once the server has said this version needs an update. */
	boolean required()
	{
		return required;
	}

	/** True for an answer that means the request itself is bad, so retrying it cannot help. */
	static boolean rejectsForGood(int code)
	{
		return code >= 400 && code < 500 && code != 401 && code != UPGRADE_REQUIRED && code != 429;
	}

	@Override
	public Response intercept(Chain chain) throws IOException
	{
		Request request = chain.request();
		if (!request.url().toString().startsWith(apiBase))
		{
			return chain.proceed(request);
		}
		if (required)
		{
			return upgradeRequired(request);
		}
		Response response = chain.proceed(request.newBuilder().header(HEADER, version).build());
		if (response.code() == UPGRADE_REQUIRED && !required)
		{
			required = true;
			onRequired.run();
		}
		return response;
	}

	private static Response upgradeRequired(Request request)
	{
		return new Response.Builder()
			.request(request)
			.protocol(Protocol.HTTP_1_1)
			.code(UPGRADE_REQUIRED)
			.message("Upgrade Required")
			.body(ResponseBody.create(MediaType.parse("application/json"), "{\"ok\":false,\"error\":\"update required\"}"))
			.build();
	}
}

package com.flipgoblin;

import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

/**
 * Widget text scan: {@link #findText} walks a loaded group's whole tree for a text needle:
 * the welcome-screen custody parser's lookup (never a hardcoded deep widget path). Client
 * thread only.
 */
final class WidgetCatalog
{

	/** Groups have no child-count API; probing this many root children covers every interface. */
	private static final int MAX_CHILDREN = 512;

	private WidgetCatalog()
	{
	}


	/**
	 * The FULL text of the first widget in the group whose text contains the needle
	 * (case-insensitive), or null. Feeds the custody parser (needle "last logged in"). Scanning
	 * the group survives client layout changes that would break a hardcoded deep widget path.
	 */
	static String findText(Client client, int groupId, String needle)
	{
		for (int child = 0; child < MAX_CHILDREN; child++)
		{
			Widget w = client.getWidget(groupId, child);
			if (w != null)
			{
				String found = subtreeFindText(w, needle);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private static String subtreeFindText(Widget w, String needle)
	{
		String text = w.getText();
		if (text != null && text.toLowerCase().contains(needle))
		{
			return text;
		}
		String found = anyFindText(w.getStaticChildren(), needle);
		if (found == null)
		{
			found = anyFindText(w.getDynamicChildren(), needle);
		}
		return found != null ? found : anyFindText(w.getNestedChildren(), needle);
	}

	private static String anyFindText(Widget[] children, String needle)
	{
		if (children == null)
		{
			return null;
		}
		for (Widget c : children)
		{
			if (c != null)
			{
				String found = subtreeFindText(c, needle);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

}

package com.flipgoblin;

import static org.junit.Assert.assertEquals;

import com.google.gson.Gson;
import org.junit.Test;

/** Pins the B1 asset-snapshot merge semantics + the Gson persistence round-trip. */
public class AssetSnapshotTest
{
	@Test
	public void mergesContainers_sumsDuplicates_dropsEmptyAndPlaceholders()
	{
		int[][] bank = {
			{995, 1_000_000}, // coins
			{4151, 3},
			{560, 0}, // bank placeholder (qty 0): dropped
			{-1, 5}, // empty slot sentinel: dropped
		};
		int[][] inventory = {
			{995, 25_000}, // more coins in the backpack; sums with the bank stack
			{4151, 1},
			{2, 100},
		};
		AssetSnapshot snap = AssetSnapshot.of(1720000000000L, bank, inventory);

		assertEquals(3, snap.totalStacks()); // 995, 4151, 2
		assertEquals(1_025_000, snap.coins());
		assertEquals(1720000000000L, snap.timestamp);
		long whips = snap.entries.stream().filter(e -> e.itemId == 4151).findFirst().get().qty;
		assertEquals(4, whips);
	}

	@Test
	public void nullContainerIsSkipped_notFatal()
	{
		AssetSnapshot snap = AssetSnapshot.of(1L, new int[][]{{995, 10}}, null);
		assertEquals(1, snap.totalStacks());
		assertEquals(10, snap.coins());
	}

	@Test
	public void noCoinsMeansZero()
	{
		AssetSnapshot snap = AssetSnapshot.of(1L, new int[][]{{4151, 1}});
		assertEquals(0, snap.coins());
	}

	@Test
	public void extraCoins_mergeWithContainerCoins_beyondIntRange()
	{
		// GE escrow can exceed int max-cash; the long path must survive composition.
		long escrow = 3_000_000_000L;
		AssetSnapshot snap = AssetSnapshot.of(1L, escrow, new int[][]{{995, 500}, {4151, 1}});
		assertEquals(escrow + 500, snap.coins());
		assertEquals(2, snap.totalStacks());
	}

	@Test
	public void pairsRoundTrip_feedsRecomposition()
	{
		AssetSnapshot bank = AssetSnapshot.of(1L, new int[][]{{995, 1000}, {4151, 2}});
		// Frozen bank pairs + live inventory compose without duplication (distinct containers).
		AssetSnapshot composite = AssetSnapshot.of(2L, 0, bank.pairs(), new int[][]{{560, 50}});
		assertEquals(3, composite.totalStacks());
		assertEquals(1000, composite.coins());
	}

	@Test
	public void gsonRoundTrip_forProfilePersistence()
	{
		AssetSnapshot before = AssetSnapshot.of(1720000000000L,
			new int[][]{{995, 5_000}, {4151, 2}});
		Gson gson = new Gson();
		AssetSnapshot after = gson.fromJson(gson.toJson(before), AssetSnapshot.class);
		assertEquals(before.timestamp, after.timestamp);
		assertEquals(before.totalStacks(), after.totalStacks());
		assertEquals(before.coins(), after.coins());
		assertEquals(2, after.entries.stream().filter(e -> e.itemId == 4151).findFirst().get().qty);
	}
	@Test
	public void estimateValue_dashboardParity()
	{
		// coins face value + whip at bid net of 2% tax + exempt lobster at full bid; ruby unpriced.
		AssetSnapshot snap = AssetSnapshot.of(0L, 1_000L,
			new int[][]{{4151, 2}, {379, 10}, {1603, 5}});
		java.util.Map<Integer, Long> bids = new java.util.HashMap<>();
		bids.put(4151, 150L); // tax floor(3.0) => net 147/unit
		bids.put(379, 250L); // exempt => 250/unit
		long[] est = snap.estimateValue(bids);
		assertEquals(1_000 + 2 * 147 + 10 * 250, est[0]);
		assertEquals(1, est[1]); // the ruby stack has no live bid
		// No price map at all: coins still count, every non-coin stack is unpriced.
		long[] blind = snap.estimateValue(null);
		assertEquals(1_000, blind[0]);
		assertEquals(3, blind[1]);
	}

	@Test
	public void platinumTokens_countAsCashAtFaceValue()
	{
		// The GE pays out and takes platinum since the Beyond Max Cash update (2026-09-30).
		AssetSnapshot snap = AssetSnapshot.of(0L, new int[][]{{995, 500}, {13204, 3_000_000}, {1603, 1}});
		assertEquals(500 + 3_000_000_000L, snap.coins());
		long[] est = snap.estimateValue(new java.util.HashMap<>());
		assertEquals(500 + 3_000_000_000L, est[0]);
		assertEquals(1, est[1]); // only the ruby is unpriced; platinum is never "unpriced"
	}
}

package com.flipgoblin;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Pins the b51 offer-board fast-path (dashboard-lag report 2026-07-12). */
public class AssetSyncThrottleTest
{
	@Test
	public void offersSectionExtractsTheTailAndHandlesNull()
	{
		String body = "{\"pairs\":[[995,100]],\"bankAt\":5,\"offers\":[{\"slot\":0}]}";
		assertEquals("\"offers\":[{\"slot\":0}]}", SyncClient.offersSection(body));
		assertEquals("", SyncClient.offersSection(null));
		assertEquals("", SyncClient.offersSection("{\"pairs\":[]}"));
	}

	@Test
	public void offerChangesFastPathThePush()
	{
		long now = 1_000_000L;
		// offers changed, last push long ago → the 1s settle floor
		assertEquals(1_000, SyncClient.assetDrainDelayMs(true, now - 100_000, now));
		// offers changed, pushed 1s ago → the remaining 2s of the 3s window
		assertEquals(2_000, SyncClient.assetDrainDelayMs(true, now - 1_000, now));
		// bank-only change, pushed 10s ago → waits out the minute window
		assertEquals(50_000, SyncClient.assetDrainDelayMs(false, now - 10_000, now));
		// bank-only change, never pushed → the 2s settle floor
		assertTrue(SyncClient.assetDrainDelayMs(false, 0, now) == 2_000);
	}
}

package com.flipgoblin;

import static org.junit.Assert.assertEquals;

import org.junit.Test;

public class BankDrawTest
{
	@Test
	public void shortfall_isTheCostTheInventoryDidNotPay()
	{
		assertEquals(20_000, BankDraw.shortfall(20_000, 0, 0)); // all from the bank
		assertEquals(0, BankDraw.shortfall(20_000, 50_000, 30_000)); // all from the inventory
		assertEquals(5_000, BankDraw.shortfall(20_000, 15_000, 0)); // split
		assertEquals(0, BankDraw.shortfall(20_000, 50_000, 10_000)); // inventory dropped more: never negative
		assertEquals(20_000, BankDraw.shortfall(20_000, 0, 7)); // inventory grew: bank paid all
	}

	@Test
	public void userCase_bankPaidBuy_noLongerCountsTwice()
	{
		// The b91 field report (2026-10-06): ~50k net worth, all coins banked, a ~20k buy paid
		// from the bank showed ~70k until the bank was reopened.
		AssetSnapshot photo = AssetSnapshot.of(1L, new int[][]{{995, 45_000}, {4151, 1}});
		long escrow = 20_000;
		AssetSnapshot fixed = BankDraw.withdraw(photo, BankDraw.shortfall(escrow, 0, 0));
		assertEquals(25_000, fixed.coins());
		assertEquals(45_000, fixed.coins() + escrow); // cash total unchanged by placing the buy
		assertEquals(1L, fixed.timestamp); // still the time the bank was last seen
		assertEquals(1, fixed.entries.stream().filter(e -> e.itemId == 4151).findFirst().get().qty);
	}

	@Test
	public void withdraw_usesPlatinumWhenCoinsRunOut_andKeepsTheChange()
	{
		AssetSnapshot photo = AssetSnapshot.of(1L, new int[][]{{995, 300}, {13204, 10}});
		AssetSnapshot after = BankDraw.withdraw(photo, 2_500);
		// 300 coins, then 3 tokens (3,000 gp) for the other 2,200: 800 change, 7 tokens left.
		assertEquals(10_300 - 2_500, after.coins());
		assertEquals(7, after.entries.stream().filter(e -> e.itemId == 13204).findFirst().get().qty);
	}

	@Test
	public void withdraw_neverGoesBelowZero()
	{
		AssetSnapshot photo = AssetSnapshot.of(1L, new int[][]{{995, 100}, {4151, 1}});
		AssetSnapshot after = BankDraw.withdraw(photo, 1_000_000);
		assertEquals(0, after.coins());
		assertEquals(1, after.totalStacks()); // only the whip is left
	}
}

package com.flipgoblin;

import static org.junit.Assert.assertEquals;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * Pins the all-characters aggregation (panel scope, 2026-07-23): per-character FIFO isolation,
 * the read-time 7d horizon, and bank-photo valuation against the shared bulk-bid map.
 */
public class CharacterLedgerTest
{
	private static final int WHIP = 4151;
	private static final long NOW = 1_760_000_000_000L;
	private static final long HORIZON = 7L * 24 * 3_600_000;

	private static TradeRecord rec(TradeRecord.Side side, long price, int qty, long ts)
	{
		return new TradeRecord(WHIP, side, price, qty, price * qty, 0, ts);
	}

	private static CharacterLedger.Character chr(String name, java.util.List<TradeRecord> recs,
		AssetSnapshot bank)
	{
		return new CharacterLedger.Character(name, recs, bank);
	}

	@Test
	public void realizedIsMatchedPerCharacter_neverMergedFifo()
	{
		// A bought, B sold: merged into one FIFO this would "realize" profit; per character the
		// buy stays open and the sell is untracked, so the honest aggregate realizes ZERO.
		CharacterLedger.Totals t = CharacterLedger.aggregate(Arrays.asList(
			chr("A", Collections.singletonList(rec(TradeRecord.Side.BUY, 100, 1, NOW - 1000)), null),
			chr("B", Collections.singletonList(rec(TradeRecord.Side.SELL, 200, 1, NOW - 500)), null)),
			null, NOW, HORIZON);
		assertEquals(0, t.realized7d);
		assertEquals(2, t.characters);
		assertEquals("A · B", t.names);
	}

	@Test
	public void realizedSumsCompletedFlipsAcrossCharacters()
	{
		// Each character flips independently: buy 100 → sell 200 nets 200 - tax(4) - 100 = 96.
		java.util.List<TradeRecord> flip = Arrays.asList(
			rec(TradeRecord.Side.BUY, 100, 1, NOW - 2000),
			rec(TradeRecord.Side.SELL, 200, 1, NOW - 1000));
		CharacterLedger.Totals t = CharacterLedger.aggregate(
			Arrays.asList(chr("A", flip, null), chr("B", flip, null)), null, NOW, HORIZON);
		assertEquals(192, t.realized7d);
	}

	@Test
	public void horizonReappliesAtReadTime()
	{
		// The stored history was trimmed at the character's LAST persist; a fill now older than
		// 7d must fall out of the sum even though it survived in storage.
		CharacterLedger.Totals t = CharacterLedger.aggregate(Collections.singletonList(
			chr("A", Arrays.asList(
				rec(TradeRecord.Side.BUY, 100, 1, NOW - HORIZON - 2000),
				rec(TradeRecord.Side.SELL, 200, 1, NOW - HORIZON - 1000)),
				null)),
			null, NOW, HORIZON);
		assertEquals(0, t.realized7d);
	}

	@Test
	public void bankPhotosValueAtBidsNetOfTax_andSum()
	{
		Map<Integer, Long> bids = new HashMap<>();
		bids.put(WHIP, 200L);
		AssetSnapshot bankA = AssetSnapshot.of(NOW, new int[][]{{WHIP, 2}, {995, 50}});
		AssetSnapshot bankB = AssetSnapshot.of(NOW, new int[][]{{WHIP, 1}, {9999, 3}});
		CharacterLedger.Totals t = CharacterLedger.aggregate(
			Arrays.asList(chr("A", null, bankA), chr("B", null, bankB)), bids, NOW, HORIZON);
		// A: 2 × net(200)=196 → 392, +50 coins = 442; B: 196, id 9999 unpriced.
		assertEquals(442 + 196, t.bankEst);
		assertEquals(1, t.unpriced);
	}

	@Test
	public void noBidMapMeansNoValuation()
	{
		AssetSnapshot bank = AssetSnapshot.of(NOW, new int[][]{{WHIP, 2}});
		CharacterLedger.Totals t = CharacterLedger.aggregate(
			Collections.singletonList(chr("A", null, bank)), null, NOW, HORIZON);
		assertEquals(-1, t.bankEst);
		assertEquals(0, t.unpriced);
	}
}

