public class CollectLedgerTest
{
	private static final int SLOT = 2;

	private static OfferSnapshot snap(int item, GrandExchangeOfferState st, int total, int sold, long spent,
		long price)
	{
		return new OfferSnapshot(item, st, total, sold, spent, price);
	}

	@Test
	public void buyFills_accumulateItems_andEmptyClears()
	{
		CollectLedger l = new CollectLedger();
		l.onOffer(SLOT, snap(563, GrandExchangeOfferState.BUYING, 6000, 0, 0, 124), 1L);
		l.onOffer(SLOT, snap(563, GrandExchangeOfferState.BUYING, 6000, 400, 49_600, 124), 2L);
		l.onOffer(SLOT, snap(563, GrandExchangeOfferState.BOUGHT, 6000, 6000, 744_000, 124), 3L);
		assertArrayEquals(new int[][]{{563, 6000}}, l.itemPairs());
		assertEquals(0, l.coins());
		// Collected → slot EMPTY → the entry dies.
		assertTrue(l.onOffer(SLOT, snap(0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0), 4L));
		assertEquals(0, l.itemPairs().length);
	}

	@Test
	public void sellFills_accumulateCoins_NET_ofTax_neverGross()
	{
		// The verified id=4 case shape: 1,800 @ 1,189: tax 23/unit, net 1,166/unit. Gross would
		// be 2,140,200; the ledger must hold 2,098,800.
		CollectLedger l = new CollectLedger();
		l.onOffer(SLOT, snap(4151, GrandExchangeOfferState.SELLING, 1800, 0, 0, 1189), 1L);
		l.onOffer(SLOT, snap(4151, GrandExchangeOfferState.SOLD, 1800, 1800, 2_140_200, 1189), 2L);
		assertEquals(1800L * 1166, l.coins());
		assertEquals(0, l.itemPairs().length);
	}

	@Test
	public void cancelledBuy_addsUnfilledEscrowRefund_cancelledSell_returnsStock()
	{
		CollectLedger l = new CollectLedger();
		// Buy 100 @ 50, 30 filled, then cancelled: 30 items + 70×50 refund coins in the box.
		l.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 100, 0, 0, 50), 1L);
		l.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 100, 30, 1500, 50), 2L);
		l.onOffer(SLOT, snap(100, GrandExchangeOfferState.CANCELLED_BUY, 100, 30, 1500, 50), 3L);
		assertArrayEquals(new int[][]{{100, 30}}, l.itemPairs());
		assertEquals(70L * 50, l.coins());

		// Sell 100 lobsters (379, tax-exempt) @ 200, 40 sold, cancelled: 40×200 coins + 60 stock.
		CollectLedger l2 = new CollectLedger();
		l2.onOffer(SLOT, snap(379, GrandExchangeOfferState.SELLING, 100, 0, 0, 200), 1L);
		l2.onOffer(SLOT, snap(379, GrandExchangeOfferState.SELLING, 100, 40, 8000, 200), 2L);
		l2.onOffer(SLOT, snap(379, GrandExchangeOfferState.CANCELLED_SELL, 100, 40, 8000, 200), 3L);
		assertEquals(40L * 200, l2.coins()); // exempt, no tax
		assertArrayEquals(new int[][]{{379, 60}}, l2.itemPairs());
	}

	@Test
	public void firstSighting_countsNothing_slotReuseWithoutEmpty_assumesCollected()
	{
		CollectLedger l = new CollectLedger();
		// Login replay of a completed offer: baseline only; offline progress arrives via
		// applyFill under acquittal, never through the raw replay (never-inflate).
		assertFalse(l.onOffer(SLOT, snap(563, GrandExchangeOfferState.BOUGHT, 6000, 6000, 744_000, 124), 1L));
		assertEquals(0, l.itemPairs().length);
		// Live fills after the baseline still count.
		CollectLedger l2 = new CollectLedger();
		l2.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 0, 0, 50), 1L);
		l2.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 4, 200, 50), 2L);
		assertArrayEquals(new int[][]{{100, 4}}, l2.itemPairs());
		// A different offer appears without a witnessed EMPTY → the old contents were collected
		// while we blinked: entry dies, new offer starts clean.
		assertTrue(l2.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 20, 0, 0, 60), 3L));
		assertEquals(0, l2.itemPairs().length);
	}

	@Test
	public void widgetResync_isAuthoritative_bothDirections()
	{
		CollectLedger l = new CollectLedger();
		l.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 0, 0, 50), 1L);
		l.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 10, 500, 50), 2L);
		assertArrayEquals(new int[][]{{100, 10}}, l.itemPairs());
		// Box shows only 3 left (mobile collected 7): resync heals DOWN.
		assertTrue(l.resyncAll(java.util.Arrays.asList(new long[]{100, 3, 0})));
		assertArrayEquals(new int[][]{{100, 3}}, l.itemPairs());
		// Box shows pre-ledger stock we never witnessed filling: resync heals UP (the b72 ruby
		// bootstrap case, authoritative-while-visible).
		assertTrue(l.resyncAll(java.util.Arrays.asList(new long[]{100, 3, 0}, new long[]{1603, 4078, 250})));
		assertEquals(250, l.coins());
		boolean rubies = false;
		for (int[] p : l.itemPairs())
		{
			rubies |= p[0] == 1603 && p[1] == 4078;
		}
		assertTrue(rubies);
		// Identical state → no change (no persist churn per tick).
		assertFalse(l.resyncAll(java.util.Arrays.asList(new long[]{100, 3, 0}, new long[]{1603, 4078, 250})));
		// Emptied box → the whole ledger dies with it.
		assertTrue(l.resyncAll(java.util.Collections.emptyList()));
		assertEquals(0, l.itemPairs().length);
		assertEquals(0, l.coins());
	}

	@Test
	public void zeroAll_empties_and_persistRoundTrip_restoresUnderAcquittal()
	{
		CollectLedger l = new CollectLedger();
		l.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 0, 0, 50), 1L);
		l.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 10, 500, 50), 2L);
		Map<Integer, CollectLedger.Entry> saved = l.snapshotEntries();
		assertTrue(l.zeroAll());
		assertFalse(l.zeroAll()); // already empty, no churn
		assertEquals(0, l.itemPairs().length);
		// The acquitted-login path: persisted entries seed a fresh ledger and count again.
		CollectLedger next = new CollectLedger();
		next.seedEntries(saved);
		assertArrayEquals(new int[][]{{100, 10}}, next.itemPairs());
		// MERGE semantics: a slot the live session already touched keeps its live entry; the
		// seed must never eat a pre-judge witnessed mutation.
		CollectLedger merged = new CollectLedger();
		merged.applyFill(new TradeRecord(200, TradeRecord.Side.BUY, 10, 5, 50, SLOT, 1L, true, 1L));
		merged.seedEntries(saved); // saved holds SLOT too (item 100); live entry wins
		assertArrayEquals(new int[][]{{200, 5}}, merged.itemPairs());
		// A seeded entry whose slot replays a DIFFERENT item = missed EMPTY → dropped low.
		assertTrue(next.onOffer(SLOT, snap(200, GrandExchangeOfferState.BUYING, 5, 0, 0, 10), 3L)
			|| next.itemPairs().length == 0);
		assertEquals(0, next.itemPairs().length);
	}

	@Test
	public void applyFill_recoveredRecords_countUnderAcquittal_netOfTax()
	{
		CollectLedger l = new CollectLedger();
		// Overnight 20k-bar sell @ 93 (the −1.72m dip case): net 92/unit (tax floor(1.86)=1).
		l.applyFill(new TradeRecord(2357, TradeRecord.Side.SELL, 93, 20_000, 1_860_000, SLOT, 5L, true, 1L));
		assertEquals(20_000L * SessionStats.netFromSale(93, 2357), l.coins());
		// A recovered buy counts as stock.
		l.applyFill(new TradeRecord(563, TradeRecord.Side.BUY, 124, 7000, 868_000, 3, 6L, true, 1L));
		boolean found = false;
		for (int[] p : l.itemPairs())
		{
			found |= p[0] == 563 && p[1] == 7000;
		}
		assertTrue(found);
	}

	@Test
	public void arrivals_positiveDeltasOnly_coinsRideAs995()
	{
		int[][] before = {{995, 1000}, {563, 20}, {4151, 1}};
		int[][] after = {{995, 5000}, {563, 6020}, {2357, 30}}; // whip left (sold), bars arrived
		Map<Integer, Integer> d = CollectLedger.arrivals(before, after);
		assertEquals(Integer.valueOf(4000), d.get(995));
		assertEquals(Integer.valueOf(6000), d.get(563));
		assertEquals(Integer.valueOf(30), d.get(2357));
		assertFalse(d.containsKey(4151)); // losses are not arrivals
		assertTrue(CollectLedger.arrivals(after, after).isEmpty());
	}

	@Test
	public void applyCollectDelta_attributesExactly_slotOrder_multiSlotSameItem()
	{
		CollectLedger l = new CollectLedger();
		// Slot 1 and slot 5 both hold uncollected law runes; slot 3 holds net sell coins.
		l.applyFill(new TradeRecord(563, TradeRecord.Side.BUY, 124, 4000, 496_000, 1, 1L, true, 1L));
		l.applyFill(new TradeRecord(563, TradeRecord.Side.BUY, 124, 2000, 248_000, 5, 2L, true, 1L));
		l.applyFill(new TradeRecord(379, TradeRecord.Side.SELL, 200, 100, 20_000, 3, 3L, true, 1L));
		// Collect delivered 5,000 runes (partial fit) + all the coins.
		Map<Integer, Integer> arrived = new HashMap<>();
		arrived.put(563, 5000);
		assertTrue(l.applyCollectDelta(arrived, 20_000)); // lobster (379) is exempt: net = gross
		// Slot order: slot 1 fully consumed (4000), slot 5 keeps the 1,000 remainder.
		assertArrayEquals(new int[][]{{563, 1000}}, l.itemPairs());
		assertEquals(0, l.coins());
	}

	@Test
	public void applyCollectDelta_clampsAtZero_ignoresUnmatchedArrivals()
	{
		CollectLedger l = new CollectLedger();
		l.applyFill(new TradeRecord(563, TradeRecord.Side.BUY, 124, 100, 12_400, 0, 1L, true, 1L));
		Map<Integer, Integer> arrived = new HashMap<>();
		arrived.put(563, 500); // more than the ledger holds (e.g. an unrelated same-item source)
		arrived.put(1613, 40); // not ours at all
		assertTrue(l.applyCollectDelta(arrived, 999_999)); // stray coins with no coin entries
		assertEquals(0, l.itemPairs().length); // consumed to zero, never negative
		assertEquals(0, l.coins());
		// Nothing armed, nothing held → a delta application is a no-op.
		assertFalse(l.applyCollectDelta(new HashMap<>(), 0));
	}

	@Test
	public void resyncViewed_witnessesOneSlot_andSweepsSameItemDuplicates()
	{
		CollectLedger l = new CollectLedger();
		// A whole-box resync stored the rubies under detection-order key 0…
		l.resyncAll(java.util.Arrays.asList(new long[]{1603, 4078, 0}));
		// …then the offer-detail view witnesses the SAME offer under its real slot key 1.
		assertTrue(l.resyncViewed(1, 1603, 4078, 0));
		// One entry, never two: a glance can never double-count.
		assertArrayEquals(new int[][]{{1603, 4078}}, l.itemPairs());
		// Re-witnessing the identical state is a no-op (no persist churn per tick).
		assertFalse(l.resyncViewed(1, 1603, 4078, 0));
		// Empty boxes witnessed = collected: the slot's entry dies.
		assertTrue(l.resyncViewed(1, 1603, 0, 0));
		assertEquals(0, l.itemPairs().length);
	}

	@Test
	public void seedEntries_dropsEmptyAndNull_gsonShapeRoundTrips()
	{
		Map<Integer, CollectLedger.Entry> seed = new HashMap<>();
		CollectLedger.Entry empty = new CollectLedger.Entry();
		seed.put(1, empty);
		seed.put(2, null);
		CollectLedger l = new CollectLedger();
		l.seedEntries(seed);
		assertEquals(0, l.itemPairs().length);
		assertEquals(0, l.coins());
	}
}

package com.flipgoblin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

/**
 * Pins the history-import reconciliation (live b43 finding, 2026-07-11: a 1000-bar buy captured as
 * partial fills summing 747 double-imported whole from the History tab; overlay read "1747B").
 */
public class GeHistoryReconcileTest
{
	private static TradeRecord fill(int item, TradeRecord.Side side, long price, int qty, int slot)
	{
		return new TradeRecord(item, side, price, qty, price * qty, slot, 1000L);
	}

	private static TradeRecord importRec(int item, TradeRecord.Side side, long price, int qty)
	{
		return new TradeRecord(item, side, price, qty, price * qty, -1, 2000L, true, 0);
	}

	/** The live mithril ledger: six partial buy fills (747 @951, slot 1) + interleaved sells. */
	private static List<TradeRecord> mithrilFills()
	{
		List<TradeRecord> recs = new ArrayList<>();
		for (int q : new int[]{22, 360, 45})
		{
			recs.add(fill(2359, TradeRecord.Side.BUY, 951, q, 1));
		}
		recs.add(fill(2359, TradeRecord.Side.SELL, 974, 10, 2));
		for (int q : new int[]{90, 27})
		{
			recs.add(fill(2359, TradeRecord.Side.BUY, 951, q, 1));
		}
		for (int q : new int[]{501, 259, 27})
		{
			recs.add(fill(2359, TradeRecord.Side.SELL, 974, q, 2));
		}
		recs.add(fill(2359, TradeRecord.Side.BUY, 951, 203, 1));
		recs.add(fill(2359, TradeRecord.Side.SELL, 974, 203, 2));
		return recs;
	}

	@Test
	public void partialCoverage_importsOnlyTheGap()
	{
		// History entry: "Bought 1000 for 951,000"; fills cover 747 → import exactly the 253 gap.
		TradeRecord r = GeHistoryReconcile.importFor(
			mithrilFills(), 2359, TradeRecord.Side.BUY, 1000, 951_000L, 5000L);
		assertEquals(253, r.quantity);
		assertEquals(951, r.price);
		assertEquals(951_000L - 747L * 951L, r.spent);
		assertEquals(-1, r.slot);
		assertTrue(r.recovered);
	}

	@Test
	public void fullCoverage_importsNothing()
	{
		// "Sold 1000 for 974,000"; the sell fills cover it all.
		assertNull(GeHistoryReconcile.importFor(
			mithrilFills(), 2359, TradeRecord.Side.SELL, 1000, 974_000L, 5000L));
	}

	@Test
	public void noMatchingRun_importsWhole()
	{
		// A pre-plugin offer at a different price: no run agrees, so import the whole entry.
		TradeRecord r = GeHistoryReconcile.importFor(
			mithrilFills(), 2359, TradeRecord.Side.BUY, 500, 430_000L, 5000L); // @860
		assertEquals(500, r.quantity);
		assertEquals(860, r.price);
	}

	@Test
	public void newerRunAtAnotherPrice_doesNotMaskTheOlderOne()
	{
		// A second buy offer @944 starts filling on another slot AFTER the 951 offer completed;
		// the 951 entry must still reconcile against ITS run, not the newest one.
		List<TradeRecord> recs = mithrilFills();
		recs.add(fill(2359, TradeRecord.Side.BUY, 944, 400, 2));
		TradeRecord r = GeHistoryReconcile.importFor(
			recs, 2359, TradeRecord.Side.BUY, 1000, 951_000L, 5000L);
		assertEquals(253, r.quantity);
		assertEquals(951, r.price);
	}


	@Test
	public void newerSamePriceRun_doesNotReopenAnOldEntry()
	{
		// A fresh 951 offer starts filling (300 on slot 2) AFTER the old 951 offer's run (747).
		// Re-parsing the old "Bought 1000" entry must reconcile against the LARGEST agreeing run
		// (747), yielding the same 253 gap the shape-dedup already holds, never a 700 re-import.
		List<TradeRecord> recs = mithrilFills();
		recs.add(fill(2359, TradeRecord.Side.BUY, 951, 300, 2));
		TradeRecord r = GeHistoryReconcile.importFor(
			recs, 2359, TradeRecord.Side.BUY, 1000, 951_000L, 5000L);
		assertEquals(253, r.quantity);
	}


	@Test
	public void runsSegmentBySlotWithinTheItemSideView()
	{
		// Same item+side on two slots = two runs, newest first; other items interleave freely.
		List<TradeRecord> recs = new ArrayList<>();
		recs.add(fill(2359, TradeRecord.Side.BUY, 951, 100, 1));
		recs.add(fill(444, TradeRecord.Side.BUY, 150, 999, 3)); // unrelated item mid-run
		recs.add(fill(2359, TradeRecord.Side.BUY, 951, 200, 1));
		recs.add(fill(2359, TradeRecord.Side.BUY, 944, 50, 2));
		List<long[]> runs = GeHistoryReconcile.runs(recs, 2359, TradeRecord.Side.BUY);
		assertEquals(2, runs.size());
		assertEquals(50, runs.get(0)[0]); // newest run: slot 2
		assertEquals(300, runs.get(1)[0]); // older run: slot 1, uninterrupted by item 444
	}
}

package com.flipgoblin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/** Pins the 4h buy-limit window model: first-buy anchor, in-window accumulation, full reset. */
public class GeLimitsTest
{
	private static final long H = 60 * 60 * 1000L;

	private static void assertUsage(long used, long resetAtMs, boolean exact, boolean hedged,
		GeLimits.Usage actual)
	{
		assertEquals(used, actual.used);
		assertEquals(resetAtMs, actual.resetAtMs);
		assertEquals(exact, actual.exact);
		assertEquals(hedged, actual.hedged);
	}

	private static TradeRecord buy(int itemId, int qty, long ts)
	{
		return new TradeRecord(itemId, TradeRecord.Side.BUY, 100, qty, 100L * qty, 0, ts);
	}

	private static TradeRecord sell(int itemId, int qty, long ts)
	{
		return new TradeRecord(itemId, TradeRecord.Side.SELL, 100, qty, 100L * qty, 0, ts);
	}

	@Test
	public void noBuysMeansNoWindow()
	{
		assertNull(GeLimits.usage(Arrays.asList(sell(4151, 5, 1000)), 4151, 2000, 0, 0));
	}

	@Test
	public void buysAccumulateInsideTheWindow_anchoredOnFirstBuy()
	{
		List<TradeRecord> recs = Arrays.asList(
			buy(4151, 10, 1 * H),
			sell(4151, 3, 2 * H), // sells never count
			buy(4151, 25, 3 * H),
			buy(999, 40, 3 * H)); // other items never count
		assertUsage(35, 5 * H, false, false, GeLimits.usage(recs, 4151, 4 * H, 0, 0));
	}

	@Test
	public void historyImports_slotMinusOne_neverCountTowardTheWindow()
	{
		TradeRecord imported = new TradeRecord(4151, TradeRecord.Side.BUY, 100, 500, 50_000, -1, 3 * H);
		assertNull(GeLimits.usage(Arrays.asList(imported), 4151, 4 * H, 0, 0));
		// ...and they don't pollute a window opened by a slot-observed buy either.
		List<TradeRecord> recs = Arrays.asList(buy(4151, 10, 3 * H), imported);
		assertUsage(10, 7 * H, false, false, GeLimits.usage(recs, 4151, 4 * H, 0, 0));
	}

	@Test
	public void windowExpiryReturnsNull_andNextBuyOpensAFreshWindow()
	{
		List<TradeRecord> recs = Arrays.asList(buy(4151, 10, 1 * H));
		assertNull(GeLimits.usage(recs, 4151, 5 * H, 0, 0)); // 1h + 4h window has ended

		List<TradeRecord> recs2 = Arrays.asList(
			buy(4151, 10, 1 * H),
			buy(4151, 7, 6 * H)); // past the first window: new anchor, count restarts
		assertUsage(7, 10 * H, false, false, GeLimits.usage(recs2, 4151, 7 * H, 0, 0));
	}

	@Test
	public void buyExactlyAtWindowEndStartsTheNextWindow()
	{
		List<TradeRecord> recs = Arrays.asList(
			buy(4151, 10, 1 * H),
			buy(4151, 5, 5 * H)); // ts == anchor + 4h, outside the old window
		assertUsage(5, 9 * H, false, false, GeLimits.usage(recs, 4151, 6 * H, 0, 0));
	}

	@Test
	public void exactWhenTheWholeWindowWasObservedLive()
	{
		List<TradeRecord> recs = Arrays.asList(buy(4151, 10, 3 * H), buy(4151, 5, 4 * H));
		// Observation started before the anchor and no fill is recovered → exact.
		assertUsage(15, 7 * H, true, false, GeLimits.usage(recs, 4151, 5 * H, 2 * H, 0));
		// Observation started AFTER the anchor → still a lower bound.
		assertUsage(15, 7 * H, false, false, GeLimits.usage(recs, 4151, 5 * H, 3 * H + 1, 0));
		// A recovered fill in the window has an estimated time → never exact, and hedged.
		TradeRecord rec = new TradeRecord(4151, TradeRecord.Side.BUY, 100, 5, 500, 0, 4 * H, true, 3 * H);
		List<TradeRecord> withRecovered = Arrays.asList(buy(4151, 10, 3 * H), rec);
		assertUsage(15, 7 * H, false, true, GeLimits.usage(withRecovered, 4151, 5 * H, 2 * H, 0));
	}

	private static TradeRecord recovered(int itemId, int qty, long detectedTs, long offlineSince)
	{
		return new TradeRecord(itemId, TradeRecord.Side.BUY, 100, qty, 100L * qty, 0, detectedTs,
			true, offlineSince);
	}

	// Two limits bought overnight: while the offline gap is under 8h, even the earliest
	// feasible placement leaves the second window active, so one limit's worth is provable.
	@Test
	public void twoLimitsOffline_shortGap_provesOneLimitStillSpent()
	{
		List<TradeRecord> recs = Arrays.asList(
			recovered(2357, 10_000, 7 * H, 0 * H + 1),
			recovered(2357, 10_000, 7 * H, 0 * H + 1));
		// Earliest placement: window 1 at ~0h holds 10k, window 2 at ~4h holds 10k and is
		// still active at 7h. Reset time stays the latest bound (detection + 4h). Hedged.
		assertUsage(10_000, 11 * H, false, true,
			GeLimits.usage(recs, 2357, 7 * H, 0, 10_000));
	}

	// Past 8h the second window may already have reset, so nothing is provable.
	@Test
	public void twoLimitsOffline_longGap_provesNothing()
	{
		List<TradeRecord> recs = Arrays.asList(
			recovered(2357, 10_000, 9 * H, 0 * H + 1),
			recovered(2357, 10_000, 9 * H, 0 * H + 1));
		assertNull(GeLimits.usage(recs, 2357, 9 * H, 0, 10_000));
	}

	// With no known buy limit, only a single window can be assumed: provable inside the
	// first 4h of the offline bound, nothing after.
	@Test
	public void unknownLimit_singleWindowBound()
	{
		List<TradeRecord> inside = Arrays.asList(recovered(2357, 500, 3 * H, 1));
		assertUsage(500, 7 * H, false, true, GeLimits.usage(inside, 2357, 3 * H + 1800_000, 0, 0));
		List<TradeRecord> past = Arrays.asList(recovered(2357, 500, 5 * H, 1));
		assertNull(GeLimits.usage(past, 2357, 5 * H, 0, 0));
	}

	// A recovered fill with no offlineSince bound could be arbitrarily old and proves nothing.
	@Test
	public void recoveredWithoutBound_provesNothing()
	{
		List<TradeRecord> recs = Arrays.asList(recovered(2357, 500, 1 * H, 0));
		assertNull(GeLimits.usage(recs, 2357, 2 * H, 0, 10_000));
	}

	// Live buys after login stay provable even when the offline buys are not.
	@Test
	public void liveBuysSurviveWhenOfflineBuysAge_out()
	{
		List<TradeRecord> recs = Arrays.asList(
			recovered(2357, 10_000, 6 * H, 1),  // earliest window [0,4h), expired by 7h
			buy(2357, 500, 6 * H + 1800_000));  // live at 6.5h opens a fresh window
		assertUsage(500, 10 * H, false, true, GeLimits.usage(recs, 2357, 7 * H, 0, 10_000));
	}

	// If early placement would force a live fill into a full window, the model does not fit
	// the data; fall back to counting live fills only.
	@Test
	public void infeasibleEarlyPlacement_fallsBackToLiveOnly()
	{
		List<TradeRecord> recs = Arrays.asList(
			recovered(2357, 10_000, 6 * H + 1800_000, 6 * H), // [6h, 6.5h]: fills the window
			buy(2357, 500, 7 * H)); // live inside that same window
		assertUsage(500, 10 * H + 1800_000, false, true,
			GeLimits.usage(recs, 2357, 7 * H, 0, 10_000));
	}
}

package com.flipgoblin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

public class GeOfferDifferTest
{
	private static final int SLOT = 0;

	private static OfferSnapshot snap(int item, GrandExchangeOfferState st, int total, int sold, long spent)
	{
		return new OfferSnapshot(item, st, total, sold, spent, 100); // one shared set price (identity field)
	}

	private static OfferSnapshot snapAt(int item, GrandExchangeOfferState st, int total, int sold, long spent,
		long price)
	{
		return new OfferSnapshot(item, st, total, sold, spent, price);
	}

	@Test
	public void staleRefireOfDeadOffer_doesNotAliasAFreshSameItemBaseline()
	{
		// The law-rune phantom (2026-08-10): a completed 6000@124 buy's state refires AFTER a fresh
		// 0-progress offer of the same item occupies the slot. Different totalQuantity/price → a
		// DIFFERENT offer: the refire must baseline, never emit a 6000 fill.
		GeOfferDiffer d = new GeOfferDiffer();
		assertFalse(d.onOffer(SLOT, snapAt(563, GrandExchangeOfferState.BUYING, 12_000, 0, 0, 123), 1L)
			.isPresent());
		assertFalse(d.onOffer(SLOT, snapAt(563, GrandExchangeOfferState.BOUGHT, 6_000, 6_000, 744_000, 124), 2L)
			.isPresent());
	}

	@Test
	public void sameItemOppositeSide_neverReadsAsTheSameOffer()
	{
		// Side is part of the offer identity: a SELL baseline followed by a BUY of the same item whose
		// counters happen to overtake it must reset, not emit the overlap as a fill.
		GeOfferDiffer d = new GeOfferDiffer();
		assertFalse(d.onOffer(SLOT, snap(563, GrandExchangeOfferState.SELLING, 6_000, 300, 37_200), 1L)
			.isPresent());
		assertFalse(d.onOffer(SLOT, snap(563, GrandExchangeOfferState.BUYING, 6_000, 5_000, 500_000), 2L)
			.isPresent());
	}

	@Test
	public void seededBaseline_recoversOfflineFills()
	{
		// A persisted seed carries the full offer identity; the login replay diffs against it and
		// the offline delta comes back as a RECOVERED fill with the honest time window.
		Map<Integer, GeOfferDiffer.SlotState> seed = new HashMap<>();
		seed.put(SLOT, new GeOfferDiffer.SlotState(100, 2, 200, 50L, TradeRecord.Side.BUY, 10, 100));
		GeOfferDiffer d = new GeOfferDiffer(seed);
		TradeRecord r = d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BOUGHT, 10, 10, 1000), 100L).get();
		assertEquals(8, r.quantity);
		assertTrue(r.recovered);
		assertEquals(50L, r.offlineSince);
	}

	@Test
	public void freshBuy_partialThenComplete_emitsSummingDeltas()
	{
		GeOfferDiffer d = new GeOfferDiffer();
		// Placement: first sighting at 0 → baseline, no fill.
		assertFalse(d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 0, 0), 1L).isPresent());
		// Partial fill of 4 @100.
		TradeRecord f1 = d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 4, 400), 2L).get();
		assertEquals(TradeRecord.Side.BUY, f1.side);
		assertEquals(4, f1.quantity);
		assertEquals(100, f1.price);
		assertEquals(400, f1.spent);
		assertEquals(100, f1.itemId);
		assertEquals(SLOT, f1.slot);
		assertEquals(2L, f1.timestamp);
		// Remaining 6 fill and the offer completes.
		TradeRecord f2 = d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 10, 1000), 3L).get();
		assertEquals(6, f2.quantity);
		assertEquals(600, f2.spent);
		// BOUGHT with no new quantity → no fill.
		assertFalse(d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BOUGHT, 10, 10, 1000), 4L).isPresent());
		assertEquals(10, f1.quantity + f2.quantity); // deltas sum to the total
	}

	@Test
	public void cancelAfterPartial_emitsOnlyThePartial()
	{
		GeOfferDiffer d = new GeOfferDiffer();
		d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 0, 0), 1L);
		TradeRecord f = d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 3, 297), 2L).get();
		assertEquals(3, f.quantity);
		assertEquals(99, f.price);
		// Cancel with no additional fill → nothing.
		assertFalse(d.onOffer(SLOT, snap(100, GrandExchangeOfferState.CANCELLED_BUY, 10, 3, 297), 3L).isPresent());
		// Collected → slot cleared.
		assertFalse(d.onOffer(SLOT, snap(0, GrandExchangeOfferState.EMPTY, 0, 0, 0), 4L).isPresent());
	}

	@Test
	public void cancelCarryingAFinalFill_emitsIt()
	{
		GeOfferDiffer d = new GeOfferDiffer();
		d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 0, 0), 1L);
		TradeRecord f = d.onOffer(SLOT, snap(100, GrandExchangeOfferState.CANCELLED_BUY, 10, 2, 200), 2L).get();
		assertEquals(TradeRecord.Side.BUY, f.side);
		assertEquals(2, f.quantity);
	}

	@Test
	public void loginReplay_emptySeed_isSuppressed()
	{
		GeOfferDiffer d = new GeOfferDiffer();
		// Login refires a pre-existing, already-partly-filled offer. With no baseline we must NOT emit it.
		assertFalse(d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 5, 500), 1L).isPresent());
		// Only genuinely-new fills after the replay are captured.
		TradeRecord f = d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 7, 700), 2L).get();
		assertEquals(2, f.quantity);
	}

	@Test
	public void offlineFills_recoveredFromPersistedSeed()
	{
		Map<Integer, GeOfferDiffer.SlotState> seed = new HashMap<>();
		// Last session left it at 3 filled, last seen at t=1000.
		seed.put(SLOT, new GeOfferDiffer.SlotState(100, 3, 300, 1000L, TradeRecord.Side.BUY, 10, 100));
		GeOfferDiffer d = new GeOfferDiffer(seed);
		// Login at t=5000: the offer progressed to 5 while offline → the 2-unit delta is recovered,
		// MARKED as such, and bounded to its offline window [1000, 5000].
		TradeRecord f = d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 5, 520), 5000L).get();
		assertEquals(2, f.quantity);
		assertEquals(220, f.spent);
		assertEquals(110, f.price);
		assertTrue(f.recovered);
		assertEquals(1000L, f.offlineSince);
		assertEquals(5000L, f.timestamp);
		// The NEXT fill on the same slot is live again, never marked recovered.
		TradeRecord live = d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 7, 740), 6000L).get();
		assertFalse(live.recovered);
		assertEquals(0L, live.offlineSince);
	}

	@Test
	public void seededSlot_replayIdentical_thenLiveFill_notRecovered()
	{
		Map<Integer, GeOfferDiffer.SlotState> seed = new HashMap<>();
		seed.put(SLOT, new GeOfferDiffer.SlotState(100, 3, 300, 1000L, TradeRecord.Side.BUY, 10, 100));
		GeOfferDiffer d = new GeOfferDiffer(seed);
		// Login replay with UNCHANGED values (nothing happened offline) → no emit, seeded status consumed.
		assertFalse(d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 3, 300), 5000L).isPresent());
		// A later fill this session is a normal live fill.
		TradeRecord f = d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 6, 600), 6000L).get();
		assertEquals(3, f.quantity);
		assertFalse(f.recovered);
	}

	@Test
	public void seededSlot_differentItem_baselinesOnly_noPhantomRecovery()
	{
		Map<Integer, GeOfferDiffer.SlotState> seed = new HashMap<>();
		seed.put(SLOT, new GeOfferDiffer.SlotState(100, 3, 300, 1000L, TradeRecord.Side.BUY, 10, 100));
		GeOfferDiffer d = new GeOfferDiffer(seed);
		// The slot was collected + reused for another item while offline; first sighting only baselines.
		assertFalse(d.onOffer(SLOT, snap(200, GrandExchangeOfferState.SELLING, 5, 2, 400), 5000L).isPresent());
	}

	@Test
	public void slotReuse_afterEmpty_startsFresh_noPhantom()
	{
		GeOfferDiffer d = new GeOfferDiffer();
		d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 5, 0, 0), 1L);
		assertEquals(5, d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 5, 5, 500), 2L).get().quantity);
		d.onOffer(SLOT, snap(0, GrandExchangeOfferState.EMPTY, 0, 0, 0), 3L); // collected
		// A different item now occupies the slot; first sighting only baselines.
		assertFalse(d.onOffer(SLOT, snap(200, GrandExchangeOfferState.SELLING, 3, 0, 0), 4L).isPresent());
		TradeRecord sell = d.onOffer(SLOT, snap(200, GrandExchangeOfferState.SELLING, 3, 3, 900), 5L).get();
		assertEquals(TradeRecord.Side.SELL, sell.side);
		assertEquals(200, sell.itemId);
		assertEquals(3, sell.quantity);
	}

	@Test
	public void slotReuse_withoutEmpty_itemChange_reBaselines()
	{
		GeOfferDiffer d = new GeOfferDiffer();
		d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BOUGHT, 10, 10, 1000), 1L); // seen, baselined
		// New item appears in the slot without an EMPTY in between → treat as a new offer, don't emit.
		assertFalse(d.onOffer(SLOT, snap(200, GrandExchangeOfferState.SELLING, 4, 0, 0), 2L).isPresent());
	}

	@Test
	public void sellMirror_soldEmitsSellSide()
	{
		GeOfferDiffer d = new GeOfferDiffer();
		d.onOffer(SLOT, snap(200, GrandExchangeOfferState.SELLING, 10, 0, 0), 1L);
		TradeRecord f = d.onOffer(SLOT, snap(200, GrandExchangeOfferState.SOLD, 10, 10, 2000), 2L).get();
		assertEquals(TradeRecord.Side.SELL, f.side);
		assertEquals(10, f.quantity);
		assertEquals(200, f.price);
	}

	@Test
	public void multiPriceDelta_roundsPrice_retainsExactSpent()
	{
		GeOfferDiffer d = new GeOfferDiffer();
		d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 5, 0, 0), 1L);
		// 5 units for 503gp (units filled at mixed prices) → avg 100.6 → round 101, but spent stays exact.
		TradeRecord f = d.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 5, 5, 503), 2L).get();
		assertEquals(101, f.price);
		assertEquals(503, f.spent);
		assertEquals(5, f.quantity);
	}

	@Test
	public void snapshotBaseline_roundTrips_forPersistence()
	{
		GeOfferDiffer d1 = new GeOfferDiffer();
		d1.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 3, 300), 1L);
		Map<Integer, GeOfferDiffer.SlotState> saved = d1.snapshotBaseline();
		assertEquals(3, saved.get(SLOT).quantitySold);
		assertEquals(300, saved.get(SLOT).spent);
		assertEquals(1L, saved.get(SLOT).lastSeen); // the recovered-fill window's lower bound persists too
		// A fresh differ seeded from the snapshot continues diffing as if uninterrupted.
		GeOfferDiffer d2 = new GeOfferDiffer(saved);
		Optional<TradeRecord> f = d2.onOffer(SLOT, snap(100, GrandExchangeOfferState.BUYING, 10, 5, 500), 2L);
		assertTrue(f.isPresent());
		assertEquals(2, f.get().quantity);
	}

	@Test
	public void logoutClearPredicate_flagsOnlyTheStorm()
	{
		// The logout/hop storm: EMPTY while not LOGGED_IN → drop.
		assertTrue(GeOfferDiffer.isLogoutClear(
			GrandExchangeOfferState.EMPTY, net.runelite.api.GameState.LOGIN_SCREEN));
		assertTrue(GeOfferDiffer.isLogoutClear(
			GrandExchangeOfferState.EMPTY, net.runelite.api.GameState.HOPPING));
		// A genuine collection arrives while LOGGED_IN → fold it.
		assertFalse(GeOfferDiffer.isLogoutClear(
			GrandExchangeOfferState.EMPTY, net.runelite.api.GameState.LOGGED_IN));
		// Non-EMPTY states are never the storm, whatever the game state.
		assertFalse(GeOfferDiffer.isLogoutClear(
			GrandExchangeOfferState.BUYING, net.runelite.api.GameState.LOGIN_SCREEN));
	}

	@Test
	public void disconnectRoundTrip_stormDropped_offlineFillRecovered()
	{
		// Live: buy filling, observed to 747/1000 (the live b42 mithril-bar scenario).
		GeOfferDiffer d = new GeOfferDiffer();
		d.onOffer(SLOT, snap(2359, GrandExchangeOfferState.BUYING, 1000, 0, 0), 1L);
		d.onOffer(SLOT, snap(2359, GrandExchangeOfferState.BUYING, 1000, 747, 705_168), 2L);

		// Disconnect: the client fires EMPTY per slot while NOT logged in; the subscriber drops it
		// via isLogoutClear, so the differ never sees it (nothing to fold here). The baseline the
		// profile persists at that moment must still hold slot 747.
		assertTrue(GeOfferDiffer.isLogoutClear(
			GrandExchangeOfferState.EMPTY, net.runelite.api.GameState.LOGIN_SCREEN));
		assertEquals(747, d.snapshotBaseline().get(SLOT).quantitySold);

		// Re-login (same or next session): replay shows BOUGHT 1000/1000 → the 253 offline units
		// come out as ONE recovered fill instead of vanishing.
		GeOfferDiffer relogged = new GeOfferDiffer(d.snapshotBaseline());
		TradeRecord f = relogged.onOffer(
			SLOT, snap(2359, GrandExchangeOfferState.BOUGHT, 1000, 1000, 944_000), 10_000L).get();
		assertEquals(253, f.quantity);
		assertTrue(f.recovered);
		assertEquals(2L, f.offlineSince);
	}

	@Test
	public void fillAboveMaxCash_keepsTheFullPrice()
	{
		// Since 2026-09-30 an offer's price and spent can pass 2,147,483,647.
		long price = 5_000_000_000L;
		GeOfferDiffer d = new GeOfferDiffer();
		assertFalse(d.onOffer(SLOT, snapAt(20997, GrandExchangeOfferState.BUYING, 2, 0, 0, price), 1L)
			.isPresent());
		TradeRecord r = d.onOffer(SLOT, snapAt(20997, GrandExchangeOfferState.BOUGHT, 2, 2, 2 * price, price), 2L)
			.get();
		assertEquals(2, r.quantity);
		assertEquals(price, r.price);
		assertEquals(2 * price, r.spent);
	}
}

package com.flipgoblin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.List;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

/** Pins the slice-D positions board: lifecycle phases, cancel-as-reuse, and the escrow math. */
public class GePositionsTest
{
	private static OfferSnapshot snap(int item, GrandExchangeOfferState st, int total, int sold, long spent,
		long price)
	{
		return new OfferSnapshot(item, st, total, sold, spent, price);
	}

	@Test
	public void lifecycle_place_partial_complete_collect()
	{
		GePositions g = new GePositions();
		g.onOffer(2, snap(100, GrandExchangeOfferState.BUYING, 10, 0, 0, 200), 1000L);
		GePositions.Position p = g.active().get(0);
		assertEquals(GePositions.Phase.WORKING, p.phase);
		assertEquals(1000L, p.firstSeen);

		g.onOffer(2, snap(100, GrandExchangeOfferState.BUYING, 10, 4, 800, 200), 2000L);
		p = g.active().get(0);
		assertEquals(4, p.quantitySold);
		assertEquals(1000L, p.firstSeen); // same offer: the position's clock does not reset
		assertEquals(GePositions.Phase.WORKING, p.phase);

		g.onOffer(2, snap(100, GrandExchangeOfferState.BOUGHT, 10, 10, 2000, 200), 3000L);
		assertEquals(GePositions.Phase.COMPLETE, g.active().get(0).phase);

		g.onOffer(2, snap(0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0), 4000L); // collected
		assertTrue(g.active().isEmpty());
	}

	@Test
	public void cancelShowsCancelled_thenReplaceRestartsTheClock()
	{
		GePositions g = new GePositions();
		g.onOffer(1, snap(100, GrandExchangeOfferState.BUYING, 10, 2, 400, 200), 1000L);
		g.onOffer(1, snap(100, GrandExchangeOfferState.CANCELLED_BUY, 10, 2, 400, 200), 2000L);
		GePositions.Position p = g.active().get(0);
		assertEquals(GePositions.Phase.CANCELLED, p.phase);
		assertEquals(1000L, p.firstSeen);

		// OSRS has no in-place modification: cancel → collect → re-place. The board shows it faithfully.
		g.onOffer(1, snap(0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0), 3000L);
		g.onOffer(1, snap(100, GrandExchangeOfferState.BUYING, 10, 0, 0, 210), 4000L);
		p = g.active().get(0);
		assertEquals(GePositions.Phase.WORKING, p.phase);
		assertEquals(210, p.price);
		assertEquals(4000L, p.firstSeen);
	}

	@Test
	public void escrow_countsWorkingBuyCoinsAndWorkingSellStockOnly()
	{
		GePositions g = new GePositions();
		// WORKING buy 10 @ 200, 4 filled: GE holds 6×200 = 1200 escrowed coins, but NO items:
		// the 4 bought sit in the collection box, independently collectable.
		g.onOffer(0, snap(100, GrandExchangeOfferState.BUYING, 10, 4, 800, 200), 1L);
		// WORKING sell 5 whips @ 1000, 2 sold: GE holds 3 unsold whips, but NO coins: the 2000
		// proceeds sit in the collection box, so counting them would double-count on collect.
		g.onOffer(1, snap(4151, GrandExchangeOfferState.SELLING, 5, 2, 2000, 1000), 2L);

		assertEquals(1200, g.heldCoins()); // working-buy escrow only (200×6); the sell adds nothing
		int[][] items = g.heldItemPairs();
		assertEquals(1, items.length); // only the working sell's unsold remainder
		assertEquals(4151, items[0][0]);
		assertEquals(3, items[0][1]);
	}

	/**
	 * COMPLETE and CANCELLED positions contribute ZERO to both coins and items: everything they hold
	 * sits in the collection box (each stack independently collectable, counters unchanged on partial
	 * collect), so no component is deterministic and counting any of it risks the double-count on
	 * collect. Never inflate. See docs/wealth-ledger-design.md.
	 */
	@Test
	public void completeAndCancelled_contributeZero()
	{
		GePositions g = new GePositions();
		g.onOffer(0, snap(100, GrandExchangeOfferState.BOUGHT, 10, 10, 2000, 200), 1L); // COMPLETE buy
		g.onOffer(1, snap(4151, GrandExchangeOfferState.SOLD, 5, 5, 5000, 1000), 1L); // COMPLETE sell
		g.onOffer(2, snap(200, GrandExchangeOfferState.CANCELLED_BUY, 10, 2, 400, 200), 1L); // refund collectable
		g.onOffer(3, snap(300, GrandExchangeOfferState.CANCELLED_SELL, 5, 3, 3000, 1000), 1L); // remainder collectable

		assertEquals(0, g.heldCoins());
		assertEquals(0, g.heldItemPairs().length);
	}

	@Test
	public void loginReplay_reconstructsTheBoard_slotOrdered()
	{
		GePositions g = new GePositions();
		g.onOffer(5, snap(2, GrandExchangeOfferState.SELLING, 100, 10, 50, 5), 1L);
		g.onOffer(1, snap(100, GrandExchangeOfferState.BUYING, 10, 0, 0, 200), 1L);
		List<GePositions.Position> active = g.active();
		assertEquals(2, active.size());
		assertEquals(1, active.get(0).slot);
		assertEquals(5, active.get(1).slot);
	}

	@Test
	public void zeroQuantityPairsAreOmitted()
	{
		GePositions g = new GePositions();
		// Fresh buy with nothing filled: no items held yet, only escrowed coins.
		g.onOffer(0, snap(100, GrandExchangeOfferState.BUYING, 10, 0, 0, 200), 1L);
		assertEquals(0, g.heldItemPairs().length);
		assertEquals(2000, g.heldCoins());
	}

	/**
	 * The 3.62m phantom peak (2026-07-13, docs/wealth-ledger-design.md): a WORKING sell's cumulative
	 * {@code spent} was counted as uncollected coins, but a mid-offer collect moves those coins to
	 * inventory with NO offer event fired, so the same gp was counted twice until the slot went
	 * EMPTY. A working sell now contributes ZERO coins; only its unsold remainder (provably still on
	 * the GE machine, not collectable) is counted as items.
	 */
	@Test
	public void workingSell_countsUnsoldItemsButZeroCoins_phantomPeakRegression()
	{
		GePositions g = new GePositions();
		// 1936 rubies listed @ 1205, 1119 sold; spent ≈ 1.32m cumulative (the poisoning shape).
		g.onOffer(3, snap(1603, GrandExchangeOfferState.SELLING, 1936, 1119, 1_348_395, 1205), 1L);
		assertEquals(0, g.heldCoins()); // the phantom coins: collectable, so counted zero
		int[][] items = g.heldItemPairs();
		assertEquals(1, items.length);
		assertEquals(1603, items[0][0]);
		assertEquals(1936 - 1119, items[0][1]); // 817 still listed
	}
}

package com.flipgoblin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import org.junit.Test;

/** Pins the GE hover tooltip markup (RS col tags + </br>; no client classes, so it stays pure). */
public class GeTooltipTest
{
	private static PriceClient.ItemPrices prices(String json)
	{
		return PriceClient.parse(4151, json, 1000L, new Gson());
	}

	@Test
	public void fullDataRendersAllLines()
	{
		String tip = GeTooltip.build(prices(
			"{\"ok\":true,\"item\":{\"name\":\"Abyssal whip\",\"ask\":1002947,\"bid\":976344,"
				+ "\"margin\":6545,\"roi\":0.0067,\"tax\":20058,\"buyLimit\":70,"
				+ "\"askVolume\":1705,\"bidVolume\":1993}}"));
		assertTrue(tip.contains("Abyssal whip"));
		assertTrue(tip.contains("Buy 1.0m · Sell 976.3k"));
		assertTrue(tip.contains("Margin"));
		assertTrue(tip.contains("(0.7%)"));
		assertTrue(tip.contains("after tax (20.1k)")); // the tax gp rides the margin line
		assertTrue(tip.contains("Limit 70"));
		assertTrue(tip.contains("<col=3fb950>")); // positive margin = profit green
		assertEquals(3, tip.split("</br>", -1).length - 1);
	}

	@Test
	public void nullSidesRenderDashes_negativeMarginRendersLossColor()
	{
		String tip = GeTooltip.build(prices(
			"{\"ok\":true,\"item\":{\"name\":\"Cannonball\",\"ask\":null,\"bid\":180,"
				+ "\"margin\":-5,\"roi\":null,\"tax\":null,\"buyLimit\":null,"
				+ "\"askVolume\":null,\"bidVolume\":9000}}"));
		assertTrue(tip.contains("Buy — · Sell 180"));
		assertTrue(tip.contains("<col=f85149>")); // loss red
		assertTrue(tip.contains("Limit —"));
		assertFalse(tip.contains("%")); // no ROI when null
	}

	@Test
	public void limitUsageLine_appearsOnlyWithAnActiveWindow_redWhenCapped()
	{
		String json = "{\"ok\":true,\"item\":{\"name\":\"Diamond\",\"ask\":1650,\"bid\":1620,"
			+ "\"margin\":10,\"roi\":0.006,\"tax\":16,\"buyLimit\":11000,"
			+ "\"askVolume\":1,\"bidVolume\":1}}";
		assertFalse(GeTooltip.build(prices(json)).contains("Bought"));

		String open = GeTooltip.build(prices(json), new GeLimits.Usage(250, 0, false, false), "15:42");
		assertTrue(open.contains("Bought ≥250/11000 · left ≤10750 · limit resets 15:42"));
		assertFalse(open.contains("<col=f85149>Bought")); // under the cap: muted, not red

		String capped = GeTooltip.build(prices(json), new GeLimits.Usage(11000, 0, false, false), "15:42");
		assertTrue(capped.contains("<col=f85149>Bought ≥11000/11000 · left ≤0"));
	}

	@Test
	public void lastFillLine_rendersPresentSidesOnly()
	{
		String json = "{\"ok\":true,\"item\":{\"name\":\"Diamond\",\"ask\":1650,\"bid\":1620,"
			+ "\"margin\":10,\"roi\":0.006,\"tax\":16,\"buyLimit\":11000,"
			+ "\"askVolume\":1,\"bidVolume\":1}}";
		TradeRecord buy = new TradeRecord(4151, TradeRecord.Side.BUY, 1_180_000, 2, 2_360_000, 0, 1000L);
		TradeRecord sell = new TradeRecord(4151, TradeRecord.Side.SELL, 1_220_000, 2, 2_440_000, 0, 2000L);

		String buyOnly = GeTooltip.build(prices(json), null, null, buy, "13:42", null, null);
		assertTrue(buyOnly.contains("Last buy 1.2m ×2 13:42"));
		assertFalse(buyOnly.contains("sell")); // capital-S "Sell" line is fine; no last-sell segment

		String both = GeTooltip.build(prices(json), null, null, buy, "13:42", sell, "14:05");
		assertTrue(both.contains("Last buy 1.2m ×2 13:42 · sell 1.2m ×2 14:05"));

		String none = GeTooltip.build(prices(json), null, null, null, null, null, null);
		assertFalse(none.contains("Last"));
	}

	@Test
	public void flipLine_signColored()
	{
		// Per-ea is an exact price figure (ruling 2026-08-28); the unrealized TOTAL stays short.
		assertEquals("<col=3fb950>Flip 12,500/ea · 1.2m unrealized</col>", GeTooltip.flipLine(12_500, 1_200_000));
		assertTrue(GeTooltip.flipLine(-50, -5_000).contains("<col=f85149>"));
	}
}

package com.flipgoblin;

import static org.junit.Assert.assertEquals;

import org.junit.Test;

public class GpTest
{
	@Test
	public void shortForm_tiers()
	{
		assertEquals("950", Gp.shortForm(950));
		assertEquals("23.5k", Gp.shortForm(23_500));
		assertEquals("1.4m", Gp.shortForm(1_400_000));
		assertEquals("999.9m", Gp.shortForm(999_900_000));
		// The billions tier starts where the m tier would round up to "1000.0m".
		assertEquals("1.0b", Gp.shortForm(999_950_000));
		assertEquals("5.0b", Gp.shortForm(5_000_000_000L));
		assertEquals("-2.1b", Gp.shortForm(-2_147_483_647L));
	}

	@Test
	public void exact_aboveMaxCash()
	{
		assertEquals("5,000,000,000", Gp.exact(5_000_000_000L));
	}
}

package com.flipgoblin;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Pins the phase-2 custody parser against every welcome-screen format captured live (2026-07-16,
 * b57/b58 auto-dumps + user reports) and the judge against the spec's verdict scenarios
 * (docs/wealth-ledger-design.md §"Login custody").
 */
public class LoginCustodyTest
{
	private static final long MIN = 60_000L;
	private static final long HOUR = 3_600_000L;
	private static final long DAY = 86_400_000L;
	private static final long NOW = 1_800_000_000_000L;

	// --- parser: live-captured formats ------------------------------------------------------------

	@Test
	public void parsesMinuteForm()
	{
		LoginCustody.Report r = LoginCustody.parse("You last logged in 40 minutes ago.");
		assertEquals(40 * MIN, r.agoMs);
		assertEquals(MIN, r.granularityMs);
	}

	@Test
	public void parsesWordForm()
	{
		// Captured verbatim 2026-07-16: "…a minute ago."; the parser must handle a/an.
		LoginCustody.Report r = LoginCustody.parse("You last logged in a minute ago.");
		assertEquals(MIN, r.agoMs);
		assertEquals(MIN, r.granularityMs);
	}

	@Test
	public void parsesHourMinuteForm()
	{
		// User-reported 2026-07-14: "1 hour, 1 min ago" (note the abbreviated unit).
		LoginCustody.Report r = LoginCustody.parse("You last logged in 1 hour, 1 min ago.");
		assertEquals(HOUR + MIN, r.agoMs);
		assertEquals(MIN, r.granularityMs);
	}

	@Test
	public void parsesLongGapForm()
	{
		LoginCustody.Report r = LoginCustody.parse("You last logged in 7 hours, 59 minutes ago.");
		assertEquals(7 * HOUR + 59 * MIN, r.agoMs);
		assertEquals(MIN, r.granularityMs);
	}

	@Test
	public void parsesDayFormWithCoarserGranularity()
	{
		// Multi-day format unobserved (assume-precise ruling 2026-07-14); if it degrades to
		// day/hour units the granularity widens and the discriminator handles the rest.
		LoginCustody.Report r = LoginCustody.parse("You last logged in 2 days, 3 hours ago.");
		assertEquals(2 * DAY + 3 * HOUR, r.agoMs);
		assertEquals(HOUR, r.granularityMs);
	}

	@Test
	public void parsesThroughColorTags()
	{
		LoginCustody.Report r =
			LoginCustody.parse("<col=ffffff>You last logged in 30 minutes ago.</col>");
		assertEquals(30 * MIN, r.agoMs);
	}

	@Test
	public void unparseableReturnsNull()
	{
		assertNull(LoginCustody.parse(null));
		assertNull(LoginCustody.parse("Welcome to Old School RuneScape"));
		assertNull(LoginCustody.parse("You last logged in earlier today."));
		assertNull(LoginCustody.parse("You last logged in 40 fortnights ago."));
	}

	// --- judge: end-anchored semantics (established live 2026-07-16, b60/b61 client.log) ----------

	private static LoginCustody.SessionRecord record(long loginAgo, long seenAgo)
	{
		LoginCustody.SessionRecord r = new LoginCustody.SessionRecord();
		r.freshLoginMs = NOW - loginAgo;
		r.anyLoginMs = NOW - loginAgo;
		r.lastSeenMs = NOW - seenAgo;
		r.bankChainTrusted = true;
		return r;
	}

	@Test
	public void acquitsWhenReportMatchesOurLogout()
	{
		// The live b61 false-conviction scenario, judged right: 54-minute session, relog a
		// minute after logout. Report "a minute ago" = the session END; matches lastSeen,
		// login instants irrelevant.
		LoginCustody.Report rep = LoginCustody.parse("You last logged in a minute ago.");
		LoginCustody.Result res = LoginCustody.judge(rep, record(54 * MIN, MIN), NOW);
		assertEquals(LoginCustody.Verdict.ACQUITTED, res.verdict);
		assertEquals(MIN, res.ourAgoMs);
	}

	@Test
	public void acquitsLongGapMinutePrecision()
	{
		LoginCustody.Report rep = LoginCustody.parse("You last logged in 7 hours, 59 minutes ago.");
		LoginCustody.Result res =
			LoginCustody.judge(rep, record(9 * HOUR, 7 * HOUR + 59 * MIN + 30_000), NOW);
		assertEquals(LoginCustody.Verdict.ACQUITTED, res.verdict);
	}

	@Test
	public void convictsWhenReportNewerThanOurLogout()
	{
		// We logged out 3h ago but the screen says a session ended 30m ago, so someone was on.
		LoginCustody.Report rep = LoginCustody.parse("You last logged in 30 minutes ago.");
		LoginCustody.Result res = LoginCustody.judge(rep, record(4 * HOUR, 3 * HOUR), NOW);
		assertEquals(LoginCustody.Verdict.CONVICTED, res.verdict);
	}

	@Test
	public void doesNotMatchLoginInstants()
	{
		// The b60/b61 bug pinned: a report that matches our LOGIN (not our logout) is a session
		// that ended while we believe we were still online: broken record → AMBIGUOUS, and
		// never a false ACQUITTED off the login anchor.
		LoginCustody.Report rep = LoginCustody.parse("You last logged in 54 minutes ago.");
		LoginCustody.Result res = LoginCustody.judge(rep, record(54 * MIN, MIN), NOW);
		assertEquals(LoginCustody.Verdict.AMBIGUOUS, res.verdict);
	}

	@Test
	public void ambiguousWithoutRecord()
	{
		LoginCustody.Report rep = LoginCustody.parse("You last logged in 40 minutes ago.");
		assertEquals(LoginCustody.Verdict.AMBIGUOUS, LoginCustody.judge(rep, null, NOW).verdict);
	}

	@Test
	public void ambiguousOnUnparseableText()
	{
		LoginCustody.Result res = LoginCustody.judge(null, record(HOUR, 5 * MIN), NOW);
		assertEquals(LoginCustody.Verdict.AMBIGUOUS, res.verdict);
		assertEquals(5 * MIN, res.ourAgoMs);
	}

	@Test
	public void ambiguousOnCoarseGranularityEvenWhenMatching()
	{
		// Hour/day-granularity display: the rounding granule could hide a whole stealth session
		// (spec's degraded-format rule); matching is not enough to acquit.
		LoginCustody.Report rep = LoginCustody.parse("You last logged in 2 days ago.");
		LoginCustody.Result res =
			LoginCustody.judge(rep, record(3 * DAY, 2 * DAY + 3 * HOUR), NOW);
		assertEquals(LoginCustody.Verdict.AMBIGUOUS, res.verdict);
	}

	@Test
	public void ambiguousWhenLogoutUnknown()
	{
		// Plugin enabled mid-session crash: record exists but lastSeen never heartbeat.
		LoginCustody.SessionRecord prev = new LoginCustody.SessionRecord();
		prev.anyLoginMs = NOW - HOUR;
		LoginCustody.Report rep = LoginCustody.parse("You last logged in 1 hour, 0 minutes ago.");
		assertEquals(LoginCustody.Verdict.AMBIGUOUS, LoginCustody.judge(rep, prev, NOW).verdict);
	}

	@Test
	public void slackAbsorbsCrashStaleHeartbeat()
	{
		// Hard-kill exit: lastSeen is up to a heartbeat (~60s) older than the true disconnect,
		// so our value reads slightly PAST the bucket; SLACK_MS keeps it an acquittal.
		LoginCustody.Report rep = LoginCustody.parse("You last logged in 10 minutes ago.");
		LoginCustody.Result res = LoginCustody.judge(rep, record(HOUR, 11 * MIN + 50_000), NOW);
		assertEquals(LoginCustody.Verdict.ACQUITTED, res.verdict);
	}

	// --- duration formatting (the overlay's "1h01m" form) ------------------------------------------

	@Test
	public void formatsDurations()
	{
		assertEquals("40m", LoginCustody.fmtDuration(40 * MIN));
		assertEquals("1h02m", LoginCustody.fmtDuration(HOUR + 2 * MIN + 30_000));
		assertEquals("2d3h", LoginCustody.fmtDuration(2 * DAY + 3 * HOUR + 7 * MIN));
		assertEquals("0m", LoginCustody.fmtDuration(12_000));
	}
}

package com.flipgoblin;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/** Which Session items cards the two hide settings hide. */
public class PanelFilterTest
{
	private static final int ITEM = 329; // Salmon

	private static TradeRecord rec(TradeRecord.Side side, long price, int qty, long ts)
	{
		return new TradeRecord(ITEM, side, price, qty, price * qty, 0, ts);
	}

	private static SessionStats.ItemPosition position(List<TradeRecord> fills, List<Dismissal> ignores)
	{
		return SessionStats.match(fills, ignores).items.get(0);
	}

	private static final List<Dismissal> NONE = Collections.emptyList();

	@Test
	public void untrackedSaleOnly_followsHideUntracked() // sold, never bought
	{
		SessionStats.ItemPosition p = position(Arrays.asList(rec(TradeRecord.Side.SELL, 189, 1, 1)), NONE);
		assertTrue(SessionStats.hiddenCard(p, true, false));
		assertFalse(SessionStats.hiddenCard(p, false, true));
	}

	@Test
	public void ignoredOnly_followsHideIgnored() // food bought and eaten
	{
		SessionStats.ItemPosition p = position(Arrays.asList(rec(TradeRecord.Side.BUY, 29, 10, 1)),
			Arrays.asList(new Dismissal(ITEM, 2)));
		assertTrue(SessionStats.hiddenCard(p, false, true));
		assertFalse(SessionStats.hiddenCard(p, true, false));
	}

	@Test
	public void flipThenRestIgnored_alwaysShown() // bought 10, sold 4, ignored 6
	{
		SessionStats.ItemPosition p = position(
			Arrays.asList(rec(TradeRecord.Side.BUY, 29, 10, 1), rec(TradeRecord.Side.SELL, 29, 4, 2)),
			Arrays.asList(new Dismissal(ITEM, 3)));
		assertFalse(SessionStats.hiddenCard(p, true, true));
	}

	@Test
	public void flipWithExtraUntrackedSales_alwaysShown()
	{
		SessionStats.ItemPosition p = position(
			Arrays.asList(rec(TradeRecord.Side.BUY, 29, 5, 1), rec(TradeRecord.Side.SELL, 35, 8, 2)), NONE);
		assertFalse(SessionStats.hiddenCard(p, true, true));
	}

	@Test
	public void ignoredThenSoldUntracked_needsBothSettings()
	{
		SessionStats.ItemPosition p = position(
			Arrays.asList(rec(TradeRecord.Side.BUY, 29, 10, 1), rec(TradeRecord.Side.SELL, 29, 3, 3)),
			Arrays.asList(new Dismissal(ITEM, 2)));
		assertTrue(SessionStats.hiddenCard(p, true, true));
		assertFalse(SessionStats.hiddenCard(p, true, false));
		assertFalse(SessionStats.hiddenCard(p, false, true));
	}

	@Test
	public void openUnitsAfterAnIgnore_alwaysShown()
	{
		SessionStats.ItemPosition p = position(
			Arrays.asList(rec(TradeRecord.Side.BUY, 29, 10, 1), rec(TradeRecord.Side.BUY, 30, 5, 3)),
			Arrays.asList(new Dismissal(ITEM, 2)));
		assertFalse(SessionStats.hiddenCard(p, true, true));
	}

	@Test
	public void plainFlip_alwaysShown()
	{
		SessionStats.ItemPosition p = position(
			Arrays.asList(rec(TradeRecord.Side.BUY, 29, 10, 1), rec(TradeRecord.Side.SELL, 35, 10, 2)), NONE);
		assertFalse(SessionStats.hiddenCard(p, true, true));
	}
}

package com.flipgoblin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import okhttp3.OkHttpClient;
import org.junit.Test;

public class PendingTradesTest
{
	/** A map in place of ConfigManager. */
	static final class MapStore implements PendingTrades.Store
	{
		final Map<String, String> saved = new HashMap<>();
		final Set<String> linked = new HashSet<>();

		@Override
		public String get(String profile)
		{
			return saved.get(profile);
		}

		@Override
		public void put(String profile, String json)
		{
			if (json == null)
			{
				saved.remove(profile);
			}
			else
			{
				saved.put(profile, json);
			}
		}

		@Override
		public boolean linked(String profile)
		{
			return linked.contains(profile);
		}
	}

	private final Gson gson = new Gson();
	private final MapStore store = new MapStore();
	private final PendingTrades trades = new PendingTrades(store, gson);

	private SyncClient client(String owner)
	{
		SyncClient s = new SyncClient(new OkHttpClient(), gson);
		s.claim(owner);
		return s;
	}

	private static TradeRecord fill(int itemId)
	{
		return new TradeRecord(itemId, TradeRecord.Side.BUY, 100, 1, 100, 0, 1720000000000L);
	}

	@Test
	public void savedFillsComeBackAfterARestart()
	{
		store.linked.add("A");
		SyncClient before = client("A");
		TradeRecord a = fill(1);
		TradeRecord b = fill(2);
		before.enqueue(a);
		before.enqueue(b);
		trades.save(before);

		SyncClient after = client("A");
		trades.load(after);
		List<TradeRecord> back = after.pendingSnapshot();
		assertEquals(2, back.size());
		assertEquals(a.clientId, back.get(0).clientId);
		assertEquals(b.clientId, back.get(1).clientId);
		assertEquals(b.price, back.get(1).price);
	}

	@Test
	public void eachCharacterKeepsItsOwnQueue()
	{
		store.linked.add("A");
		store.linked.add("B");
		SyncClient a = client("A");
		a.enqueue(fill(1));
		trades.save(a);
		SyncClient b = client("B");
		trades.load(b);
		assertEquals(0, b.pendingCount());
		b.enqueue(fill(2));
		trades.save(b);
		SyncClient a2 = client("A");
		trades.load(a2);
		assertEquals(1, a2.pendingCount());
		assertEquals(1, a2.pendingSnapshot().get(0).itemId);
	}

	@Test
	public void unlinkedOrEmptyQueuesAreNotSaved()
	{
		SyncClient s = client("A");
		s.enqueue(fill(1));
		trades.save(s);
		assertNull(store.saved.get("A")); // unlinked: it would never send

		store.linked.add("A");
		trades.save(s);
		assertTrue(store.saved.containsKey("A"));
		trades.save(client("A"));
		assertFalse(store.saved.containsKey("A")); // drained: the saved copy is removed
	}

	@Test
	public void restoreSkipsFillsAlreadyQueued()
	{
		store.linked.add("A");
		SyncClient s = client("A");
		s.enqueue(fill(1));
		trades.save(s);
		trades.load(s);
		assertEquals(1, s.pendingCount());
	}

	@Test
	public void tooManyKeepsTheNewest()
	{
		store.linked.add("A");
		SyncClient s = client("A");
		for (int i = 0; i < PendingTrades.MAX_SAVED + 3; i++)
		{
			s.enqueue(fill(i));
		}
		trades.save(s);
		SyncClient back = client("A");
		trades.load(back);
		assertEquals(PendingTrades.MAX_SAVED, back.pendingCount());
		assertEquals(3, back.pendingSnapshot().get(0).itemId);
	}

	@Test
	public void unreadableSaveIsSkipped()
	{
		store.saved.put("A", "{not json");
		SyncClient s = client("A");
		trades.load(s);
		assertEquals(0, s.pendingCount());
	}
}

package com.flipgoblin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import org.junit.Test;

/** Pins PriceClient's parse to the `GET /items/:id` contract (apps/api items.ts detail shape). */
public class PriceClientTest
{
	private static final Gson GSON = new Gson();

	@Test
	public void parsesTheDetailShape()
	{
		String body = "{\"ok\":true,\"item\":{\"id\":4151,\"name\":\"Abyssal whip\",\"buyLimit\":70,"
			+ "\"ask\":1734000,\"bid\":1731000,\"askTime\":1783600000,\"bidTime\":1783600050,"
			+ "\"margin\":-37680,\"roi\":-0.0218,\"askVolume\":4800,\"bidVolume\":5100,\"tax\":34680}}";
		PriceClient.ItemPrices p = PriceClient.parse(4151, body, 1000L, GSON);
		assertEquals("Abyssal whip", p.name);
		assertEquals((Long) 1734000L, p.ask);
		assertEquals((Long) 1731000L, p.bid);
		assertEquals((Long) (-37680L), p.margin);
		assertEquals(-0.0218, p.roi, 1e-9);
		assertEquals((Long) 34680L, p.tax);
		assertEquals((Long) 70L, p.buyLimit);
		assertEquals((Long) 4800L, p.askVolume);
		assertEquals((Long) 5100L, p.bidVolume);
		assertEquals(1000L, p.fetchedAt);
	}

	@Test
	public void nullSidesStayNull_neverZero()
	{
		String body = "{\"ok\":true,\"item\":{\"id\":2,\"name\":\"Cannonball\",\"buyLimit\":null,"
			+ "\"ask\":null,\"bid\":180,\"margin\":null,\"roi\":null,\"askVolume\":null,"
			+ "\"bidVolume\":9000,\"tax\":null}}";
		PriceClient.ItemPrices p = PriceClient.parse(2, body, 1L, GSON);
		assertNull(p.ask);
		assertNull(p.margin);
		assertNull(p.roi);
		assertNull(p.buyLimit);
		assertEquals((Long) 180L, p.bid);
		assertEquals((Long) 9000L, p.bidVolume);
	}

	@Test
	public void malformedBodyReturnsNull()
	{
		assertNull(PriceClient.parse(2, "{\"ok\":false,\"error\":\"item not found\"}", 1L, GSON));
		assertNull(PriceClient.parse(2, "[]", 1L, GSON));
	}

	@Test
	public void seriesParse_closeFallsBackToAvg_nullSideIsNaN()
	{
		String body = "{\"ok\":true,\"candles\":["
			+ "{\"time\":1,\"askClose\":100,\"bidClose\":95,\"avgAsk\":99,\"avgBid\":94,"
			+ "\"askVolume\":40,\"bidVolume\":50},"
			+ "{\"time\":2,\"askClose\":null,\"bidClose\":null,\"avgAsk\":101,\"avgBid\":96},"
			+ "{\"time\":3,\"askClose\":null,\"bidClose\":97,\"avgAsk\":null,\"avgBid\":null}]}";
		PriceClient.Series s = PriceClient.parseSeries(body, 5L, GSON);
		assertEquals(3, s.ask.length);
		assertEquals(1L, s.time[0]);
		assertEquals(3L, s.time[2]);
		assertEquals(100.0, s.ask[0], 0);
		assertEquals(101.0, s.ask[1], 0); // synthetic bucket: falls back to the window avg
		assertTrue(Double.isNaN(s.ask[2])); // side truly absent
		assertEquals(97.0, s.bid[2], 0);
		assertNull(s.askReal); // candle series carry no fill flags; only the 1m tick series do
		assertEquals(40.0, s.askVol[0], 0); // per-bucket volumes ride along for the volume pane
		assertEquals(50.0, s.bidVol[0], 0);
		assertTrue(Double.isNaN(s.askVol[1])); // absent volume stays NaN, never zero-filled
		assertEquals(5L, s.fetchedAt);
	}

	@Test
	public void seriesParse_malformedReturnsNull()
	{
		assertNull(PriceClient.parseSeries("{\"ok\":false}", 1L, GSON));
		assertNull(PriceClient.parseSeries("not json", 1L, GSON));
	}

	@Test
	public void ticksParse_minuteGridCarriesPlateaus()
	{
		// now = minute 100 (epoch 6000s); 5-minute window ⇒ slots at minutes 95..100.
		long now = 6_000_000L;
		String body = "{\"ok\":true,\"itemId\":2,\"ticks\":["
			+ "{\"time\":5580,\"ask\":100,\"bid\":null}," // minute 93: pre-window, feeds the carry
			+ "{\"time\":5760,\"ask\":null,\"bid\":90},"  // minute 96
			+ "{\"time\":5880,\"ask\":102,\"bid\":null}]}"; // minute 98
		PriceClient.Series s = PriceClient.parseTicks(body, 5, now, GSON);
		assertEquals(6, s.ask.length);
		assertEquals(5700L, s.time[0]); // minute 95
		assertEquals(6000L, s.time[5]); // the live minute
		assertEquals(100.0, s.ask[0], 0); // carried plateau from the pre-window trade
		assertTrue(Double.isNaN(s.bid[0])); // bid never traded before the window
		assertEquals(90.0, s.bid[1], 0);
		assertEquals(100.0, s.ask[1], 0);
		assertEquals(102.0, s.ask[3], 0);
		assertEquals(102.0, s.ask[5], 0); // plateau extends through "now"
		assertEquals(90.0, s.bid[5], 0);
		// Real-fill flags mark ONLY the slots where a trade landed; carried plateaus stay false.
		assertTrue(s.bidReal[1]);
		assertFalse(s.askReal[1]); // ask was carried at minute 96, not traded
		assertTrue(s.askReal[3]);
		assertFalse(s.askReal[0]);
		assertFalse(s.bidReal[5]);
	}

	@Test
	public void cacheCycleDelay_readsEdgeHeaders_fallsBackOnGarbage()
	{
		// s-maxage 60, served copy 52s old → fresh in 8s (+1.5s margin).
		assertEquals(9_500L, PriceClient.cacheCycleDelayMs("public, max-age=15, s-maxage=60", "52"));
		assertEquals(61_500L, PriceClient.cacheCycleDelayMs("s-maxage=60", "0"));
		assertEquals(3_000L, PriceClient.cacheCycleDelayMs("s-maxage=60", "59")); // floor, no hammering
		assertEquals(-1L, PriceClient.cacheCycleDelayMs("public, max-age=15", "10")); // no s-maxage
		assertEquals(-1L, PriceClient.cacheCycleDelayMs("s-maxage=60", "abc"));
		assertEquals(-1L, PriceClient.cacheCycleDelayMs(null, "10"));
		assertEquals(-1L, PriceClient.cacheCycleDelayMs("s-maxage=60", null));
	}

	@Test
	public void resample_uniformGridEndsAtCurrentBucket_carriesGaps()
	{
		// 900s buckets, 4 slots, now = 9900s → grid [7200, 8100, 9000, 9900].
		PriceClient.Series in = PriceClient.Series.candles(
			new long[]{6300, 8100}, new double[]{10, 12}, new double[]{9, 11}, null, null, 77L);
		PriceClient.Series out = PriceClient.resample(in, 900, 4, 9_900_000L);
		assertEquals(4, out.time.length);
		assertEquals(7200L, out.time[0]);
		assertEquals(9900L, out.time[3]); // always ends at the wall clock's current bucket
		assertEquals(10.0, out.ask[0], 0); // pre-window row seeds the carry
		assertEquals(12.0, out.ask[1], 0);
		assertEquals(12.0, out.ask[3], 0); // quiet buckets carry the plateau
		assertEquals(11.0, out.bid[3], 0);
		assertNull(out.askReal); // candle grids stay flagless
		assertEquals(77L, out.fetchedAt);
	}

	@Test
	public void ticksParse_derivedFillPaintsButNeverFlags()
	{
		String body = "{\"ok\":true,\"itemId\":2,\"ticks\":["
			+ "{\"time\":5760,\"ask\":100,\"bid\":null,\"src\":\"5m\"}]}"; // minute 96, derived
		PriceClient.Series s = PriceClient.parseTicks(body, 5, 6_000_000L, GSON);
		assertEquals(100.0, s.ask[1], 0); // the plateau is real information; it renders
		assertFalse(s.askReal[1]); // ...but synth averages never get a trade dot
	}

	@Test
	public void mergeTail_overwritesLiveBucket_appendsAndTrims_nullOnNoOverlap()
	{
		PriceClient.Series cached = PriceClient.Series.candles(
			new long[]{100, 200, 300}, new double[]{1, 2, 3}, new double[]{10, 20, 30}, null, null, 1000L);

		// Same live bucket refreshed: values overwritten in place, length unchanged.
		PriceClient.Series sameBucket = PriceClient.Series.candles(
			new long[]{300}, new double[]{3.5}, new double[]{35}, null, null, 2000L);
		PriceClient.Series m1 = PriceClient.mergeTail(cached, sameBucket, 3);
		assertEquals(3, m1.time.length);
		assertEquals(3.5, m1.ask[2], 0);
		assertEquals(2000L, m1.fetchedAt);

		// Boundary crossed: old live closes, new live appends, head trims to maxLen.
		PriceClient.Series crossed = PriceClient.Series.candles(
			new long[]{300, 400}, new double[]{3.9, 4}, new double[]{39, 40}, null, null, 3000L);
		PriceClient.Series m2 = PriceClient.mergeTail(cached, crossed, 3);
		assertEquals(3, m2.time.length);
		assertEquals(200L, m2.time[0]); // oldest bucket dropped
		assertEquals(400L, m2.time[2]);
		assertEquals(4.0, m2.ask[2], 0);
		assertEquals(3.9, m2.ask[1], 0);

		// Tail from far in the future (client away): no overlap, caller must refetch full depth.
		PriceClient.Series away = PriceClient.Series.candles(
			new long[]{900, 1000}, new double[]{9, 10}, new double[]{90, 100}, null, null, 4000L);
		assertNull(PriceClient.mergeTail(cached, away, 3));
		assertNull(PriceClient.mergeTail(null, sameBucket, 3));
	}

	@Test
	public void latestPriceMatch_findsLatestRealTradeAtExactPrice_insideWindow()
	{
		// Minute grid via parseTicks: trades at minutes 96 (bid 90) and 98 (ask 102), now = min 100.
		String body = "{\"ok\":true,\"itemId\":2,\"ticks\":["
			+ "{\"time\":5760,\"ask\":null,\"bid\":90},"
			+ "{\"time\":5820,\"ask\":null,\"bid\":90},"  // minute 97: later matching bid trade
			+ "{\"time\":5880,\"ask\":102,\"bid\":null}]}";
		PriceClient.Series s = PriceClient.parseTicks(body, 5, 6_000_000L, GSON);

		// My BUY fill at 90 → the bid series; latest real match is minute 97 (5820s).
		assertEquals(5_820_000L,
			PriceClient.latestPriceMatchMs(s, TradeRecord.Side.BUY, 90, 5_700_000L, 6_000_000L));
		// My SELL fill at 102 → the ask series, minute 98.
		assertEquals(5_880_000L,
			PriceClient.latestPriceMatchMs(s, TradeRecord.Side.SELL, 102, 5_700_000L, 6_000_000L));
		// Carried plateau minutes never match (real flags gate), and prices must be exact.
		assertEquals(0L,
			PriceClient.latestPriceMatchMs(s, TradeRecord.Side.BUY, 91, 5_700_000L, 6_000_000L));
		// Window bounds are honored: nothing before minute 98 for the ask.
		assertEquals(0L,
			PriceClient.latestPriceMatchMs(s, TradeRecord.Side.SELL, 102, 5_700_000L, 5_820_000L));
	}

	@Test
	public void mergeTail_nanTailSlotsKeepCachedTruth()
	{
		// Cached grid with real volumes; the tail's oldest slot has no row (NaN everywhere).
		PriceClient.Series cached = PriceClient.Series.candles(
			new long[]{100, 200, 300}, new double[]{1, 2, 3}, new double[]{10, 20, 30},
			new double[]{5, 6, 7}, new double[]{50, 60, 70}, 1000L);
		PriceClient.Series tail = PriceClient.Series.candles(
			new long[]{200, 300, 400},
			new double[]{Double.NaN, 3.5, 4}, new double[]{Double.NaN, 35, 40},
			new double[]{Double.NaN, 7.5, 8}, new double[]{Double.NaN, 75, 80}, 2000L);
		PriceClient.Series m = PriceClient.mergeTail(cached, tail, 4);
		assertEquals(4, m.time.length);
		assertEquals(6.0, m.askVol[1], 0); // NaN tail slot kept the cached volume (no erosion)
		assertEquals(2.0, m.ask[1], 0); // same for prices
		assertEquals(7.5, m.askVol[2], 0); // real tail values still overwrite
		assertEquals(8.0, m.askVol[3], 0);
	}

	@Test
	public void mergeTail_slidesTickGridAndMergesFlags()
	{
		long now = 6_000_000L; // minute 100
		String full = "{\"ok\":true,\"itemId\":2,\"ticks\":["
			+ "{\"time\":5580,\"ask\":100,\"bid\":90}," // pre-window anchor (minute 93)
			+ "{\"time\":5880,\"ask\":102,\"bid\":null}]}"; // minute 98 trade
		PriceClient.Series cached = PriceClient.parseTicks(full, 5, now, GSON); // minutes 95..100

		long later = 6_060_000L; // one refresh on (minute 101)
		String tailBody = "{\"ok\":true,\"itemId\":2,\"ticks\":["
			+ "{\"time\":5880,\"ask\":102,\"bid\":null}," // the tail fetch's own anchor
			+ "{\"time\":6060,\"ask\":null,\"bid\":95}]}"; // minute 101 trade
		PriceClient.Series tail = PriceClient.parseTicks(tailBody, 2, later, GSON); // minutes 99..101

		PriceClient.Series m = PriceClient.mergeTail(cached, tail, 6);
		assertEquals(6, m.time.length); // window size held constant
		assertEquals(5760L, m.time[0]); // minute 95 dropped off the left edge
		assertEquals(6060L, m.time[5]); // ...through the new live minute
		assertEquals(102.0, m.ask[5], 0); // plateau carried through the tail
		assertEquals(95.0, m.bid[5], 0);
		assertTrue(m.askReal[2]); // minute-98 fill flag survives from the cached region
		assertTrue(m.bidReal[5]);
		assertFalse(m.askReal[5]);
	}

	@Test
	public void ticksParse_noTradesEverIsAllNaN_malformedReturnsNull()
	{
		PriceClient.Series s = PriceClient.parseTicks("{\"ok\":true,\"itemId\":2,\"ticks\":[]}", 5, 6_000_000L, GSON);
		assertEquals(6, s.ask.length);
		assertTrue(Double.isNaN(s.ask[0]));
		assertTrue(Double.isNaN(s.bid[5]));
		assertNull(PriceClient.parseTicks("{\"ok\":false}", 5, 6_000_000L, GSON));
	}
}

package com.flipgoblin;

import static org.junit.Assert.assertEquals;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

/**
 * Pins the Java P/L math to the SAME fixture values as packages/shared/src/flips.test.ts, the
 * cross-implementation consistency guard (client panel vs website must agree).
 */
public class SessionStatsTest
{
	private static TradeRecord rec(int item, TradeRecord.Side side, long price, int qty, long ts)
	{
		return new TradeRecord(item, side, price, qty, price * qty, 0, ts);
	}

	/** A known-taxable id for the generic cases (Abyssal whip; mirrors tax.test.ts WHIP). */
	private static final int WHIP = 4151;

	@Test
	public void taxMirrorsShared()
	{
		assertEquals(3, SessionStats.geSellTax(150, WHIP)); // floor(3.0)
		assertEquals(2, SessionStats.geSellTax(149, WHIP)); // floor(2.98)
		assertEquals(0, SessionStats.geSellTax(49, WHIP)); // floor(0.98)
		assertEquals(5_000_000, SessionStats.geSellTax(300_000_000, WHIP)); // cap
		assertEquals(5_000_000, SessionStats.geSellTax(5_000_000_000L, WHIP)); // cap holds above max cash
		assertEquals(4_995_000_000L, SessionStats.netFromSale(5_000_000_000L, WHIP));
		assertEquals(0, SessionStats.geSellTax(0, WHIP));
	}

	@Test
	public void exemptItems_zeroTax() // mirrors tax.test.ts "exempt items pay ZERO tax" (FND-5)
	{
		assertEquals(0, SessionStats.geSellTax(10_000_000, 13190)); // Old school bond, 200k if taxable
		assertEquals(10_000_000, SessionStats.netFromSale(10_000_000, 13190));
		assertEquals(0, SessionStats.geSellTax(250, 379)); // Lobster, 5 if taxable
	}

	@Test
	public void breakevenMirrorsShared() // mirrors tax.test.ts "breakevenAsk: smallest ask that nets the cost basis"
	{
		assertEquals(1_020_408, SessionStats.breakevenAsk(1_000_000, WHIP));
		// The solved ask nets the basis; one gp lower does not.
		long be = SessionStats.breakevenAsk(1_000_000, WHIP);
		org.junit.Assert.assertTrue(SessionStats.netFromSale(be, WHIP) >= 1_000_000);
		org.junit.Assert.assertTrue(SessionStats.netFromSale(be - 1, WHIP) < 1_000_000);
		assertEquals(180, SessionStats.breakevenAsk(180, 379)); // exempt (Lobster): breakeven = cost
		assertEquals(305_000_000, SessionStats.breakevenAsk(300_000_000, WHIP)); // capped territory
		assertEquals(0, SessionStats.breakevenAsk(0, WHIP));
	}

	@Test
	public void exemptFlip_realizesRawSpread() // mirrors flips.test.ts "exempt items realize the raw spread"
	{
		SessionStats.Result r = SessionStats.match(Arrays.asList(
			rec(379, TradeRecord.Side.BUY, 200, 10, 1),
			rec(379, TradeRecord.Side.SELL, 250, 10, 2)));
		assertEquals(500, r.totalRealized);
	}

	@Test
	public void simpleFlip_realizes470() // mirrors flips.test.ts "simple flip"
	{
		SessionStats.Result r = SessionStats.match(Arrays.asList(
			rec(1, TradeRecord.Side.BUY, 100, 10, 1),
			rec(1, TradeRecord.Side.SELL, 150, 10, 2)));
		assertEquals(470, r.totalRealized);
		assertEquals(10, r.items.get(0).matchedQty);
		assertEquals(0, r.items.get(0).openQty);
	}

	@Test
	public void fifoOrder_oldestLotsFirst() // mirrors "FIFO order"
	{
		SessionStats.Result r = SessionStats.match(Arrays.asList(
			rec(1, TradeRecord.Side.BUY, 100, 10, 1),
			rec(1, TradeRecord.Side.BUY, 200, 10, 2),
			rec(1, TradeRecord.Side.SELL, 300, 15, 3)));
		assertEquals(10 * (294 - 100) + 5 * (294 - 200), r.totalRealized);
		assertEquals(5, r.items.get(0).openQty);
		assertEquals(5 * 200, r.items.get(0).openCost);
	}

	@Test
	public void unmatchedSells_surfacedNotPriced() // mirrors "unmatched sells"
	{
		SessionStats.Result r = SessionStats.match(
			Collections.singletonList(rec(1, TradeRecord.Side.SELL, 150, 4, 1)));
		assertEquals(0, r.totalRealized);
		assertEquals(4, r.items.get(0).unmatchedSellQty);
	}

	@Test
	public void taxCap_perUnit_hugeSell() // mirrors "tax cap applies per item unit"
	{
		SessionStats.Result r = SessionStats.match(Arrays.asList(
			rec(9, TradeRecord.Side.BUY, 250_000_000, 2, 1),
			rec(9, TradeRecord.Side.SELL, 300_000_000, 2, 2)));
		assertEquals(2L * 45_000_000, r.totalRealized);
	}

	@Test
	public void losingFlip_goesNegative() // mirrors "a losing flip"
	{
		SessionStats.Result r = SessionStats.match(Arrays.asList(
			rec(1, TradeRecord.Side.BUY, 100, 3, 1),
			rec(1, TradeRecord.Side.SELL, 90, 3, 2)));
		assertEquals(-33, r.totalRealized);
	}

	// --- Ignore ("not a flip"), same cases as the website's tests ---

	private static SessionStats.ItemPosition only(SessionStats.Result r)
	{
		assertEquals(1, r.items.size());
		return r.items.get(0);
	}

	@Test
	public void dismissal_writesOffOpenLots_realizedUntouched()
	{
		SessionStats.Result r = SessionStats.match(
			Arrays.asList(rec(WHIP, TradeRecord.Side.BUY, 100, 10, 1)),
			Arrays.asList(new Dismissal(WHIP, 2)));
		assertEquals(0, r.totalRealized);
		SessionStats.ItemPosition p = only(r);
		assertEquals(0, p.openQty);
		assertEquals(0, p.openCost);
		assertEquals(10, p.ignoredQty);
	}

	@Test
	public void dismissal_midEpisode_soldPartStaysRealized()
	{
		// Buy 10@100, sell 4@150 (net 147 → +47/unit), ignore the open 6.
		SessionStats.Result r = SessionStats.match(
			Arrays.asList(rec(WHIP, TradeRecord.Side.BUY, 100, 10, 1), rec(WHIP, TradeRecord.Side.SELL, 150, 4, 2)),
			Arrays.asList(new Dismissal(WHIP, 3)));
		assertEquals(4 * 47, r.totalRealized);
		SessionStats.ItemPosition p = only(r);
		assertEquals(0, p.openQty);
		assertEquals(6, p.ignoredQty);
	}

	@Test
	public void dismissal_laterSellsUntracked_rebuyOpensFresh()
	{
		SessionStats.Result r = SessionStats.match(
			Arrays.asList(
				rec(WHIP, TradeRecord.Side.BUY, 100, 10, 1),
				rec(WHIP, TradeRecord.Side.SELL, 150, 3, 5), // after the ignore, no cost basis
				rec(WHIP, TradeRecord.Side.BUY, 120, 5, 6), // fresh position
				rec(WHIP, TradeRecord.Side.SELL, 200, 5, 7)), // net 196 → +76/unit
			Arrays.asList(new Dismissal(WHIP, 2)));
		SessionStats.ItemPosition p = only(r);
		assertEquals(3, p.unmatchedSellQty);
		assertEquals(5 * 76, r.totalRealized);
		assertEquals(10, p.ignoredQty);
		assertEquals(0, p.openQty);
	}

	@Test
	public void dismissal_staleIsNoop_sameTsFillWrittenOff()
	{
		SessionStats.Result stale = SessionStats.match(
			Arrays.asList(rec(WHIP, TradeRecord.Side.BUY, 100, 5, 1), rec(WHIP, TradeRecord.Side.SELL, 150, 5, 2)),
			Arrays.asList(new Dismissal(WHIP, 3)));
		assertEquals(0, only(stale).ignoredQty);
		assertEquals(5 * 47, stale.totalRealized);
		SessionStats.Result tied = SessionStats.match(
			Arrays.asList(rec(WHIP, TradeRecord.Side.BUY, 100, 5, 3)),
			Arrays.asList(new Dismissal(WHIP, 3)));
		assertEquals(0, only(tied).openQty); // the fill sorts before the ignore on a tie
		assertEquals(5, only(tied).ignoredQty);
		// Another item's ignore touches nothing here.
		SessionStats.Result other = SessionStats.match(
			Arrays.asList(rec(WHIP, TradeRecord.Side.BUY, 100, 5, 1)),
			Arrays.asList(new Dismissal(379, 2)));
		assertEquals(5, only(other).openQty);
	}

	@Test
	public void sideTotals_countEveryFillPerSide()
	{
		SessionStats.ItemPosition p = only(SessionStats.match(Arrays.asList(
			rec(WHIP, TradeRecord.Side.BUY, 100, 10, 1),
			rec(WHIP, TradeRecord.Side.BUY, 110, 10, 2),
			rec(WHIP, TradeRecord.Side.SELL, 150, 25, 3)))); // 5 of these have no cost basis
		assertEquals(20, p.boughtQty);
		assertEquals(2_100, p.boughtValue);
		assertEquals(100, p.boughtMinPrice);
		assertEquals(110, p.boughtMaxPrice);
		assertEquals(25, p.soldQty);
		assertEquals(3_750, p.soldValue);
		assertEquals(150, p.soldMinPrice);
		assertEquals(150, p.soldMaxPrice);
	}
}

package com.flipgoblin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonArray;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.Arrays;
import org.junit.Test;

/**
 * Pins the sync wire payload to the API-8 contract (`parseSyncBody` in apps/api/src/flips.ts):
 * {flips: [{itemId, side: "buy"|"sell", price, qty, ts, geSlot?, clientId}]}. If either side renames a
 * field, this test (or the server e2e) goes red. It is the cross-system contract guard.
 */
public class SyncClientTest
{
	@Test
	public void lockedBodyDistinguishesTheLapseLockFromABadToken()
	{
		// The lapse lock rides a 401 whose body names it; anything else is not "locked".
		org.junit.Assert.assertTrue(SyncClient.lockedBody(401, "{\"ok\":false,\"error\":\"character locked\"}"));
		org.junit.Assert.assertFalse(SyncClient.lockedBody(401, "{\"ok\":false,\"error\":\"unauthenticated\"}"));
		org.junit.Assert.assertFalse(SyncClient.lockedBody(403, "{\"error\":\"character locked\"}"));
		org.junit.Assert.assertFalse(SyncClient.lockedBody(401, null));
		org.junit.Assert.assertFalse(SyncClient.lockedBody(200, ""));
	}

	@Test
	public void payloadMatchesTheApiContract()
	{
		TradeRecord buy = new TradeRecord(4151, TradeRecord.Side.BUY, 1_000_000, 2, 2_000_000, 3, 1720000000000L);
		TradeRecord sell = new TradeRecord(4151, TradeRecord.Side.SELL, 1_100_000, 1, 1_100_000, 5, 1720000060000L);
		JsonObject body = SyncClient.buildPayload(Arrays.asList(buy, sell));

		JsonArray flips = body.getAsJsonArray("flips");
		assertEquals(2, flips.size());

		JsonObject f0 = flips.get(0).getAsJsonObject();
		assertEquals(4151, f0.get("itemId").getAsInt());
		assertEquals("buy", f0.get("side").getAsString());
		assertEquals(1_000_000, f0.get("price").getAsLong());
		assertEquals(2, f0.get("qty").getAsInt());
		assertEquals(1720000000000L, f0.get("ts").getAsLong());
		assertEquals(3, f0.get("geSlot").getAsInt());
		assertEquals(buy.clientId, f0.get("clientId").getAsString());
		assertEquals(36, f0.get("clientId").getAsString().length()); // UUID: fits the server's 1-64 cap

		assertEquals("sell", flips.get(1).getAsJsonObject().get("side").getAsString());
		assertFalse(f0.get("clientId").getAsString().equals(
			flips.get(1).getAsJsonObject().get("clientId").getAsString()));
	}

	@Test
	public void negativeSlotIsOmitted() // geSlot is optional in the contract (null ⇔ absent)
	{
		TradeRecord r = new TradeRecord(1, TradeRecord.Side.BUY, 10, 1, 10, -1, 1720000000000L);
		JsonObject f0 = SyncClient.buildPayload(Arrays.asList(r)).getAsJsonArray("flips")
			.get(0).getAsJsonObject();
		assertTrue(!f0.has("geSlot"));
	}

	@Test
	public void recoveredFillCarriesFlagAndWindow_liveFillOmitsBoth()
	{
		TradeRecord recovered = new TradeRecord(
			4151, TradeRecord.Side.SELL, 1_000, 2, 2_000, 1, 1720000060000L, true, 1720000000000L);
		TradeRecord live = new TradeRecord(4151, TradeRecord.Side.BUY, 900, 1, 900, 2, 1720000070000L);
		JsonArray flips = SyncClient.buildPayload(Arrays.asList(recovered, live)).getAsJsonArray("flips");

		JsonObject f0 = flips.get(0).getAsJsonObject();
		assertTrue(f0.get("recovered").getAsBoolean());
		assertEquals(1720000000000L, f0.get("offlineSince").getAsLong());

		JsonObject f1 = flips.get(1).getAsJsonObject();
		assertFalse(f1.has("recovered"));
		assertFalse(f1.has("offlineSince"));
	}

	@Test
	public void assetsJsonCarriesPairsBankAtAndOffers() // mirrors parseAssetsBody in apps/api/src/assets.ts
	{
		AssetSnapshot snap = AssetSnapshot.of(0L, 1_000L, new int[][]{{4151, 3}});
		GePositions.Position sell = new GePositions.Position(
			2, 2359, TradeRecord.Side.SELL, 92, 7081, 0, 0, GePositions.Phase.WORKING, 1L, 2L);
		String json = SyncClient.assetsJson(snap, 1720000000000L, true, Arrays.asList(sell));

		assertEquals("{\"pairs\":[[995,1000],[4151,3]],\"bankAt\":1720000000000,\"bankFresh\":true,"
			+ "\"offers\":[{\"slot\":2,\"itemId\":2359,\"side\":\"sell\",\"price\":92,"
			+ "\"total\":7081,\"filled\":0,\"phase\":\"working\"}]}", json);
	}

	@Test
	public void assetsJsonWithNoOffersSendsEmptyArray() // [] = "none standing"; absent = old plugin
	{
		AssetSnapshot snap = AssetSnapshot.of(0L, 500L);
		String json = SyncClient.assetsJson(snap, 0L, false, java.util.Collections.emptyList());
		assertEquals("{\"pairs\":[[995,500]],\"bankFresh\":false,\"offers\":[]}", json);
	}

	/**
	 * PLUG-7: the crowd payload matches parseCrowdBody in apps/api/src/crowd.ts:
	 * {events: [{itemId, side, price, quantity, ts(SECONDS), clientId}]} and NEVER the GE slot.
	 */
	@Test
	public void crowdPayloadMatchesTheApiContractAndOmitsTheSlot()
	{
		TradeRecord buy = new TradeRecord(4151, TradeRecord.Side.BUY, 1_000_000, 2, 2_000_000, 3, 1720000000000L);
		JsonObject body = SyncClient.buildCrowdPayload(Arrays.asList(buy));
		JsonArray events = body.getAsJsonArray("events");
		assertEquals(1, events.size());
		JsonObject e0 = events.get(0).getAsJsonObject();
		assertEquals(4151, e0.get("itemId").getAsInt());
		assertEquals("buy", e0.get("side").getAsString());
		assertEquals(1_000_000, e0.get("price").getAsLong());
		assertEquals(2, e0.get("quantity").getAsInt());
		assertEquals(1720000000L, e0.get("ts").getAsLong()); // unix SECONDS on the crowd wire
		assertEquals(buy.clientId, e0.get("clientId").getAsString());
		assertFalse("the GE slot must never ride the crowd stream", e0.has("geSlot"));
		assertFalse(e0.has("slot"));
	}

	/** Recovered fills never qualify for the crowd stream (their ts is detection, not fill time). */
	@Test
	public void recoveredFillsAreNeverEnqueuedForCrowd()
	{
		SyncClient s = new SyncClient(null, new Gson());
		TradeRecord recovered = new TradeRecord(4151, TradeRecord.Side.BUY, 100, 1, 100, 2,
			1720000000000L, true, 1719990000000L);
		TradeRecord live = new TradeRecord(4151, TradeRecord.Side.BUY, 100, 1, 100, 2, 1720000000000L);
		s.enqueueCrowd(recovered);
		s.enqueueCrowd(live);
		assertEquals(1, s.crowdPendingCount());
	}

	@Test
	public void ignoreBodiesMatchThePluginDismissContract() // mirrors the server's parsePluginDismissBody
	{
		Dismissal d = new Dismissal(4151, 1720000000000L);
		JsonObject ignore = SyncClient.dismissalBody(new SyncClient.DismissalOp(d, false));
		assertEquals(4151, ignore.get("itemId").getAsInt());
		assertEquals(1720000000000L, ignore.get("ts").getAsLong());
		JsonObject undo = SyncClient.dismissalBody(new SyncClient.DismissalOp(d, true));
		assertEquals(4151, undo.get("itemId").getAsInt());
		assertFalse(undo.has("ts"));
	}

	@Test
	public void undoOfAnUnsentIgnoreCancelsBoth_undoOfASentIgnoreQueuesARestore()
	{
		SyncClient s = new SyncClient(null, new Gson());
		Dismissal queued = new Dismissal(4151, 1L);
		s.enqueueDismissal(queued);
		assertEquals(1, s.dismissalPendingCount());
		s.enqueueRestore(queued);
		assertEquals(0, s.dismissalPendingCount()); // never sent, so both cancel

		Dismissal alreadySent = new Dismissal(4151, 2L); // not in the queue: flushed earlier
		s.enqueueRestore(alreadySent);
		assertEquals(1, s.dismissalPendingCount());
		// A different ignore of the same item is not the one being undone.
		s.enqueueDismissal(new Dismissal(4151, 3L));
		s.enqueueRestore(new Dismissal(4151, 3L));
		assertEquals(3, s.dismissalPendingCount());
	}
}

package com.flipgoblin;

import com.google.gson.Gson;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Pins the /plugin/targets wire parse + the overlay's alert vocabulary. */
public class TargetsClientTest
{
	private final Gson gson = new Gson();

	@Test
	public void parsesTargetsWithAlerts()
	{
		String body = "{\"ok\":true,\"targets\":["
			+ "{\"itemId\":4151,\"watched\":true,\"alerts\":["
			+ "{\"metric\":\"bid\",\"op\":\"lte\",\"threshold\":1000000,\"enabled\":true},"
			+ "{\"metric\":\"roi\",\"op\":\"gte\",\"threshold\":250,\"enabled\":false}]},"
			+ "{\"itemId\":2,\"watched\":true,\"alerts\":[]}]}";
		Map<Integer, TargetsClient.Target> parsed = TargetsClient.parse(gson, body);
		assertNotNull(parsed);
		assertEquals(2, parsed.size());
		TargetsClient.Target whip = parsed.get(4151);
		assertTrue(whip.watched);
		assertEquals(2, whip.alerts.size());
		assertEquals("bid", whip.alerts.get(0).metric);
		assertEquals(1_000_000L, whip.alerts.get(0).threshold);
		assertTrue(whip.alerts.get(0).enabled);
		assertFalse(whip.alerts.get(1).enabled);
		assertTrue(parsed.get(2).alerts.isEmpty());
	}

	@Test
	public void malformedBodiesParseToNullNeverThrow()
	{
		assertNull(TargetsClient.parse(gson, "not json at all"));
		assertNull(TargetsClient.parse(gson, "{\"ok\":true}"));
		assertNull(TargetsClient.parse(gson, "{\"targets\":{\"a\":1}}"));
		assertNull(TargetsClient.parse(gson, "{\"targets\":[{\"noItemId\":1}]}"));
	}

	@Test
	public void alertLabelUsesTheSiteVocabulary()
	{
		// Thresholds are exact prices the user typed, never abbreviated back (ruling 2026-08-28).
		assertEquals("Buy ≤ 1,000,000",
			TargetsClient.alertLabel(new TargetsClient.TargetAlert("bid", "lte", 1_000_000, true)));
		assertEquals("Sell ≥ 250",
			TargetsClient.alertLabel(new TargetsClient.TargetAlert("ask", "gte", 250, true)));
		assertEquals("ROI ≥ 2.5%",
			TargetsClient.alertLabel(new TargetsClient.TargetAlert("roi", "gte", 250, true)));
		assertEquals("Margin ≥ 29,000",
			TargetsClient.alertLabel(new TargetsClient.TargetAlert("margin", "gte", 29_000, true)));
	}
}

package com.flipgoblin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/** Drives the gate through a real OkHttp client against a local HTTP server. */
public class UpdateGateTest
{
	private HttpServer server;
	private String base;
	private final AtomicInteger hits = new AtomicInteger();
	private final AtomicInteger status = new AtomicInteger(200);
	private final AtomicReference<String> seenVersion = new AtomicReference<>();
	private final StringBuilder bodies = new StringBuilder();

	@Before
	public void start() throws Exception
	{
		server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/", ex ->
		{
			hits.incrementAndGet();
			seenVersion.set(ex.getRequestHeaders().getFirst(UpdateGate.HEADER));
			synchronized (bodies)
			{
				bodies.append(new String(ex.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));
			}
			byte[] body = "{\"ok\":true}".getBytes(StandardCharsets.UTF_8);
			ex.sendResponseHeaders(status.get(), body.length);
			ex.getResponseBody().write(body);
			ex.close();
		});
		server.start();
		base = "http://127.0.0.1:" + server.getAddress().getPort();
	}

	@After
	public void stop()
	{
		server.stop(0);
	}

	private int get(OkHttpClient http, String url) throws Exception
	{
		try (Response r = http.newCall(new Request.Builder().url(url).build()).execute())
		{
			return r.code();
		}
	}

	@Test
	public void sendsTheVersionToOurApiOnly() throws Exception
	{
		UpdateGate gate = new UpdateGate("2026.10.06", base + "/", () -> { });
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(gate).build();
		assertEquals(200, get(http, base + "/plugin/me"));
		assertEquals("2026.10.06", seenVersion.get());

		UpdateGate other = new UpdateGate("2026.10.06", "https://flipgoblin-api.example", () -> { });
		OkHttpClient otherHttp = new OkHttpClient.Builder().addInterceptor(other).build();
		assertEquals(200, get(otherHttp, base + "/anything"));
		assertNull(seenVersion.get()); // not our API: no header
	}

	@Test
	public void a426PausesEveryLaterCallWithoutTheNetwork() throws Exception
	{
		AtomicInteger fired = new AtomicInteger();
		UpdateGate gate = new UpdateGate("2026.10.06", base, fired::incrementAndGet);
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(gate).build();
		status.set(426);
		assertEquals(426, get(http, base + "/plugin/flips"));
		assertTrue(gate.required());
		assertEquals(1, fired.get());
		int before = hits.get();
		status.set(200); // even if the server changed its mind, the session stays paused
		assertEquals(426, get(http, base + "/plugin/flips"));
		assertEquals(426, get(http, base + "/prices"));
		assertEquals(before, hits.get());
		assertEquals(1, fired.get());
	}

	@Test
	public void syncKeepsItsQueueOn426() throws Exception
	{
		UpdateGate gate = new UpdateGate("2026.10.06", base, () -> { });
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(gate).build();
		SyncClient sync = new SyncClient(http, new Gson());
		sync.enqueue(new TradeRecord(4151, TradeRecord.Side.BUY, 1_000_000, 1, 1_000_000, 0, 1720000000000L));
		status.set(426);
		assertFalse(sync.flush(base, "flipgoblin_test", "Char"));
		assertEquals(1, sync.pendingCount()); // held for after the update, never dropped
		status.set(400);
		UpdateGate fresh = new UpdateGate("2026.10.06", base, () -> { });
		SyncClient plain = new SyncClient(new OkHttpClient.Builder().addInterceptor(fresh).build(), new Gson());
		plain.enqueue(new TradeRecord(4151, TradeRecord.Side.BUY, 1_000_000, 1, 1_000_000, 0, 1720000000000L));
		plain.flush(base, "flipgoblin_test", "Char");
		assertEquals(0, plain.pendingCount()); // a real 400 still drops the bad batch
	}

	@Test
	public void heldTradesSyncAfterARestart() throws Exception
	{
		PendingTradesTest.MapStore store = new PendingTradesTest.MapStore();
		store.linked.add("A");
		PendingTrades saved = new PendingTrades(store, new Gson());

		// Old version: the server says update, so the fill is held and saved.
		UpdateGate oldGate = new UpdateGate("2026.10.06", base, () -> { });
		SyncClient old = new SyncClient(new OkHttpClient.Builder().addInterceptor(oldGate).build(), new Gson());
		old.claim("A");
		TradeRecord fill = new TradeRecord(4151, TradeRecord.Side.BUY, 1_000_000, 1, 1_000_000, 0, 1720000000000L);
		old.enqueue(fill);
		status.set(426);
		assertFalse(old.flush(base, "flipgoblin_test", "Char"));
		saved.save(old);

		// RuneLite restarts on the new version: a fresh client loads the saved fill and sends it.
		status.set(200);
		UpdateGate newGate = new UpdateGate("2026.10.07", base, () -> { });
		SyncClient fresh = new SyncClient(new OkHttpClient.Builder().addInterceptor(newGate).build(), new Gson());
		fresh.claim("A");
		saved.load(fresh);
		assertTrue(fresh.flush(base, "flipgoblin_test", "Char"));
		synchronized (bodies)
		{
			assertTrue(bodies.toString().contains(fill.clientId));
		}
		saved.save(fresh);
		assertNull(store.get("A"));
	}

	@Test
	public void rejectsForGood_onlyForBadRequests()
	{
		assertTrue(UpdateGate.rejectsForGood(400));
		assertTrue(UpdateGate.rejectsForGood(404));
		assertFalse(UpdateGate.rejectsForGood(401)); // token problem: hold
		assertFalse(UpdateGate.rejectsForGood(426)); // update needed: hold
		assertFalse(UpdateGate.rejectsForGood(429)); // rate limited: hold
		assertFalse(UpdateGate.rejectsForGood(503)); // server trouble: hold
		assertFalse(UpdateGate.rejectsForGood(200));
	}
}
